const MUSHAF = {"q":{"label":"رواية قالون عن نافع","ver":"KFGQPC Qaloon v10","suras":{"67":{"n":"الملك","j":29,"a":["تَبَٰرَكَ اَ۬لذِے بِيَدِهِ اِ۬لْمُلْكُ وَهْوَ عَلَىٰ كُلِّ شَےْءٖ قَدِيرٌۖ","اِ۬لذِے خَلَقَ اَ۬لْمَوْتَ وَالْحَيَوٰةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلاٗۖ وَهْوَ اَ۬لْعَزِيزُ اُ۬لْغَفُورُۖ","اُ۬لذِے خَلَقَ سَبْعَ سَمَٰوَٰتٖ طِبَاقاٗۖ مَّا تَرَىٰ فِے خَلْقِ اِ۬لرَّحْمَٰنِ مِن تَفَٰوُتٖۖ فَارْجِعِ اِ۬لْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٖۖ","ثُمَّ اَ۪رْجِعِ اِ۬لْبَصَرَ كَرَّتَيْنِ يَنقَلِبْ إِلَيْكَ اَ۬لْبَصَرُ خَاسِئاٗ وَهْوَ حَسِيرٞۖ","وَلَقَدْ زَيَّنَّا اَ۬لسَّمَآءَ اَ۬لدُّنْيَا بِمَصَٰبِيحَ وَجَعَلْنَٰهَا رُجُوماٗ لِّلشَّيَٰطِينِ وَأَعْتَدْنَا لَهُمْ عَذَابَ اَ۬لسَّعِيرِۖ","وَلِلذِينَ كَفَرُواْ بِرَبِّهِمْ عَذَابُ جَهَنَّمَۖ وَبِئْسَ اَ۬لْمَصِيرُۖ","إِذَا أُلْقُواْ فِيهَا سَمِعُواْ لَهَا شَهِيقاٗ وَهْيَ تَفُورُ","تَكَادُ تَمَيَّزُ مِنَ اَ۬لْغَيْظِۖ كُلَّمَا أُلْقِيَ فِيهَا فَوْجٞ سَأَلَهُمْ خَزَنَتُهَا أَلَمْ يَأْتِكُمْ نَذِيرٞۖ","قَالُواْ بَلَىٰ قَدْ جَآءَنَا نَذِيرٞ","فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ اَ۬للَّهُ مِن شَےْءٍ إِنْ أَنتُمْ إِلَّا فِے ضَلَٰلٖ كَبِيرٖۖ","وَقَالُواْ لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِے أَصْحَٰبِ اِ۬لسَّعِيرِۖ","فَاعْتَرَفُواْ بِذَنۢبِهِمْۖ فَسُحْقاٗ لِّأَصْحَٰبِ اِ۬لسَّعِيرِۖ","إِنَّ اَ۬لذِينَ يَخْشَوْنَ رَبَّهُم بِالْغَيْبِ لَهُم مَّغْفِرَةٞ وَأَجْرٞ كَبِيرٞۖ","وَأَسِرُّواْ قَوْلَكُمْ أَوِ اِ۪جْهَرُواْ بِهِۦۖ إِنَّهُۥ عَلِيمُۢ بِذَاتِ اِ۬لصُّدُورِۖ","أَلَا يَعْلَمُ مَنْ خَلَقَ وَهْوَ اَ۬للَّطِيفُ اُ۬لْخَبِيرُۖ","هُوَ اَ۬لذِے جَعَلَ لَكُمُ اُ۬لْأَرْضَ ذَلُولاٗ فَامْشُواْ فِے مَنَاكِبِهَا وَكُلُواْ مِن رِّزْقِهِۦۖ وَإِلَيْهِ اِ۬لنُّشُورُۖ","ءَٰا۬مِنتُم مَّن فِے اِ۬لسَّمَآءِ اَ۬نْ يَّخْسِفَ بِكُمُ اُ۬لْأَرْضَ فَإِذَا هِيَ تَمُورُۖ","أَمْ أَمِنتُم مَّن فِے اِ۬لسَّمَآءِ اَ۬نْ يُّرْسِلَ عَلَيْكُمْ حَاصِباٗۖ فَسَتَعْلَمُونَ كَيْفَ نَذِيرِۖ","وَلَقَدْ كَذَّبَ اَ۬لذِينَ مِن قَبْلِهِمْۖ فَكَيْفَ كَانَ نَكِيرِۖ","أَوَلَمْ يَرَوْاْ إِلَى اَ۬لطَّيْرِ فَوْقَهُمْ صَٰٓفَّٰتٖ وَيَقْبِضْنَۖ مَا يُمْسِكُهُنَّ إِلَّا اَ۬لرَّحْمَٰنُۖ إِنَّهُۥ بِكُلِّ شَےْءِۢ بَصِيرٌۖ","أَمَّنْ هَٰذَا اَ۬لذِے هُوَ جُندٞ لَّكُمْ يَنصُرُكُم مِّن دُونِ اِ۬لرَّحْمَٰنِۖ إِنِ اِ۬لْكَٰفِرُونَ إِلَّا فِے غُرُورٍۖ","أَمَّنْ هَٰذَا اَ۬لذِے يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُۥۖ بَل لَّجُّواْ فِے عُتُوّٖ وَنُفُورٍۖ","أَفَمَنْ يَّمْشِے مُكِبّاً عَلَىٰ وَجْهِهِۦ أَهْدَىٰ أَمَّنْ يَّمْشِے سَوِيّاً عَلَىٰ صِرَٰطٖ مُّسْتَقِيمٖۖ","قُلْ هُوَ اَ۬لذِے أَنشَأَكُمْ وَجَعَلَ لَكُمُ اُ۬لسَّمْعَ وَالْأَبْصَٰرَ وَالْأَفْـِٕدَةَۖ قَلِيلاٗ مَّا تَشْكُرُونَۖ","قُلْ هُوَ اَ۬لذِے ذَرَأَكُمْ فِے اِ۬لْأَرْضِ وَإِلَيْهِ تُحْشَرُونَۖ","وَيَقُولُونَ مَتَىٰ هَٰذَا اَ۬لْوَعْدُ إِن كُنتُمْ صَٰدِقِينَۖ","قُلْ إِنَّمَا اَ۬لْعِلْمُ عِندَ اَ۬للَّهِ وَإِنَّمَا أَنَا نَذِيرٞ مُّبِينٞۖ","فَلَمَّا رَأَوْهُ زُلْفَةٗ س۬يَٓٔتْ وُجُوهُ اُ۬لذِينَ كَفَرُواْ وَقِيلَ هَٰذَا اَ۬لذِے كُنتُم بِهِۦ تَدَّعُونَۖ","قُلْ أَرَٰ۬يْتُمْ إِنْ أَهْلَكَنِيَ اَ۬للَّهُ وَمَن مَّعِيَ أَوْ رَحِمَنَا فَمَنْ يُّجِيرُ اُ۬لْكَٰفِرِينَ مِنْ عَذَابٍ أَلِيمٖۖ","قُلْ هُوَ اَ۬لرَّحْمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيْهِ تَوَكَّلْنَاۖ فَسَتَعْلَمُونَ مَنْ هُوَ فِے ضَلَٰلٖ مُّبِينٖۖ","قُلْ أَرَٰ۬يْتُمْ إِنْ أَصْبَحَ مَآؤُكُمْ غَوْراٗ فَمَنْ يَّأْتِيكُم بِمَآءٖ مَّعِينِۢۖ"]},"68":{"n":"القلم","j":29,"a":["نُٓۖ وَالْقَلَمِ وَمَا يَسْطُرُونَ","مَا أَنتَ بِنِعْمَةِ رَبِّكَ بِمَجْنُونٖ","وَإِنَّ لَكَ لَأَجْراً غَيْرَ مَمْنُونٖ","وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٖۖ","فَسَتُبْصِرُ وَيُبْصِرُونَ","بِأَييِّكُمُ اُ۬لْمَفْتُونُۖ","إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦۖ وَهْوَ أَعْلَمُ بِالْمُهْتَدِينَۖ","فَلَا تُطِعِ اِ۬لْمُكَذِّبِينَۖ","وَدُّواْ لَوْ تُدْهِنُ فَيُدْهِنُونَۖ","وَلَا تُطِعْ كُلَّ حَلَّٰفٖ مَّهِينٍ","هَمَّازٖ مَّشَّآءِۢ بِنَمِيمٖ","مَّنَّاعٖ لِّلْخَيْرِ مُعْتَدٍ أَثِيمٍ","عُتُلِّۢ بَعْدَ ذَٰلِكَ زَنِيمٍ","أَن كَانَ ذَا مَالٖ وَبَنِينَ","إِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ اُ۬لْأَوَّلِينَۖ","سَنَسِمُهُۥ عَلَى اَ۬لْخُرْطُومِۖ","إِنَّا بَلَوْنَٰهُمْ كَمَا بَلَوْنَا أَصْحَٰبَ اَ۬لْجَنَّةِ إِذْ أَقْسَمُواْ لَيَصْرِمُنَّهَا مُصْبِحِينَ","وَلَا يَسْتَثْنُونَۖ","فَطَافَ عَلَيْهَا طَآئِفٞ مِّن رَّبِّكَ وَهُمْ نَآئِمُونَ","فَأَصْبَحَتْ كَالصَّرِيمِۖ","فَتَنَادَوْاْ مُصْبِحِينَ","أَنُ اُ۟غْدُواْ عَلَىٰ حَرْثِكُمْ إِن كُنتُمْ صَٰرِمِينَۖ","فَانطَلَقُواْ وَهُمْ يَتَخَٰفَتُونَ","أَن لَّا يَدْخُلَنَّهَا اَ۬لْيَوْمَ عَلَيْكُم مِّسْكِينٞۖ","وَغَدَوْاْ عَلَىٰ حَرْدٖ قَٰدِرِينَۖ","فَلَمَّا رَأَوْهَا قَالُواْ إِنَّا لَضَآلُّونَ","بَلْ نَحْنُ مَحْرُومُونَۖ","قَالَ أَوْسَطُهُمْ أَلَمْ أَقُل لَّكُمْ لَوْلَا تُسَبِّحُونَۖ","قَالُواْ سُبْحَٰنَ رَبِّنَا إِنَّا كُنَّا ظَٰلِمِينَۖ","فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٖ يَتَلَٰوَمُونَۖ","قَالُواْ يَٰوَيْلَنَا إِنَّا كُنَّا طَٰغِينَ","عَسَىٰ رَبُّنَا أَنْ يُّبَدِّلَنَا خَيْراٗ مِّنْهَا إِنَّا إِلَىٰ رَبِّنَا رَٰغِبُونَۖ","كَذَٰلِكَ اَ۬لْعَذَابُۖ وَلَعَذَابُ اُ۬لْأٓخِرَةِ أَكْبَرُۖ لَوْ كَانُواْ يَعْلَمُونَۖ","إِنَّ لِلْمُتَّقِينَ عِندَ رَبِّهِمْ جَنَّٰتِ اِ۬لنَّعِيمِۖ","أَفَنَجْعَلُ اُ۬لْمُسْلِمِينَ كَالْمُجْرِمِينَۖ","مَا لَكُمْۖ كَيْفَ تَحْكُمُونَۖ","أَمْ لَكُمْ كِتَٰبٞ فِيهِ تَدْرُسُونَ","إِنَّ لَكُمْ فِيهِ لَمَا تَخَيَّرُونَۖ","أَمْ لَكُمْ أَيْمَٰنٌ عَلَيْنَا بَٰلِغَةٌ إِلَىٰ يَوْمِ اِ۬لْقِيَٰمَةِ إِنَّ لَكُمْ لَمَا تَحْكُمُونَۖ","سَلْهُمْ أَيُّهُم بِذَٰلِكَ زَعِيمٌۖ","أَمْ لَهُمْ شُرَكَآءُ فَلْيَأْتُواْ بِشُرَكَآئِهِمْ إِن كَانُواْ صَٰدِقِينَۖ","يَوْمَ يُكْشَفُ عَن سَاقٖ وَيُدْعَوْنَ إِلَى اَ۬لسُّجُودِ فَلَا يَسْتَطِيعُونَۖ","خَٰشِعَةً أَبْصَٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٞۖ وَقَدْ كَانُواْ يُدْعَوْنَ إِلَى اَ۬لسُّجُودِ وَهُمْ سَٰلِمُونَۖ","فَذَرْنِے وَمَنْ يُّكَذِّبُ بِهَٰذَا اَ۬لْحَدِيثِۖ سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ","وَأُمْلِے لَهُمْۖ إِنَّ كَيْدِے مَتِينٌۖ","أَمْ تَسْـَٔلُهُمْ أَجْراٗ فَهُم مِّن مَّغْرَمٖ مُّثْقَلُونَۖ","أَمْ عِندَهُمُ اُ۬لْغَيْبُ فَهُمْ يَكْتُبُونَۖ","فَاصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تَكُن كَصَٰحِبِ اِ۬لْحُوتِ إِذْ نَادَىٰ وَهْوَ مَكْظُومٞۖ","لَّوْلَا أَن تَدَٰرَكَهُۥ نِعْمَةٞ مِّن رَّبِّهِۦ لَنُبِذَ بِالْعَرَآءِ وَهْوَ مَذْمُومٞۖ","فَاجْتَبَٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ اَ۬لصَّٰلِحِينَۖ","وَإِنْ يَّكَادُ اُ۬لذِينَ كَفَرُواْ لَيَزْلِقُونَكَ بِأَبْصَٰرِهِمْ لَمَّا سَمِعُواْ اُ۬لذِّكْرَ وَيَقُولُونَ إِنَّهُۥ لَمَجْنُونٞۖ","وَمَا هُوَ إِلَّا ذِكْرٞ لِّلْعَٰلَمِينَۖ"]},"69":{"n":"الحاقة","j":29,"a":["اِ۬لْحَآقَّةُ مَا اَ۬لْحَآقَّةُۖ","وَمَا أَدْرَيٰكَ مَا اَ۬لْحَآقَّةُۖ","كَذَّبَتْ ثَمُودُ وَعَادُۢ بِالْقَارِعَةِۖ","فَأَمَّا ثَمُودُ فَأُهْلِكُواْ بِالطَّاغِيَةِۖ","وَأَمَّا عَادٞ فَأُهْلِكُواْ بِرِيحٖ صَرْصَرٍ عَاتِيَةٖ","سَخَّرَهَا عَلَيْهِمْ سَبْعَ لَيَالٖ وَثَمَٰنِيَةَ أَيَّامٍ حُسُوماٗۖ فَتَرَى اَ۬لْقَوْمَ فِيهَا صَرْعَىٰ كَأَنَّهُمْ أَعْجَازُ نَخْلٍ خَاوِيَةٖۖ","فَهَلْ تَرَىٰ لَهُم مِّنۢ بَاقِيَةٖۖ","وَجَآءَ فِرْعَوْنُ وَمَن قَبْلَهُۥ وَالْمُؤْتَفِكَٰتُ بِالْخَاطِئَةِ","فَعَصَوْاْ رَسُولَ رَبِّهِمْ فَأَخَذَهُمْ أَخْذَةٗ رَّابِيَةًۖ","إِنَّا لَمَّا طَغَا اَ۬لْمَآءُ حَمَلْنَٰكُمْ فِے اِ۬لْجَارِيَةِ","لِنَجْعَلَهَا لَكُمْ تَذْكِرَةٗ وَتَعِيَهَا أُذْنٞ وَٰعِيَةٞۖ","فَإِذَا نُفِخَ فِے اِ۬لصُّورِ نَفْخَةٞ وَٰحِدَةٞ","وَحُمِلَتِ اِ۬لْأَرْضُ وَالْجِبَالُ فَدُكَّتَا دَكَّةٗ وَٰحِدَةٗ","فَيَوْمَئِذٖ وَقَعَتِ اِ۬لْوَاقِعَةُ","وَانشَقَّتِ اِ۬لسَّمَآءُ فَهْيَ يَوْمَئِذٖ وَاهِيَةٞ","وَالْمَلَكُ عَلَىٰ أَرْجَآئِهَاۖ وَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَئِذٖ ثَمَٰنِيَةٞ","يَوْمَئِذٖ تُعْرَضُونَ لَا تَخْفَىٰ مِنكُمْ خَافِيَةٞۖ","فَأَمَّا مَنْ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَيَقُولُ هَآؤُمُ اُ۪قْرَءُواْ كِتَٰبِيَهْۖ","إِنِّے ظَنَنتُ أَنِّے مُلَٰقٍ حِسَابِيَهْۖ","فَهْوَ فِے عِيشَةٖ رَّاضِيَةٖ","فِے جَنَّةٍ عَالِيَةٖ","قُطُوفُهَا دَانِيَةٞۖ","كُلُواْ وَاشْرَبُواْۖ هَنِيٓـٔاَۢ بِمَا أَسْلَفْتُمْ فِے اِ۬لْأَيَّامِ اِ۬لْخَالِيَةِۖ","وَأَمَّا مَنْ أُوتِيَ كِتَٰبَهُۥ بِشِمَالِهِۦ","فَيَقُولُ يَٰلَيْتَنِے لَمْ أُوتَ كِتَٰبِيَهْۖ","وَلَمْ أَدْرِ مَا حِسَابِيَهْۖ","يَٰلَيْتَهَا كَانَتِ اِ۬لْقَاضِيَةَ","مَا أَغْنَىٰ عَنِّے مَالِيَهۖ","هَّلَكَ عَنِّے سُلْطَٰنِيَهْۖ","خُذُوهُ فَغُلُّوهُ","ثُمَّ اَ۬لْجَحِيمَ صَلُّوهُ","ثُمَّ فِے سِلْسِلَةٖ ذَرْعُهَا سَبْعُونَ ذِرَاعاٗ فَاسْلُكُوهُۖ","إِنَّهُۥ كَانَ لَا يُؤْمِنُ بِاللَّهِ اِ۬لْعَظِيمِ","وَلَا يَحُضُّ عَلَىٰ طَعَامِ اِ۬لْمِسْكِينِۖ","فَلَيْسَ لَهُ اُ۬لْيَوْمَ هَٰهُنَا حَمِيمٞ","وَلَا طَعَامٌ إِلَّا مِنْ غِسْلِينٖ","لَّا يَأْكُلُهُۥ إِلَّا اَ۬لْخَٰطِـُٔونَۖ","فَلَا أُقْسِمُ بِمَا تُبْصِرُونَ","وَمَا لَا تُبْصِرُونَ","إِنَّهُۥ لَقَوْلُ رَسُولٖ كَرِيمٖ","وَمَا هُوَ بِقَوْلِ شَاعِرٖ قَلِيلاٗ مَّا تُؤْمِنُونَ","وَلَا بِقَوْلِ كَاهِنٖۖ قَلِيلاٗ مَّا تَذَّكَّرُونَۖ","تَنزِيلٞ مِّن رَّبِّ اِ۬لْعَٰلَمِينَۖ","وَلَوْ تَقَوَّلَ عَلَيْنَا بَعْضَ اَ۬لْأَقَاوِيلِ","لَأَخَذْنَا مِنْهُ بِالْيَمِينِ","ثُمَّ لَقَطَعْنَا مِنْهُ اُ۬لْوَتِينَ","فَمَا مِنكُم مِّنْ أَحَدٍ عَنْهُ حَٰجِزِينَۖ","وَإِنَّهُۥ لَتَذْكِرَةٞ لِّلْمُتَّقِينَۖ","وَإِنَّا لَنَعْلَمُ أَنَّ مِنكُم مُّكَذِّبِينَۖ","وَإِنَّهُۥ لَحَسْرَةٌ عَلَى اَ۬لْكَٰفِرِينَۖ","وَإِنَّهُۥ لَحَقُّ اُ۬لْيَقِينِۖ","فَسَبِّحْ بِاسْمِ رَبِّكَ اَ۬لْعَظِيمِۖ"]},"70":{"n":"المعارج","j":29,"a":["سَالَ سَآئِلُۢ بِعَذَابٖ وَاقِعٖ","لِّلْكَٰفِرِينَ لَيْسَ لَهُۥ دَافِعٞ","مِّنَ اَ۬للَّهِ ذِے اِ۬لْمَعَارِجِۖ","تَعْرُجُ اُ۬لْمَلَٰٓئِكَةُ وَالرُّوحُ إِلَيْهِ فِے يَوْمٖ كَانَ مِقْدَارُهُۥ خَمْسِينَ أَلْفَ سَنَةٖۖ","فَاصْبِرْ صَبْراٗ جَمِيلاًۖ","إِنَّهُمْ يَرَوْنَهُۥ بَعِيداٗ","وَنَرَيٰهُ قَرِيباٗۖ","يَوْمَ تَكُونُ اُ۬لسَّمَآءُ كَالْمُهْلِ","وَتَكُونُ اُ۬لْجِبَالُ كَالْعِهْنِ","وَلَا يَسْـَٔلُ حَمِيمٌ حَمِيماٗ","يُبَصَّرُونَهُمْۖ يَوَدُّ اُ۬لْمُجْرِمُ لَوْ يَفْتَدِے مِنْ عَذَابِ يَوْمَئِذِۢ بِبَنِيهِ","وَصَٰحِبَتِهِۦ وَأَخِيهِ","وَفَصِيلَتِهِ اِ۬لتِے تُـْٔوِيهِ","وَمَن فِے اِ۬لْأَرْضِ جَمِيعاٗ ثُمَّ يُنجِيهِ","كَلَّاۖ إِنَّهَا لَظَىٰ","نَزَّاعَةٞ لِّلشَّوَىٰ","تَدْعُواْ مَنْ أَدْبَرَ وَتَوَلَّىٰ","وَجَمَعَ فَأَوْعَىٰۖ","إِنَّ اَ۬لْإِنسَٰنَ خُلِقَ هَلُوعاً","إِذَا مَسَّهُ اُ۬لشَّرُّ جَزُوعاٗ","وَإِذَا مَسَّهُ اُ۬لْخَيْرُ مَنُوعاً","إِلَّا اَ۬لْمُصَلِّينَ","اَ۬لذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ دَآئِمُونَۖ","وَالذِينَ فِے أَمْوَٰلِهِمْ حَقّٞ مَّعْلُومٞ","لِّلسَّآئِلِ وَالْمَحْرُومِۖ","وَالذِينَ يُصَدِّقُونَ بِيَوْمِ اِ۬لدِّينِۖ","وَالذِينَ هُم مِّنْ عَذَابِ رَبِّهِم مُّشْفِقُونَ","إِنَّ عَذَابَ رَبِّهِمْ غَيْرُ مَأْمُونٖۖ","وَالذِينَ هُمْ لِفُرُوجِهِمْ حَٰفِظُونَ","إِلَّا عَلَىٰ أَزْوَٰجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَٰنُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَۖ","فَمَنِ اِ۪بْتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ اُ۬لْعَادُونَۖ","وَالذِينَ هُمْ لِأَمَٰنَٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَۖ","وَالذِينَ هُم بِشَهَٰدَتِهِمْ قَآئِمُونَۖ","وَالذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ","أُوْلَٰٓئِكَ فِے جَنَّٰتٖ مُّكْرَمُونَۖ","فَمَالِ اِ۬لذِينَ كَفَرُواْ قِبَلَكَ مُهْطِعِينَ","عَنِ اِ۬لْيَمِينِ وَعَنِ اِ۬لشِّمَالِ عِزِينَۖ","أَيَطْمَعُ كُلُّ اُ۪مْرِےٕٖ مِّنْهُمْ أَنْ يُّدْخَلَ جَنَّةَ نَعِيمٖ","كَلَّاۖ إِنَّا خَلَقْنَٰهُم مِّمَّا يَعْلَمُونَۖ","فَلَا أُقْسِمُ بِرَبِّ اِ۬لْمَشَٰرِقِ وَالْمَغَٰرِبِ إِنَّا لَقَٰدِرُونَ","عَلَىٰ أَن نُّبَدِّلَ خَيْراٗ مِّنْهُمْ وَمَا نَحْنُ بِمَسْبُوقِينَۖ","فَذَرْهُمْ يَخُوضُواْ وَيَلْعَبُواْ حَتَّىٰ يُلَٰقُواْ يَوْمَهُمُ اُ۬لذِے يُوعَدُونَ","يَوْمَ يَخْرُجُونَ مِنَ اَ۬لْأَجْدَاثِ سِرَاعاٗ كَأَنَّهُمْ إِلَىٰ نَصْبٖ يُوفِضُونَ","خَٰشِعَةً أَبْصَٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٞۖ ذَٰلِكَ اَ۬لْيَوْمُ اُ۬لذِے كَانُواْ يُوعَدُونَۖ"]},"71":{"n":"نوح","j":29,"a":["إِنَّا أَرْسَلْنَا نُوحاً إِلَىٰ قَوْمِهِۦ أَنْ أَنذِرْ قَوْمَكَ مِن قَبْلِ أَنْ يَّأْتِيَهُمْ عَذَابٌ أَلِيمٞۖ","قَالَ يَٰقَوْمِ إِنِّے لَكُمْ نَذِيرٞ مُّبِينٌ","أَنُ اُ۟عْبُدُواْ اُ۬للَّهَ وَاتَّقُوهُ وَأَطِيعُونِ","يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرْكُمْ إِلَىٰ أَجَلٖ مُّسَمّىًۖ إِنَّ أَجَلَ اَ۬للَّهِ إِذَا جَآءَ لَا يُؤَخَّرُۖ لَوْ كُنتُمْ تَعْلَمُونَۖ","قَالَ رَبِّ إِنِّے دَعَوْتُ قَوْمِے لَيْلاٗ وَنَهَاراٗ","فَلَمْ يَزِدْهُمْ دُعَآءِيَ إِلَّا فِرَاراٗۖ","وَإِنِّے كُلَّمَا دَعَوْتُهُمْ لِتَغْفِرَ لَهُمْ جَعَلُواْ أَصَٰبِعَهُمْ فِے ءَاذَانِهِمْ وَاسْتَغْشَوْاْ ثِيَابَهُمْ وَأَصَرُّواْ وَاسْتَكْبَرُواْ اُ۪سْتِكْبَاراٗۖ","ثُمَّ إِنِّے دَعَوْتُهُمْ جِهَاراٗۖ","ثُمَّ إِنِّيَ أَعْلَنتُ لَهُمْ وَأَسْرَرْتُ لَهُمْ إِسْرَاراٗ","فَقُلْتُ اُ۪سْتَغْفِرُواْ رَبَّكُمْ إِنَّهُۥ كَانَ غَفَّاراٗ","يُرْسِلِ اِ۬لسَّمَآءَ عَلَيْكُم مِّدْرَاراٗ","وَيُمْدِدْكُم بِأَمْوَٰلٖ وَبَنِينَ وَيَجْعَل لَّكُمْ جَنَّٰتٖ وَيَجْعَل لَّكُمْ أَنْهَٰراٗۖ","مَّا لَكُمْ لَا تَرْجُونَ لِلهِ وَقَاراٗ","وَقَدْ خَلَقَكُمْ أَطْوَاراًۖ","أَلَمْ تَرَوْاْ كَيْفَ خَلَقَ اَ۬للَّهُ سَبْعَ سَمَٰوَٰتٖ طِبَاقاٗ","وَجَعَلَ اَ۬لْقَمَرَ فِيهِنَّ نُوراٗ وَجَعَلَ اَ۬لشَّمْسَ سِرَاجاٗۖ","وَاللَّهُ أَنۢبَتَكُم مِّنَ اَ۬لْأَرْضِ نَبَاتاٗ","ثُمَّ يُعِيدُكُمْ فِيهَا وَيُخْرِجُكُمْ إِخْرَاجاٗۖ","وَاللَّهُ جَعَلَ لَكُمُ اُ۬لْأَرْضَ بِسَاطاٗ","لِّتَسْلُكُواْ مِنْهَا سُبُلاٗ فِجَاجاٗۖ","قَالَ نُوحٞ رَّبِّ إِنَّهُمْ عَصَوْنِے وَاتَّبَعُواْ مَن لَّمْ يَزِدْهُ مَالُهُۥ وَوَلَدُهُۥ إِلَّا خَسَاراٗ","وَمَكَرُواْ مَكْراٗ كُبَّاراٗۖ","وَقَالُواْ لَا تَذَرُنَّ ءَالِهَتَكُمْ وَلَا تَذَرُنَّ وُدّاٗ وَلَا سُوَاعاٗ","وَلَا يَغُوثَ وَيَعُوقَ وَنَسْراٗۖ","وَقَدْ أَضَلُّواْ كَثِيراٗۖ وَلَا تَزِدِ اِ۬لظَّٰلِمِينَ إِلَّا ضَلَٰلاٗۖ","مِّمَّا خَطِيٓـَٰٔتِهِمْ أُغْرِقُواْ فَأُدْخِلُواْ نَاراٗ","فَلَمْ يَجِدُواْ لَهُم مِّن دُونِ اِ۬للَّهِ أَنصَاراٗۖ","وَقَالَ نُوحٞ رَّبِّ لَا تَذَرْ عَلَى اَ۬لْأَرْضِ مِنَ اَ۬لْكَٰفِرِينَ دَيَّاراًۖ","إِنَّكَ إِن تَذَرْهُمْ يُضِلُّواْ عِبَادَكَ وَلَا يَلِدُواْ إِلَّا فَاجِراٗ كَفَّاراٗۖ","رَّبِّ اِ۪غْفِرْ لِے وَلِوَٰلِدَيَّ وَلِمَن دَخَلَ بَيْتِے مُؤْمِناٗ وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَٰتِۖ وَلَا تَزِدِ اِ۬لظَّٰلِمِينَ إِلَّا تَبَاراَۢۖ"]},"72":{"n":"الجن","j":29,"a":["قُلْ أُوحِيَ إِلَيَّ أَنَّهُ اُ۪سْتَمَعَ نَفَرٞ مِّنَ اَ۬لْجِنِّ فَقَالُواْ إِنَّا سَمِعْنَا قُرْءَاناً عَجَباٗ","يَهْدِے إِلَى اَ۬لرُّشْدِ فَـَٔامَنَّا بِهِۦ وَلَن نُّشْرِكَ بِرَبِّنَا أَحَداٗۖ","وَإِنَّهُۥ تَعَٰلَىٰ جَدُّ رَبِّنَا مَا اَ۪تَّخَذَ صَٰحِبَةٗ وَلَا وَلَداٗۖ","وَإِنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى اَ۬للَّهِ شَطَطاٗۖ","وَإِنَّا ظَنَنَّا أَن لَّن تَقُولَ اَ۬لْإِنسُ وَالْجِنُّ عَلَى اَ۬للَّهِ كَذِباٗۖ","وَإِنَّهُۥ كَانَ رِجَالٞ مِّنَ اَ۬لْإِنسِ يَعُوذُونَ بِرِجَالٖ مِّنَ اَ۬لْجِنِّ فَزَادُوهُمْ رَهَقاٗۖ","وَإِنَّهُمْ ظَنُّواْ كَمَا ظَنَنتُمْ أَن لَّنْ يَّبْعَثَ اَ۬للَّهُ أَحَداٗۖ","وَإِنَّا لَمَسْنَا اَ۬لسَّمَآءَ فَوَجَدْنَٰهَا مُلِئَتْ حَرَساٗ شَدِيداٗ وَشُهُباٗۖ","وَإِنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَٰعِدَ لِلسَّمْعِ فَمَنْ يَّسْتَمِعِ اِ۬لْأٓنَ يَجِدْ لَهُۥ شِهَاباٗ رَّصَداٗۖ","وَإِنَّا لَا نَدْرِے أَشَرٌّ أُرِيدَ بِمَن فِے اِ۬لْأَرْضِ أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَداٗۖ","وَإِنَّا مِنَّا اَ۬لصَّٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَۖ كُنَّا طَرَآئِقَ قِدَداٗۖ","وَإِنَّا ظَنَنَّا أَن لَّن نُّعْجِزَ اَ۬للَّهَ فِے اِ۬لْأَرْضِ وَلَن نُّعْجِزَهُۥ هَرَباٗۖ","وَإِنَّا لَمَّا سَمِعْنَا اَ۬لْهُدَىٰ ءَامَنَّا بِهِۦۖ فَمَنْ يُّؤْمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخْساٗ وَلَا رَهَقاٗۖ","وَإِنَّا مِنَّا اَ۬لْمُسْلِمُونَ وَمِنَّا اَ۬لْقَٰسِطُونَۖ فَمَنْ أَسْلَمَ فَأُوْلَٰٓئِكَ تَحَرَّوْاْ رَشَداٗۖ","وَأَمَّا اَ۬لْقَٰسِطُونَ فَكَانُواْ لِجَهَنَّمَ حَطَباٗۖ","وَأَن لَّوِ اِ۪سْتَقَٰمُواْ عَلَى اَ۬لطَّرِيقَةِ لَأَسْقَيْنَٰهُم مَّآءً غَدَقاٗ","لِّنَفْتِنَهُمْ فِيهِۖ وَمَنْ يُّعْرِضْ عَن ذِكْرِ رَبِّهِۦ نَسْلُكْهُ عَذَاباٗ صَعَداٗۖ","وَأَنَّ اَ۬لْمَسَٰجِدَ لِلهِ فَلَا تَدْعُواْ مَعَ اَ۬للَّهِ أَحَداٗۖ","وَإِنَّهُۥ لَمَّا قَامَ عَبْدُ اُ۬للَّهِ يَدْعُوهُ كَادُواْ يَكُونُونَ عَلَيْهِ لِبَداٗۖ","قَالَ إِنَّمَا أَدْعُواْ رَبِّے وَلَا أُشْرِكُ بِهِۦ أَحَداٗۖ","قُلْ إِنِّے لَا أَمْلِكُ لَكُمْ ضَرّاٗ وَلَا رَشَداٗۖ","قُلْ إِنِّے لَنْ يُّجِيرَنِے مِنَ اَ۬للَّهِ أَحَدٞ وَلَنْ أَجِدَ مِن دُونِهِۦ مُلْتَحَداً","إِلَّا بَلَٰغاٗ مِّنَ اَ۬للَّهِ وَرِسَٰلَٰتِهِۦۖ وَمَنْ يَّعْصِ اِ۬للَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَا أَبَداًۖ","حَتَّىٰ إِذَا رَأَوْاْ مَا يُوعَدُونَ فَسَيَعْلَمُونَ مَنْ أَضْعَفُ نَاصِراٗ وَأَقَلُّ عَدَداٗۖ","قُلْ إِنْ أَدْرِے أَقَرِيبٞ مَّا تُوعَدُونَ أَمْ يَجْعَلُ لَهُۥ رَبِّيَ أَمَداًۖ","عَٰلِمُ اُ۬لْغَيْبِ فَلَا يُظْهِرُ عَلَىٰ غَيْبِهِۦ أَحَداً","إِلَّا مَنِ اِ۪رْتَضَىٰ مِن رَّسُولٖ فَإِنَّهُۥ يَسْلُكُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ رَصَداٗ","لِّيَعْلَمَ أَن قَدْ أَبْلَغُواْ رِسَٰلَٰتِ رَبِّهِمْ وَأَحَاطَ بِمَا لَدَيْهِمْ وَأَحْصَىٰ كُلَّ شَےْءٍ عَدَداَۢۖ"]},"73":{"n":"المزمل","j":29,"a":["يَٰأَيُّهَا اَ۬لْمُزَّمِّلُ قُمِ اِ۬ليْلَ إِلَّا قَلِيلاٗ","نِّصْفَهُۥ أَوُ اُ۟نقُصْ مِنْهُ قَلِيلاً","أَوْ زِدْ عَلَيْهِ وَرَتِّلِ اِ۬لْقُرْءَانَ تَرْتِيلاًۖ","إِنَّا سَنُلْقِے عَلَيْكَ قَوْلاٗ ثَقِيلاًۖ","إِنَّ نَاشِئَةَ اَ۬ليْلِ هِيَ أَشَدُّ وَطْـٔاٗ وَأَقْوَمُ قِيلاًۖ","إِنَّ لَكَ فِے اِ۬لنَّهَارِ سَبْحاٗ طَوِيلاٗۖ","وَاذْكُرِ اِ۪سْمَ رَبِّكَ وَتَبَتَّلْ إِلَيْهِ تَبْتِيلاٗۖ","رَّبُّ اُ۬لْمَشْرِقِ وَالْمَغْرِبِۖ لَا إِلَٰهَ إِلَّا هُوَۖ فَاتَّخِذْهُ وَكِيلاٗۖ","وَاصْبِرْ عَلَىٰ مَا يَقُولُونَۖ وَاهْجُرْهُمْ هَجْراٗ جَمِيلاٗۖ","وَذَرْنِے وَالْمُكَذِّبِينَ أُوْلِے اِ۬لنَّعْمَةِ وَمَهِّلْهُمْ قَلِيلاًۖ","إِنَّ لَدَيْنَا أَنكَالاٗ وَجَحِيماٗ","وَطَعَاماٗ ذَا غُصَّةٖ وَعَذَاباً أَلِيماٗ","يَوْمَ تَرْجُفُ اُ۬لْأَرْضُ وَالْجِبَالُ وَكَانَتِ اِ۬لْجِبَالُ كَثِيباٗ مَّهِيلاًۖ","إِنَّا أَرْسَلْنَا إِلَيْكُمْ رَسُولاٗ شَٰهِداً عَلَيْكُمْ كَمَا أَرْسَلْنَا إِلَىٰ فِرْعَوْنَ رَسُولاٗ","فَعَصَىٰ فِرْعَوْنُ اُ۬لرَّسُولَ فَأَخَذْنَٰهُ أَخْذاٗ وَبِيلاٗۖ","فَكَيْفَ تَتَّقُونَ إِن كَفَرْتُمْ يَوْماٗ يَجْعَلُ اُ۬لْوِلْدَٰنَ شِيباً اِ۬لسَّمَآءُ مُنفَطِرُۢ بِهِۦۖ كَانَ وَعْدُهُۥ مَفْعُولاًۖ","إِنَّ هَٰذِهِۦ تَذْكِرَةٞۖ فَمَن شَآءَ اَ۪تَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلاًۖ","إِنَّ رَبَّكَ يَعْلَمُ أَنَّكَ تَقُومُ أَدْنَىٰ مِن ثُلُثَيِ اِ۬ليْلِ وَنِصْفِهِۦ وَثُلُثِهِۦ وَطَآئِفَةٞ مِّنَ اَ۬لذِينَ مَعَكَۖ وَاللَّهُ يُقَدِّرُ اُ۬ليْلَ وَالنَّهَارَۖ عَلِمَ أَن لَّن تُحْصُوهُ فَتَابَ عَلَيْكُمْۖ فَاقْرَءُواْ مَا تَيَسَّرَ مِنَ اَ۬لْقُرْءَانِۖ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرْضَىٰ وَءَاخَرُونَ يَضْرِبُونَ فِے اِ۬لْأَرْضِ يَبْتَغُونَ مِن فَضْلِ اِ۬للَّهِ وَءَاخَرُونَ يُقَٰتِلُونَ فِے سَبِيلِ اِ۬للَّهِۖ فَاقْرَءُواْ مَا تَيَسَّرَ مِنْهُۖ وَأَقِيمُواْ اُ۬لصَّلَوٰةَ وَءَاتُواْ اُ۬لزَّكَوٰةَۖ وَأَقْرِضُواْ اُ۬للَّهَ قَرْضاً حَسَناٗۖ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنْ خَيْرٖ تَجِدُوهُ عِندَ اَ۬للَّهِ هُوَ خَيْراٗ وَأَعْظَمَ أَجْراٗۖ وَاسْتَغْفِرُواْ اُ۬للَّهَۖ إِنَّ اَ۬للَّهَ غَفُورٞ رَّحِيمُۢۖ"]},"74":{"n":"المدثر","j":29,"a":["يَٰأَيُّهَا اَ۬لْمُدَّثِّرُ","قُمْ فَأَنذِرْۖ","وَرَبَّكَ فَكَبِّرْۖ","وَثِيَابَكَ فَطَهِّرْۖ","وَالرِّجْزَ فَاهْجُرْۖ","وَلَا تَمْنُن تَسْتَكْثِرُۖ","وَلِرَبِّكَ فَاصْبِرْۖ","فَإِذَا نُقِرَ فِے اِ۬لنَّاقُورِ","فَذَٰلِكَ يَوْمَئِذٖ يَوْمٌ عَسِيرٌ","عَلَى اَ۬لْكَٰفِرِينَ غَيْرُ يَسِيرٖۖ","ذَرْنِے وَمَنْ خَلَقْتُ وَحِيداٗ","وَجَعَلْتُ لَهُۥ مَالاٗ مَّمْدُوداٗ","وَبَنِينَ شُهُوداٗ","وَمَهَّدتُّ لَهُۥ تَمْهِيداٗ","ثُمَّ يَطْمَعُ أَنْ أَزِيدَ","كَلَّاۖ إِنَّهُۥ كَانَ لِأٓيَٰتِنَا عَنِيداٗۖ","سَأُرْهِقُهُۥ صَعُوداًۖ","إِنَّهُۥ فَكَّرَ وَقَدَّرَ","فَقُتِلَ كَيْفَ قَدَّرَ","ثُمَّ قُتِلَ كَيْفَ قَدَّرَ","ثُمَّ نَظَرَ","ثُمَّ عَبَسَ وَبَسَرَ","ثُمَّ أَدْبَرَ وَاسْتَكْبَرَ","فَقَالَ إِنْ هَٰذَا إِلَّا سِحْرٞ يُؤْثَرُ","إِنْ هَٰذَا إِلَّا قَوْلُ اُ۬لْبَشَرِۖ","سَأُصْلِيهِ سَقَرَۖ","وَمَا أَدْرَيٰكَ مَا سَقَرُۖ","لَا تُبْقِے وَلَا تَذَرُۖ","لَوَّاحَةٞ لِّلْبَشَرِۖ","عَلَيْهَا تِسْعَةَ عَشَرَۖ","وَمَا جَعَلْنَا أَصْحَٰبَ اَ۬لنَّارِ إِلَّا مَلَٰٓئِكَةٗۖ وَمَا جَعَلْنَا عِدَّتَهُمْ إِلَّا فِتْنَةٗ لِّلذِينَ كَفَرُواْ لِيَسْتَيْقِنَ اَ۬لذِينَ أُوتُواْ اُ۬لْكِتَٰبَ وَيَزْدَادَ اَ۬لذِينَ ءَامَنُواْ إِيمَٰناٗ وَلَا يَرْتَابَ اَ۬لذِينَ أُوتُواْ اُ۬لْكِتَٰبَ وَالْمُؤْمِنُونَ وَلِيَقُولَ اَ۬لذِينَ فِے قُلُوبِهِم مَّرَضٞ وَالْكَٰفِرُونَ مَاذَا أَرَادَ اَ۬للَّهُ بِهَٰذَا مَثَلاٗۖ كَذَٰلِكَ يُضِلُّ اُ۬للَّهُ مَنْ يَّشَآءُ وَيَهْدِے مَنْ يَّشَآءُۖ وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَۖ وَمَا هِيَ إِلَّا ذِكْرَىٰ لِلْبَشَرِۖ","كَلَّا وَالْقَمَرِ","وَاليْلِ إِذْ أَدْبَرَ","وَالصُّبْحِ إِذَا أَسْفَرَ","إِنَّهَا لَإِحْدَى اَ۬لْكُبَرِ","نَذِيراٗ لِّلْبَشَرِ","لِمَن شَآءَ مِنكُمْ أَنْ يَّتَقَدَّمَ أَوْ يَتَأَخَّرَۖ","كُلُّ نَفْسِۢ بِمَا كَسَبَتْ رَهِينَةٌ","إِلَّا أَصْحَٰبَ اَ۬لْيَمِينِۖ","فِے جَنَّٰتٖ يَتَسَآءَلُونَ عَنِ اِ۬لْمُجْرِمِينَ","مَا سَلَكَكُمْ فِے سَقَرَۖ","قَالُواْ لَمْ نَكُ مِنَ اَ۬لْمُصَلِّينَ","وَلَمْ نَكُ نُطْعِمُ اُ۬لْمِسْكِينَ","وَكُنَّا نَخُوضُ مَعَ اَ۬لْخَآئِضِينَ","وَكُنَّا نُكَذِّبُ بِيَوْمِ اِ۬لدِّينِ","حَتَّىٰ أَتَيٰنَا اَ۬لْيَقِينُۖ","فَمَا تَنفَعُهُمْ شَفَٰعَةُ اُ۬لشَّٰفِعِينَۖ","فَمَا لَهُمْ عَنِ اِ۬لتَّذْكِرَةِ مُعْرِضِينَ","كَأَنَّهُمْ حُمُرٞ مُّسْتَنفَرَةٞ","فَرَّتْ مِن قَسْوَرَةِۢۖ","بَلْ يُرِيدُ كُلُّ اُ۪مْرِےٕٖ مِّنْهُمْ أَنْ يُّؤْتَىٰ صُحُفاٗ مُّنَشَّرَةٗۖ","كَلَّا بَل لَّا يَخَافُونَ اَ۬لْأٓخِرَةَۖ","كَلَّا إِنَّهُۥ تَذْكِرَةٞۖ","فَمَن شَآءَ ذَكَرَهُۥۖ","وَمَا تَذْكُرُونَ إِلَّا أَنْ يَّشَآءَ اَ۬للَّهُۖ هُوَ أَهْلُ اُ۬لتَّقْوَىٰ وَأَهْلُ اُ۬لْمَغْفِرَةِۖ"]},"75":{"n":"القيامة","j":29,"a":["لَا أُقْسِمُ بِيَوْمِ اِ۬لْقِيَٰمَةِ","وَلَا أُقْسِمُ بِالنَّفْسِ اِ۬للَّوَّامَةِۖ","أَيَحْسِبُ اُ۬لْإِنسَٰنُ أَلَّن نَّجْمَعَ عِظَامَهُۥ","بَلَىٰۖ قَٰدِرِينَ عَلَىٰ أَن نُّسَوِّيَ بَنَانَهُۥۖ","بَلْ يُرِيدُ اُ۬لْإِنسَٰنُ لِيَفْجُرَ أَمَامَهُۥۖ","يَسْـَٔلُ أَيَّانَ يَوْمُ اُ۬لْقِيَٰمَةِۖ","فَإِذَا بَرَقَ اَ۬لْبَصَرُ","وَخَسَفَ اَ۬لْقَمَرُ","وَجُمِعَ اَ۬لشَّمْسُ وَالْقَمَرُ","يَقُولُ اُ۬لْإِنسَٰنُ يَوْمَئِذٍ أَيْنَ اَ۬لْمَفَرُّۖ","كَلَّا لَا وَزَرَۖ","إِلَىٰ رَبِّكَ يَوْمَئِذٍ اِ۬لْمُسْتَقَرُّۖ","يُنَبَّؤُاْ اُ۬لْإِنسَٰنُ يَوْمَئِذِۢ بِمَا قَدَّمَ وَأَخَّرَۖ","بَلِ اِ۬لْإِنسَٰنُ عَلَىٰ نَفْسِهِۦ بَصِيرَةٞ","وَلَوْ أَلْقَىٰ مَعَاذِيرَهُۥۖ","لَا تُحَرِّكْ بِهِۦ لِسَانَكَ لِتَعْجَلَ بِهِۦۖ إِنَّ عَلَيْنَا جَمْعَهُۥ وَقُرْءَانَهُۥۖ","فَإِذَا قَرَأْنَٰهُ فَاتَّبِعْ قُرْءَانَهُۥ","ثُمَّ إِنَّ عَلَيْنَا بَيَانَهُۥۖ","كَلَّا بَلْ تُحِبُّونَ اَ۬لْعَاجِلَةَ","وَتَذَرُونَ اَ۬لْأٓخِرَةَۖ","وُجُوهٞ يَوْمَئِذٖ نَّاضِرَةٌ","إِلَىٰ رَبِّهَا نَاظِرَةٞۖ","وَوُجُوهٞ يَوْمَئِذِۢ بَاسِرَةٞ","تَظُنُّ أَنْ يُّفْعَلَ بِهَا فَاقِرَةٞۖ","كَلَّا إِذَا بَلَغَتِ اِ۬لتَّرَاقِيَ","وَقِيلَ مَن رَّاقٖ","وَظَنَّ أَنَّهُ اُ۬لْفِرَاقُ","وَالْتَفَّتِ اِ۬لسَّاقُ بِالسَّاقِ","إِلَىٰ رَبِّكَ يَوْمَئِذٍ اِ۬لْمَسَاقُۖ","فَلَا صَدَّقَ وَلَا صَلَّىٰۖ","وَلَٰكِن كَذَّبَ وَتَوَلَّىٰۖ","ثُمَّ ذَهَبَ إِلَىٰ أَهْلِهِۦ يَتَمَطَّىٰۖ","أَوْلَىٰ لَكَ فَأَوْلَىٰ","ثُمَّ أَوْلَىٰ لَكَ فَأَوْلَىٰۖ","أَيَحْسِبُ اُ۬لْإِنسَٰنُ أَنْ يُّتْرَكَ سُدىًۖ","أَلَمْ يَكُ نُطْفَةٗ مِّن مَّنِيّٖ تُمْنَىٰ","ثُمَّ كَانَ عَلَقَةٗ فَخَلَقَ فَسَوَّىٰ","فَجَعَلَ مِنْهُ اُ۬لزَّوْجَيْنِ اِ۬لذَّكَرَ وَالْأُنثَىٰۖ","أَلَيْسَ ذَٰلِكَ بِقَٰدِرٍ عَلَىٰ أَنْ يُّحْـِۧيَ اَ۬لْمَوْتَىٰۖ"]},"76":{"n":"الإنسان","j":29,"a":["هَلْ أَتَىٰ عَلَى اَ۬لْإِنسَٰنِ حِينٞ مِّنَ اَ۬لدَّهْرِ لَمْ يَكُن شَئْاٗ مَّذْكُوراًۖ","إِنَّا خَلَقْنَا اَ۬لْإِنسَٰنَ مِن نُّطْفَةٍ أَمْشَاجٖ نَّبْتَلِيهِ فَجَعَلْنَٰهُ سَمِيعاَۢ بَصِيراًۖ","إِنَّا هَدَيْنَٰهُ اُ۬لسَّبِيلَ إِمَّا شَاكِراٗ وَإِمَّا كَفُوراًۖ","إِنَّا أَعْتَدْنَا لِلْكَٰفِرِينَ سَلَٰسِلاٗ وَأَغْلَٰلاٗ وَسَعِيراًۖ","إِنَّ اَ۬لْأَبْرَارَ يَشْرَبُونَ مِن كَأْسٖ كَانَ مِزَاجُهَا كَافُوراً","عَيْناٗ يَشْرَبُ بِهَا عِبَادُ اُ۬للَّهِ يُفَجِّرُونَهَا تَفْجِيراٗۖ","يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْماٗ كَانَ شَرُّهُۥ مُسْتَطِيراٗۖ","وَيُطْعِمُونَ اَ۬لطَّعَامَ عَلَىٰ حُبِّهِۦ مِسْكِيناٗ وَيَتِيماٗ وَأَسِيراً","إِنَّمَا نُطْعِمُكُمْ لِوَجْهِ اِ۬للَّهِۖ لَا نُرِيدُ مِنكُمْ جَزَآءٗ وَلَا شُكُوراًۖ","إِنَّا نَخَافُ مِن رَّبِّنَا يَوْماً عَبُوساٗ قَمْطَرِيراٗۖ","فَوَقَيٰهُمُ اُ۬للَّهُ شَرَّ ذَٰلِكَ اَ۬لْيَوْمِ وَلَقَّيٰهُمْ نَضْرَةٗ وَسُرُوراٗۖ","وَجَزَيٰهُم بِمَا صَبَرُواْ جَنَّةٗ وَحَرِيراٗ","مُّتَّكِـِٕينَ فِيهَا عَلَى اَ۬لْأَرَآئِكِ لَا يَرَوْنَ فِيهَا شَمْساٗ وَلَا زَمْهَرِيراٗ","وَدَانِيَةً عَلَيْهِمْ ظِلَٰلُهَا وَذُلِّلَتْ قُطُوفُهَا تَذْلِيلاٗۖ","وَيُطَافُ عَلَيْهِم بِـَٔانِيَةٖ مِّن فِضَّةٖۖ وَأَكْوَابٖ كَانَتْ قَوَارِيراٗۖ","قَوَارِيراٗ مِّن فِضَّةٖ قَدَّرُوهَا تَقْدِيراٗۖ","وَيُسْقَوْنَ فِيهَا كَأْساٗ كَانَ مِزَاجُهَا زَنجَبِيلاً","عَيْناٗ فِيهَا تُسَمَّىٰ سَلْسَبِيلاٗۖ","وَيَطُوفُ عَلَيْهِمْ وِلْدَٰنٞ مُّخَلَّدُونَ إِذَا رَأَيْتَهُمْ حَسِبْتَهُمْ لُؤْلُؤاٗ مَّنثُوراٗۖ","وَإِذَا رَأَيْتَ ثَمَّ رَأَيْتَ نَعِيماٗ وَمُلْكاٗ كَبِيراً","عَٰلِيهِمْ ثِيَابُ سُندُسٍ خُضْرٞ وَإِسْتَبْرَقٞۖ وَحُلُّواْ أَسَاوِرَ مِن فِضَّةٖۖ وَسَقَيٰهُمْ رَبُّهُمْ شَرَاباٗ طَهُوراًۖ","إِنَّ هَٰذَا كَانَ لَكُمْ جَزَآءٗ وَكَانَ سَعْيُكُم مَّشْكُوراًۖ","إِنَّا نَحْنُ نَزَّلْنَا عَلَيْكَ اَ۬لْقُرْءَانَ تَنزِيلاٗۖ","فَاصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تُطِعْ مِنْهُمْ ءَاثِماً أَوْ كَفُوراٗۖ","وَاذْكُرِ اِ۪سْمَ رَبِّكَ بُكْرَةٗ وَأَصِيلاٗۖ","وَمِنَ اَ۬ليْلِ فَاسْجُدْ لَهُۥ وَسَبِّحْهُ لَيْلاٗ طَوِيلاًۖ","إِنَّ هَٰؤُلَآءِ يُحِبُّونَ اَ۬لْعَاجِلَةَ وَيَذَرُونَ وَرَآءَهُمْ يَوْماٗ ثَقِيلاٗۖ","نَّحْنُ خَلَقْنَٰهُمْ وَشَدَدْنَا أَسْرَهُمْ وَإِذَا شِئْنَا بَدَّلْنَا أَمْثَٰلَهُمْ تَبْدِيلاًۖ","إِنَّ هَٰذِهِۦ تَذْكِرَةٞۖ فَمَن شَآءَ اَ۪تَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلاٗۖ","وَمَا تَشَآءُونَ إِلَّا أَنْ يَّشَآءَ اَ۬للَّهُۖ إِنَّ اَ۬للَّهَ كَانَ عَلِيماً حَكِيماٗۖ","يُدْخِلُ مَنْ يَّشَآءُ فِے رَحْمَتِهِۦۖ وَالظَّٰلِمِينَ أَعَدَّ لَهُمْ عَذَاباً أَلِيماَۢۖ"]},"77":{"n":"المرسلات","j":29,"a":["وَالْمُرْسَلَٰتِ عُرْفاٗ","فَالْعَٰصِفَٰتِ عَصْفاٗ","وَالنَّٰشِرَٰتِ نَشْراٗ","فَالْفَٰرِقَٰتِ فَرْقاٗ","فَالْمُلْقِيَٰتِ ذِكْراً","عُذْراً أَوْ نُذُراً","إِنَّمَا تُوعَدُونَ لَوَٰقِعٞۖ","فَإِذَا اَ۬لنُّجُومُ طُمِسَتْ","وَإِذَا اَ۬لسَّمَآءُ فُرِجَتْ","وَإِذَا اَ۬لْجِبَالُ نُسِفَتْ","وَإِذَا اَ۬لرُّسُلُ أُقِّتَتْ","لِأَيِّ يَوْمٍ أُجِّلَتْ","لِيَوْمِ اِ۬لْفَصْلِۖ","وَمَا أَدْرَيٰكَ مَا يَوْمُ اُ۬لْفَصْلِۖ","وَيْلٞ يَوْمَئِذٖ لِّلْمُكَذِّبِينَۖ","أَلَمْ نُهْلِكِ اِ۬لْأَوَّلِينَۖ","ثُمَّ نُتْبِعُهُمُ اُ۬لْأٓخِرِينَۖ","كَذَٰلِكَ نَفْعَلُ بِالْمُجْرِمِينَۖ","وَيْلٞ يَوْمَئِذٖ لِّلْمُكَذِّبِينَۖ","أَلَمْ نَخْلُقكُّم مِّن مَّآءٖ مَّهِينٖ","فَجَعَلْنَٰهُ فِے قَرَارٖ مَّكِينٍ","إِلَىٰ قَدَرٖ مَّعْلُومٖ","فَقَدَّرْنَاۖ فَنِعْمَ اَ۬لْقَٰدِرُونَۖ","وَيْلٞ يَوْمَئِذٖ لِّلْمُكَذِّبِينَۖ","أَلَمْ نَجْعَلِ اِ۬لْأَرْضَ كِفَاتاً","أَحْيَآءٗ وَأَمْوَٰتاٗ","وَجَعَلْنَا فِيهَا رَوَٰسِيَ شَٰمِخَٰتٖ وَأَسْقَيْنَٰكُم مَّآءٗ فُرَاتاٗۖ","وَيْلٞ يَوْمَئِذٖ لِّلْمُكَذِّبِينَۖ","اَ۪نطَلِقُواْ إِلَىٰ مَا كُنتُم بِهِۦ تُكَذِّبُونَ","اَ۪نطَلِقُواْ إِلَىٰ ظِلّٖ ذِے ثَلَٰثِ شُعَبٖ","لَّا ظَلِيلٖ وَلَا يُغْنِے مِنَ اَ۬للَّهَبِۖ","إِنَّهَا تَرْمِے بِشَرَرٖ كَالْقَصْرِ","كَأَنَّهُۥ جِمَٰلَٰتٞ صُفْرٞۖ","وَيْلٞ يَوْمَئِذٖ لِّلْمُكَذِّبِينَۖ","هَٰذَا يَوْمُ لَا يَنطِقُونَ","وَلَا يُؤْذَنُ لَهُمْ فَيَعْتَذِرُونَۖ","وَيْلٞ يَوْمَئِذٖ لِّلْمُكَذِّبِينَۖ","هَٰذَا يَوْمُ اُ۬لْفَصْلِ جَمَعْنَٰكُمْ وَالْأَوَّلِينَ","فَإِن كَانَ لَكُمْ كَيْدٞ فَكِيدُونِۖ","وَيْلٞ يَوْمَئِذٖ لِّلْمُكَذِّبِينَۖ","إِنَّ اَ۬لْمُتَّقِينَ فِے ظِلَٰلٖ وَعُيُونٖ","وَفَوَٰكِهَ مِمَّا يَشْتَهُونَۖ","كُلُواْ وَاشْرَبُواْۖ هَنِيٓـٔاَۢ بِمَا كُنتُمْ تَعْمَلُونَۖ","إِنَّا كَذَٰلِكَ نَجْزِے اِ۬لْمُحْسِنِينَۖ","وَيْلٞ يَوْمَئِذٖ لِّلْمُكَذِّبِينَۖ","كُلُواْ وَتَمَتَّعُواْ قَلِيلاً إِنَّكُم مُّجْرِمُونَۖ","وَيْلٞ يَوْمَئِذٖ لِّلْمُكَذِّبِينَۖ","وَإِذَا قِيلَ لَهُمُ اُ۪رْكَعُواْ لَا يَرْكَعُونَۖ","وَيْلٞ يَوْمَئِذٖ لِّلْمُكَذِّبِينَۖ","فَبِأَيِّ حَدِيثِۢ بَعْدَهُۥ يُؤْمِنُونَۖ"]},"78":{"n":"النبإ","j":30,"a":["عَمَّ يَتَسَآءَلُونَ","عَنِ اِ۬لنَّبَإِ اِ۬لْعَظِيمِ","اِ۬لذِے هُمْ فِيهِ مُخْتَلِفُونَۖ","كَلَّا سَيَعْلَمُونَ","ثُمَّ كَلَّا سَيَعْلَمُونَۖ","أَلَمْ نَجْعَلِ اِ۬لْأَرْضَ مِهَٰداٗ","وَالْجِبَالَ أَوْتَاداٗ","وَخَلَقْنَٰكُمْ أَزْوَٰجاٗ","وَجَعَلْنَا نَوْمَكُمْ سُبَاتاٗ","وَجَعَلْنَا اَ۬ليْلَ لِبَاساٗ","وَجَعَلْنَا اَ۬لنَّهَارَ مَعَاشاٗ","وَبَنَيْنَا فَوْقَكُمْ سَبْعاٗ شِدَاداٗ","وَجَعَلْنَا سِرَاجاٗ وَهَّاجاٗ","وَأَنزَلْنَا مِنَ اَ۬لْمُعْصِرَٰتِ مَآءٗ ثَجَّاجاٗ","لِّنُخْرِجَ بِهِۦ حَبّاٗ وَنَبَاتاٗ","وَجَنَّٰتٍ أَلْفَافاًۖ","إِنَّ يَوْمَ اَ۬لْفَصْلِ كَانَ مِيقَٰتاٗ","يَوْمَ يُنفَخُ فِے اِ۬لصُّورِ فَتَأْتُونَ أَفْوَاجاٗ","وَفُتِّحَتِ اِ۬لسَّمَآءُ فَكَانَتْ أَبْوَاباٗ","وَسُيِّرَتِ اِ۬لْجِبَالُ فَكَانَتْ سَرَاباًۖ","إِنَّ جَهَنَّمَ كَانَتْ مِرْصَاداٗ","لِّلطَّٰغِينَ مَـَٔاباٗ","لَّٰبِثِينَ فِيهَا أَحْقَاباٗۖ","لَّا يَذُوقُونَ فِيهَا بَرْداٗ وَلَا شَرَاباً","إِلَّا حَمِيماٗ وَغَسَاقاٗ","جَزَآءٗ وِفَاقاًۖ","إِنَّهُمْ كَانُواْ لَا يَرْجُونَ حِسَاباٗ","وَكَذَّبُواْ بِـَٔايَٰتِنَا كِذَّاباٗۖ","وَكُلَّ شَےْءٍ أَحْصَيْنَٰهُ كِتَٰباٗۖ","فَذُوقُواْ فَلَن نَّزِيدَكُمْ إِلَّا عَذَاباًۖ","إِنَّ لِلْمُتَّقِينَ مَفَازاً","حَدَآئِقَ وَأَعْنَٰباٗ","وَكَوَاعِبَ أَتْرَاباٗ","وَكَأْساٗ دِهَاقاٗ","لَّا يَسْمَعُونَ فِيهَا لَغْواٗ وَلَا كِذَّاباٗۖ","جَزَآءٗ مِّن رَّبِّكَ عَطَآءً حِسَاباٗۖ","رَّبُّ اُ۬لسَّمَٰوَٰتِ وَالْأَرْضِ وَمَا بَيْنَهُمَاۖ اَ۬لرَّحْمَٰنُ لَا يَمْلِكُونَ مِنْهُ خِطَاباٗۖ","يَوْمَ يَقُومُ اُ۬لرُّوحُ وَالْمَلَٰٓئِكَةُ صَفّاٗ لَّا يَتَكَلَّمُونَ إِلَّا مَنْ أَذِنَ لَهُ اُ۬لرَّحْمَٰنُ وَقَالَ صَوَاباٗۖ","ذَٰلِكَ اَ۬لْيَوْمُ اُ۬لْحَقُّۖ فَمَن شَآءَ اَ۪تَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔاباًۖ","إِنَّا أَنذَرْنَٰكُمْ عَذَاباٗ قَرِيباٗ يَوْمَ يَنظُرُ اُ۬لْمَرْءُ مَا قَدَّمَتْ يَدَٰهُ وَيَقُولُ اُ۬لْكَافِرُ يَٰلَيْتَنِے كُنتُ تُرَٰباَۢۖ"]},"79":{"n":"النازعات","j":30,"a":["وَالنَّٰزِعَٰتِ غَرْقاٗ","وَالنَّٰشِطَٰتِ نَشْطاٗ","وَالسَّٰبِحَٰتِ سَبْحاٗ","فَالسَّٰبِقَٰتِ سَبْقاٗ","فَالْمُدَبِّرَٰتِ أَمْراٗ","يَوْمَ تَرْجُفُ اُ۬لرَّاجِفَةُ","تَتْبَعُهَا اَ۬لرَّادِفَةُۖ","قُلُوبٞ يَوْمَئِذٖ وَاجِفَةٌ","أَبْصَٰرُهَا خَٰشِعَةٞۖ","يَقُولُونَ أَٰ۟نَّا لَمَرْدُودُونَ فِے اِ۬لْحَافِرَةِ","إِذَا كُنَّا عِظَٰماٗ نَّخِرَةٗۖ","قَالُواْ تِلْكَ إِذاٗ كَرَّةٌ خَاسِرَةٞ","فَإِنَّمَا هِيَ زَجْرَةٞ وَٰحِدَةٞ","فَإِذَا هُم بِالسَّاهِرَةِۖ","هَلْ أَتَيٰكَ حَدِيثُ مُوسَىٰ","إِذْ نَادَيٰهُ رَبُّهُۥ بِالْوَادِ اِ۬لْمُقَدَّسِ طُوَىۖ","اَ۪ذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ","فَقُلْ هَل لَّكَ إِلَىٰ أَن تَزَّكَّىٰ","وَأَهْدِيَكَ إِلَىٰ رَبِّكَ فَتَخْشَىٰۖ","فَأَرَيٰهُ اُ۬لْأٓيَةَ اَ۬لْكُبْرَىٰ","فَكَذَّبَ وَعَصَىٰ","ثُمَّ أَدْبَرَ يَسْعَىٰ","فَحَشَرَ فَنَادَىٰ","فَقَالَ أَنَا رَبُّكُمُ اُ۬لْأَعْلَىٰ","فَأَخَذَهُ اُ۬للَّهُ نَكَالَ اَ۬لْأٓخِرَةِ وَالْأُولَىٰۖ","إِنَّ فِے ذَٰلِكَ لَعِبْرَةٗ لِّمَنْ يَّخْشَىٰۖ","ءَٰا۬نتُمْ أَشَدُّ خَلْقاً أَمِ اِ۬لسَّمَآءُۖ بَنَيٰهَا","رَفَعَ سَمْكَهَا فَسَوَّيٰهَا","وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَيٰهَاۖ","وَالْأَرْضَ بَعْدَ ذَٰلِكَ دَحَيٰهَا","أَخْرَجَ مِنْهَا مَآءَهَا وَمَرْعَيٰهَا","وَالْجِبَالَ أَرْسَيٰهَا","مَتَٰعاٗ لَّكُمْ وَلِأَنْعَٰمِكُمْۖ","فَإِذَا جَآءَتِ اِ۬لطَّآمَّةُ اُ۬لْكُبْرَىٰ","يَوْمَ يَتَذَكَّرُ اُ۬لْإِنسَٰنُ مَا سَعَىٰ","وَبُرِّزَتِ اِ۬لْجَحِيمُ لِمَنْ يَّرَىٰۖ","فَأَمَّا مَن طَغَىٰ وَءَاثَرَ اَ۬لْحَيَوٰةَ اَ۬لدُّنْيَا","فَإِنَّ اَ۬لْجَحِيمَ هِيَ اَ۬لْمَأْوَىٰۖ","وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى اَ۬لنَّفْسَ عَنِ اِ۬لْهَوَىٰ","فَإِنَّ اَ۬لْجَنَّةَ هِيَ اَ۬لْمَأْوَىٰۖ","يَسْـَٔلُونَكَ عَنِ اِ۬لسَّاعَةِ أَيَّانَ مُرْسَيٰهَاۖ","فِيمَ أَنتَ مِن ذِكْرَيٰهَاۖ","إِلَىٰ رَبِّكَ مُنتَهَيٰهَاۖ","إِنَّمَا أَنتَ مُنذِرُ مَنْ يَّخْشَيٰهَاۖ","كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُواْ إِلَّا عَشِيَّةً أَوْ ضُحَيٰهَاۖ"]},"80":{"n":"عبس","j":30,"a":["عَبَسَ وَتَوَلَّىٰ","أَن جَآءَهُ اُ۬لْأَعْمَىٰۖ","وَمَا يُدْرِيكَۖ لَعَلَّهُۥ يَزَّكَّىٰ","أَوْ يَذَّكَّرُ فَتَنفَعُهُ اُ۬لذِّكْرَىٰۖ","أَمَّا مَنِ اِ۪سْتَغْنَىٰ","فَأَنتَ لَهُۥ تَصَّدَّىٰ","وَمَا عَلَيْكَ أَلَّا يَزَّكَّىٰۖ","وَأَمَّا مَن جَآءَكَ يَسْعَىٰ","وَهْوَ يَخْشَىٰ","فَأَنتَ عَنْهُ تَلَهَّىٰ","كَلَّاۖ إِنَّهَا تَذْكِرَةٞۖ","فَمَن شَآءَ ذَكَرَهُۥ","فِے صُحُفٖ مُّكَرَّمَةٖ","مَّرْفُوعَةٖ مُّطَهَّرَةِۢ","بِأَيْدِے سَفَرَةٖ","كِرَامِۢ بَرَرَةٖۖ","قُتِلَ اَ۬لْإِنسَٰنُ مَا أَكْفَرَهُۥۖ","مِنْ أَيِّ شَےْءٍ خَلَقَهُۥۖ","مِن نُّطْفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ","ثُمَّ اَ۬لسَّبِيلَ يَسَّرَهُۥ","ثُمَّ أَمَاتَهُۥ فَأَقْبَرَهُۥۖ","ثُمَّ إِذَا شَا أَنشَرَهُۥۖ","كَلَّا لَمَّا يَقْضِ مَا أَمَرَهُۥۖ","فَلْيَنظُرِ اِ۬لْإِنسَٰنُ إِلَىٰ طَعَامِهِۦۖ","إِنَّا صَبَبْنَا اَ۬لْمَآءَ صَبّاٗ","ثُمَّ شَقَقْنَا اَ۬لْأَرْضَ شَقّاٗ","فَأَنۢبَتْنَا فِيهَا حَبّاٗ","وَعِنَباٗ وَقَضْباٗ","وَزَيْتُوناٗ وَنَخْلاٗ","وَحَدَآئِقَ غُلْباٗ","وَفَٰكِهَةٗ وَأَبّاٗ","مَّتَٰعاٗ لَّكُمْ وَلِأَنْعَٰمِكُمْۖ","فَإِذَا جَآءَتِ اِ۬لصَّآخَّةُ","يَوْمَ يَفِرُّ اُ۬لْمَرْءُ مِنْ أَخِيهِ","وَأُمِّهِۦ وَأَبِيهِ","وَصَٰحِبَتِهِۦ وَبَنِيهِۖ","لِكُلِّ اِ۪مْرِےٕٖ مِّنْهُمْ يَوْمَئِذٖ شَأْنٞ يُغْنِيهِۖ","وُجُوهٞ يَوْمَئِذٖ مُّسْفِرَةٞ","ضَاحِكَةٞ مُّسْتَبْشِرَةٞۖ","وَوُجُوهٞ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٞ","تَرْهَقُهَا قَتَرَةٌۖ","أُوْلَٰٓئِكَ هُمُ اُ۬لْكَفَرَةُ اُ۬لْفَجَرَةُۖ"]},"81":{"n":"التكوير","j":30,"a":["إِذَا اَ۬لشَّمْسُ كُوِّرَتْ","وَإِذَا اَ۬لنُّجُومُ اُ۪نكَدَرَتْ","وَإِذَا اَ۬لْجِبَالُ سُيِّرَتْ","وَإِذَا اَ۬لْعِشَارُ عُطِّلَتْ","وَإِذَا اَ۬لْوُحُوشُ حُشِرَتْ","وَإِذَا اَ۬لْبِحَارُ سُجِّرَتْ","وَإِذَا اَ۬لنُّفُوسُ زُوِّجَتْ","وَإِذَا اَ۬لْمَوْءُۥدَةُ سُئِلَتْ","بِأَيِّ ذَنۢبٖ قُتِلَتْ","وَإِذَا اَ۬لصُّحُفُ نُشِرَتْ","وَإِذَا اَ۬لسَّمَآءُ كُشِطَتْ","وَإِذَا اَ۬لْجَحِيمُ سُعِّرَتْ","وَإِذَا اَ۬لْجَنَّةُ أُزْلِفَتْ","عَلِمَتْ نَفْسٞ مَّا أَحْضَرَتْۖ","فَلَا أُقْسِمُ بِالْخُنَّسِ","اِ۬لْجَوَارِ اِ۬لْكُنَّسِ","وَاليْلِ إِذَا عَسْعَسَ","وَالصُّبْحِ إِذَا تَنَفَّسَ","إِنَّهُۥ لَقَوْلُ رَسُولٖ كَرِيمٖ","ذِے قُوَّةٍ عِندَ ذِے اِ۬لْعَرْشِ مَكِينٖ","مُّطَاعٖ ثَمَّ أَمِينٖۖ","وَمَا صَٰحِبُكُم بِمَجْنُونٖۖ","وَلَقَدْ رَءَاهُ بِالْأُفُقِ اِ۬لْمُبِينِۖ","وَمَا هُوَ عَلَى اَ۬لْغَيْبِ بِضَنِينٖۖ","وَمَا هُوَ بِقَوْلِ شَيْطَٰنٖ رَّجِيمٖ","فَأَيْنَ تَذْهَبُونَۖ","إِنْ هُوَ إِلَّا ذِكْرٞ لِّلْعَٰلَمِينَ","لِمَن شَآءَ مِنكُمْ أَنْ يَّسْتَقِيمَۖ","وَمَا تَشَآءُونَ إِلَّا أَنْ يَّشَآءَ اَ۬للَّهُ رَبُّ اُ۬لْعَٰلَمِينَۖ"]},"82":{"n":"الانفطار","j":30,"a":["إِذَا اَ۬لسَّمَآءُ اُ۪نفَطَرَتْ","وَإِذَا اَ۬لْكَوَاكِبُ اُ۪نتَثَرَتْ","وَإِذَا اَ۬لْبِحَارُ فُجِّرَتْ","وَإِذَا اَ۬لْقُبُورُ بُعْثِرَتْ","عَلِمَتْ نَفْسٞ مَّا قَدَّمَتْ وَأَخَّرَتْۖ","يَٰأَيُّهَا اَ۬لْإِنسَٰنُ مَا غَرَّكَ بِرَبِّكَ اَ۬لْكَرِيمِ","اِ۬لذِے خَلَقَكَ فَسَوَّيٰكَ فَعَدَّلَكَ","فِے أَيِّ صُورَةٖ مَّا شَآءَ رَكَّبَكَۖ","كَلَّا بَلْ تُكَذِّبُونَ بِالدِّينِ","وَإِنَّ عَلَيْكُمْ لَحَٰفِظِينَ","كِرَاماٗ كَٰتِبِينَ","يَعْلَمُونَ مَا تَفْعَلُونَۖ","إِنَّ اَ۬لْأَبْرَارَ لَفِے نَعِيمٖۖ","وَإِنَّ اَ۬لْفُجَّارَ لَفِے جَحِيمٖ","يَصْلَوْنَهَا يَوْمَ اَ۬لدِّينِ","وَمَا هُمْ عَنْهَا بِغَآئِبِينَۖ","وَمَا أَدْرَيٰكَ مَا يَوْمُ اُ۬لدِّينِ","ثُمَّ مَا أَدْرَيٰكَ مَا يَوْمُ اُ۬لدِّينِۖ","يَوْمَ لَا تَمْلِكُ نَفْسٞ لِّنَفْسٖ شَئْاٗۖ وَالْأَمْرُ يَوْمَئِذٖ لِّلهِۖ"]},"83":{"n":"المطففين","j":30,"a":["وَيْلٞ لِّلْمُطَفِّفِينَ","اَ۬لذِينَ إِذَا اَ۪كْتَالُواْ عَلَى اَ۬لنَّاسِ يَسْتَوْفُونَ","وَإِذَا كَالُوهُمْ أَو وَّزَنُوهُمْ يُخْسِرُونَۖ","أَلَا يَظُنُّ أُوْلَٰٓئِكَ أَنَّهُم مَّبْعُوثُونَ","لِيَوْمٍ عَظِيمٖ","يَوْمَ يَقُومُ اُ۬لنَّاسُ لِرَبِّ اِ۬لْعَٰلَمِينَۖ","كَلَّا إِنَّ كِتَٰبَ اَ۬لْفُجَّارِ لَفِے سِجِّينٖۖ","وَمَا أَدْرَيٰكَ مَا سِجِّينٞ","كِتَٰبٞ مَّرْقُومٞۖ","وَيْلٞ يَوْمَئِذٖ لِّلْمُكَذِّبِينَ","اَ۬لذِينَ يُكَذِّبُونَ بِيَوْمِ اِ۬لدِّينِۖ","وَمَا يُكَذِّبُ بِهِۦ إِلَّا كُلُّ مُعْتَدٍ أَثِيمٍ","إِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ اُ۬لْأَوَّلِينَۖ","كَلَّا بَل رَّانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكْسِبُونَۖ","كَلَّا إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٖ لَّمَحْجُوبُونَۖ","ثُمَّ إِنَّهُمْ لَصَالُواْ اُ۬لْجَحِيمِۖ","ثُمَّ يُقَالُ هَٰذَا اَ۬لذِے كُنتُم بِهِۦ تُكَذِّبُونَۖ","كَلَّا إِنَّ كِتَٰبَ اَ۬لْأَبْرَارِ لَفِے عِلِّيِّينَۖ","وَمَا أَدْرَيٰكَ مَا عِلِّيُّونَ","كِتَٰبٞ مَّرْقُومٞ","يَشْهَدُهُ اُ۬لْمُقَرَّبُونَۖ","إِنَّ اَ۬لْأَبْرَارَ لَفِے نَعِيمٍ","عَلَى اَ۬لْأَرَآئِكِ يَنظُرُونَ","تَعْرِفُ فِے وُجُوهِهِمْ نَضْرَةَ اَ۬لنَّعِيمِ","يُسْقَوْنَ مِن رَّحِيقٖ مَّخْتُومٍ","خِتَٰمُهُۥ مِسْكٞۖ وَفِے ذَٰلِكَ فَلْيَتَنَافَسِ اِ۬لْمُتَنَٰفِسُونَۖ","وَمِزَاجُهُۥ مِن تَسْنِيمٍ","عَيْناٗ يَشْرَبُ بِهَا اَ۬لْمُقَرَّبُونَۖ","إِنَّ اَ۬لذِينَ أَجْرَمُواْ كَانُواْ مِنَ اَ۬لذِينَ ءَامَنُواْ يَضْحَكُونَ","وَإِذَا مَرُّواْ بِهِمْ يَتَغَامَزُونَ","وَإِذَا اَ۪نقَلَبُواْ إِلَىٰ أَهْلِهِمُ اُ۪نقَلَبُواْ فَٰكِهِينَ","وَإِذَا رَأَوْهُمْ قَالُواْ إِنَّ هَٰؤُلَآءِ لَضَآلُّونَ","وَمَا أُرْسِلُواْ عَلَيْهِمْ حَٰفِظِينَۖ","فَالْيَوْمَ اَ۬لذِينَ ءَامَنُواْ مِنَ اَ۬لْكُفَّارِ يَضْحَكُونَ","عَلَى اَ۬لْأَرَآئِكِۖ يَنظُرُونَ","هَلْ ثُوِّبَ اَ۬لْكُفَّارُ مَا كَانُواْ يَفْعَلُونَۖ"]},"84":{"n":"الانشقاق","j":30,"a":["إِذَا اَ۬لسَّمَآءُ اُ۪نشَقَّتْ","وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ","وَإِذَا اَ۬لْأَرْضُ مُدَّتْ","وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ","وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْۖ","يَٰأَيُّهَا اَ۬لْإِنسَٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحاٗ فَمُلَٰقِيهِۖ","فَأَمَّا مَنْ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ","فَسَوْفَ يُحَاسَبُ حِسَاباٗ يَسِيراٗ","وَيَنقَلِبُ إِلَىٰ أَهْلِهِۦ مَسْرُوراٗۖ","وَأَمَّا مَنْ أُوتِيَ كِتَٰبَهُۥ وَرَآءَ ظَهْرِهِۦ","فَسَوْفَ يَدْعُواْ ثُبُوراٗ","وَيُصَلَّىٰ سَعِيراًۖ","إِنَّهُۥ كَانَ فِے أَهْلِهِۦ مَسْرُوراًۖ","إِنَّهُۥ ظَنَّ أَن لَّنْ يَّحُورَ","بَلَىٰۖ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيراٗۖ","فَلَا أُقْسِمُ بِالشَّفَقِ","وَاليْلِ وَمَا وَسَقَ","وَالْقَمَرِ إِذَا اَ۪تَّسَقَ","لَتَرْكَبُنَّ طَبَقاً عَن طَبَقٖۖ","فَمَا لَهُمْ لَا يُؤْمِنُونَ","وَإِذَا قُرِۓَ عَلَيْهِمُ اُ۬لْقُرْءَانُ لَا يَسْجُدُونَۖ","بَلِ اِ۬لذِينَ كَفَرُواْ يُكَذِّبُونَ","وَاللَّهُ أَعْلَمُ بِمَا يُوعُونَۖ","فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍۖ","إِلَّا اَ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ اُ۬لصَّٰلِحَٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونِۢۖ"]},"85":{"n":"البروج","j":30,"a":["وَالسَّمَآءِ ذَاتِ اِ۬لْبُرُوجِ","وَالْيَوْمِ اِ۬لْمَوْعُودِ","وَشَاهِدٖ وَمَشْهُودٖ","قُتِلَ أَصْحَٰبُ اُ۬لْأُخْدُودِ","اِ۬لنَّارِ ذَاتِ اِ۬لْوَقُودِ","إِذْ هُمْ عَلَيْهَا قُعُودٞ","وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِالْمُؤْمِنِينَ شُهُودٞۖ","وَمَا نَقَمُواْ مِنْهُمْ إِلَّا أَنْ يُّؤْمِنُواْ بِاللَّهِ اِ۬لْعَزِيزِ اِ۬لْحَمِيدِ","اِ۬لذِے لَهُۥ مُلْكُ اُ۬لسَّمَٰوَٰتِ وَالْأَرْضِۖ وَاللَّهُ عَلَىٰ كُلِّ شَےْءٖ شَهِيدٌۖ","إِنَّ اَ۬لذِينَ فَتَنُواْ اُ۬لْمُؤْمِنِينَ وَالْمُؤْمِنَٰتِ ثُمَّ لَمْ يَتُوبُواْ فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ اُ۬لْحَرِيقِۖ","إِنَّ اَ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ اُ۬لصَّٰلِحَٰتِ لَهُمْ جَنَّٰتٞ تَجْرِے مِن تَحْتِهَا اَ۬لْأَنْهَٰرُۖ ذَٰلِكَ اَ۬لْفَوْزُ اُ۬لْكَبِيرُۖ","إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌۖ","إِنَّهُۥ هُوَ يُبْدِۓُ وَيُعِيدُۖ","وَهْوَ اَ۬لْغَفُورُ اُ۬لْوَدُودُ","ذُو اُ۬لْعَرْشِۖ اِ۬لْمَجِيدُ","فَعَّالٞ لِّمَا يُرِيدُۖ","هَلْ أَتَيٰكَ حَدِيثُ اُ۬لْجُنُودِ","فِرْعَوْنَ وَثَمُودَۖ","بَلِ اِ۬لذِينَ كَفَرُواْ فِے تَكْذِيبٖ","وَاللَّهُ مِنْ وَّرَآئِهِم مُّحِيطُۢۖ","بَلْ هُوَ قُرْءَانٞ مَّجِيدٞ","فِے لَوْحٖ مَّحْفُوظُۢۖ"]},"86":{"n":"الطارق","j":30,"a":["وَالسَّمَآءِ وَالطَّارِقِ","وَمَا أَدْرَيٰكَ مَا اَ۬لطَّارِقُ","اُ۬لنَّجْمُ اُ۬لثَّاقِبُ","إِن كُلُّ نَفْسٖ لَّمَا عَلَيْهَا حَافِظٞۖ","فَلْيَنظُرِ اِ۬لْإِنسَٰنُ مِمَّ خُلِقَۖ","خُلِقَ مِن مَّآءٖ دَافِقٖ","يَخْرُجُ مِنۢ بَيْنِ اِ۬لصُّلْبِ وَالتَّرَآئِبِۖ","إِنَّهُۥ عَلَىٰ رَجْعِهِۦ لَقَادِرٞ","يَوْمَ تُبْلَى اَ۬لسَّرَآئِرُ","فَمَا لَهُۥ مِن قُوَّةٖ وَلَا نَاصِرٖۖ","وَالسَّمَآءِ ذَاتِ اِ۬لرَّجْعِ","وَالْأَرْضِ ذَاتِ اِ۬لصَّدْعِ","إِنَّهُۥ لَقَوْلٞ فَصْلٞ","وَمَا هُوَ بِالْهَزْلِۖ","إِنَّهُمْ يَكِيدُونَ كَيْداٗ","وَأَكِيدُ كَيْداٗۖ","فَمَهِّلِ اِ۬لْكَٰفِرِينَ أَمْهِلْهُمْ رُوَيْداَۢۖ"]},"87":{"n":"الأعلى","j":30,"a":["سَبِّحِ اِ۪سْمَ رَبِّكَ اَ۬لْأَعْلَى","اَ۬لذِے خَلَقَ فَسَوَّىٰ","وَالذِے قَدَّرَ فَهَدَىٰ","وَالذِے أَخْرَجَ اَ۬لْمَرْعَىٰ","فَجَعَلَهُۥ غُثَآءً أَحْوَىٰۖ","سَنُقْرِئُكَ فَلَا تَنسَىٰ","إِلَّا مَا شَآءَ اَ۬للَّهُۖ إِنَّهُۥ يَعْلَمُ اُ۬لْجَهْرَ وَمَا يَخْفَىٰۖ","وَنُيَسِّرُكَ لِلْيُسْرَىٰۖ","فَذَكِّرْ إِن نَّفَعَتِ اِ۬لذِّكْرَىٰۖ","سَيَذَّكَّرُ مَنْ يَّخْشَىٰ","وَيَتَجَنَّبُهَا اَ۬لْأَشْقَى","اَ۬لذِے يَصْلَى اَ۬لنَّارَ اَ۬لْكُبْرَىٰ","ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰۖ","قَدْ أَفْلَحَ مَن تَزَكَّىٰ","وَذَكَرَ اَ۪سْمَ رَبِّهِۦ فَصَلَّىٰۖ","بَلْ تُؤْثِرُونَ اَ۬لْحَيَوٰةَ اَ۬لدُّنْيَا","وَالْأٓخِرَةُ خَيْرٞ وَأَبْقَىٰۖ","إِنَّ هَٰذَا لَفِے اِ۬لصُّحُفِ اِ۬لْأُولَىٰ","صُحُفِ إِبْرَٰهِيمَ وَمُوسَىٰۖ"]},"88":{"n":"الغاشية","j":30,"a":["هَلْ أَتَيٰكَ حَدِيثُ اُ۬لْغَٰشِيَةِۖ","وُجُوهٞ يَوْمَئِذٍ خَٰشِعَةٌ","عَامِلَةٞ نَّاصِبَةٞ","تَصْلَىٰ نَاراً حَامِيَةٗ","تُسْقَىٰ مِنْ عَيْنٍ ءَانِيَةٖۖ","لَّيْسَ لَهُمْ طَعَامٌ إِلَّا مِن ضَرِيعٖ","لَّا يُسْمِنُ وَلَا يُغْنِے مِن جُوعٖۖ","وُجُوهٞ يَوْمَئِذٖ نَّاعِمَةٞ","لِّسَعْيِهَا رَاضِيَةٞ","فِے جَنَّةٍ عَالِيَةٖ","لَّا تُسْمَعُ فِيهَا لَٰغِيَةٞۖ","فِيهَا عَيْنٞ جَارِيَةٞۖ","فِيهَا سُرُرٞ مَّرْفُوعَةٞ","وَأَكْوَابٞ مَّوْضُوعَةٞ","وَنَمَارِقُ مَصْفُوفَةٞ","وَزَرَابِيُّ مَبْثُوثَةٌۖ","أَفَلَا يَنظُرُونَ إِلَى اَ۬لْإِبِلِ كَيْفَ خُلِقَتْ","وَإِلَى اَ۬لسَّمَآءِ كَيْفَ رُفِعَتْ","وَإِلَى اَ۬لْجِبَالِ كَيْفَ نُصِبَتْ","وَإِلَى اَ۬لْأَرْضِ كَيْفَ سُطِحَتْۖ","فَذَكِّرْ إِنَّمَا أَنتَ مُذَكِّرٞۖ","لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍۖ","إِلَّا مَن تَوَلَّىٰ وَكَفَرَ","فَيُعَذِّبُهُ اُ۬للَّهُ اُ۬لْعَذَابَ اَ۬لْأَكْبَرَۖ","إِنَّ إِلَيْنَا إِيَابَهُمْ","ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُمۖ"]},"89":{"n":"الفجر","j":30,"a":["وَالْفَجْرِ","وَلَيَالٍ عَشْرٖ","وَالشَّفْعِ وَالْوَتْرِ","وَاليْلِ إِذَا يَسْرِۦ","هَلْ فِے ذَٰلِكَ قَسَمٞ لِّذِے حِجْرٍۖ","أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ","إِرَمَ ذَاتِ اِ۬لْعِمَادِ","اِ۬لتِے لَمْ يُخْلَقْ مِثْلُهَا فِے اِ۬لْبِلَٰدِ","وَثَمُودَ اَ۬لذِينَ جَابُواْ اُ۬لصَّخْرَ بِالْوَادِ","وَفِرْعَوْنَ ذِے اِ۬لْأَوْتَادِ","اِ۬لذِينَ طَغَوْاْ فِے اِ۬لْبِلَٰدِ","فَأَكْثَرُواْ فِيهَا اَ۬لْفَسَادَ","فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍۖ","إِنَّ رَبَّكَ لَبِالْمِرْصَادِۖ","فَأَمَّا اَ۬لْإِنسَٰنُ إِذَا مَا اَ۪بْتَلَيٰهُ رَبُّهُۥ فَأَكْرَمَهُۥ وَنَعَّمَهُۥ","فَيَقُولُ رَبِّيَ أَكْرَمَنِۦۖ","وَأَمَّا إِذَا مَا اَ۪بْتَلَيٰهُ فَقَدَرَ عَلَيْهِ رِزْقَهُۥ","فَيَقُولُ رَبِّيَ أَهَٰنَنِۦ","كَلَّاۖ بَل لَّا تُكْرِمُونَ اَ۬لْيَتِيمَ","وَلَا تَحُضُّونَ عَلَىٰ طَعَامِ اِ۬لْمِسْكِينِ","وَتَأْكُلُونَ اَ۬لتُّرَاثَ أَكْلاٗ لَّمّاٗ","وَتُحِبُّونَ اَ۬لْمَالَ حُبّاٗ جَمّاٗ","كَلَّاۖ إِذَا دُكَّتِ اِ۬لْأَرْضُ دَكّاٗ دَكّاٗ","وَجَآءَ رَبُّكَ وَالْمَلَكُ صَفّاٗ صَفّاٗ","وَجِےٓءَ يَوْمَئِذِۢ بِجَهَنَّمَ","يَوْمَئِذٖ يَتَذَكَّرُ اُ۬لْإِنسَٰنُ وَأَنَّىٰ لَهُ اُ۬لذِّكْرَىٰۖ","يَقُولُ يَٰلَيْتَنِے قَدَّمْتُ لِحَيَاتِےۖ","فَيَوْمَئِذٖ لَّا يُعَذِّبُ عَذَابَهُۥ أَحَدٞ","وَلَا يُوثِقُ وَثَاقَهُۥ أَحَدٞۖ","يَٰأَيَّتُهَا اَ۬لنَّفْسُ اُ۬لْمُطْمَئِنَّةُ","اُ۪رْجِعِے إِلَىٰ رَبِّكِ رَاضِيَةٗ مَّرْضِيَّةٗ","فَادْخُلِے فِے عِبَٰدِے وَادْخُلِے جَنَّتِےۖ"]},"90":{"n":"البلد","j":30,"a":["لَا أُقْسِمُ بِهَٰذَا اَ۬لْبَلَدِ","وَأَنتَ حِلُّۢ بِهَٰذَا اَ۬لْبَلَدِ","وَوَالِدٖ وَمَا وَلَدَ","لَقَدْ خَلَقْنَا اَ۬لْإِنسَٰنَ فِے كَبَدٍۖ","أَيَحْسِبُ أَن لَّنْ يَّقْدِرَ عَلَيْهِ أَحَدٞ","يَقُولُ أَهْلَكْتُ مَالاٗ لُّبَداًۖ","أَيَحْسِبُ أَن لَّمْ يَرَهُۥ أَحَدٌۖ","أَلَمْ نَجْعَل لَّهُۥ عَيْنَيْنِ","وَلِسَاناٗ وَشَفَتَيْنِ","وَهَدَيْنَٰهُ اُ۬لنَّجْدَيْنِۖ","فَلَا اَ۪قْتَحَمَ اَ۬لْعَقَبَةَۖ","وَمَا أَدْرَيٰكَ مَا اَ۬لْعَقَبَةُۖ","فَكُّ رَقَبَةٍ","أَوْ إِطْعَامٞ فِے يَوْمٖ ذِے مَسْغَبَةٖ","يَتِيماٗ ذَا مَقْرَبَةٍ","أَوْ مِسْكِيناٗ ذَا مَتْرَبَةٖۖ","ثُمَّ كَانَ مِنَ اَ۬لذِينَ ءَامَنُواْ وَتَوَاصَوْاْ بِالصَّبْرِ وَتَوَاصَوْاْ بِالْمَرْحَمَةِۖ","أُوْلَٰٓئِكَ أَصْحَٰبُ اُ۬لْمَيْمَنَةِۖ","وَالذِينَ كَفَرُواْ بِـَٔايَٰتِنَا هُمْ أَصْحَٰبُ اُ۬لْمَشْـَٔمَةِۖ","عَلَيْهِمْ نَارٞ مُّوصَدَةُۢۖ"]},"91":{"n":"الشمس","j":30,"a":["وَالشَّمْسِ وَضُحَيٰهَا","وَالْقَمَرِ إِذَا تَلَيٰهَا","وَالنَّهَارِ إِذَا جَلَّيٰهَا","وَاليْلِ إِذَا يَغْشَيٰهَا","وَالسَّمَآءِ وَمَا بَنَيٰهَا","وَالْأَرْضِ وَمَا طَحَيٰهَا","وَنَفْسٖ وَمَا سَوَّيٰهَا","فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَيٰهَا","قَدْ أَفْلَحَ مَن زَكَّيٰهَا","وَقَدْ خَابَ مَن دَسَّيٰهَاۖ","كَذَّبَتْ ثَمُودُ بِطَغْوَيٰهَا","إِذِ اِ۪نۢبَعَثَ أَشْقَيٰهَا","فَقَالَ لَهُمْ رَسُولُ اُ۬للَّهِ نَاقَةَ اَ۬للَّهِ وَسُقْيَاهَا","فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنۢبِهِمْ فَسَوَّيٰهَاۖ","فَلَا يَخَافُ عُقْبَٰهَاۖ"]},"92":{"n":"الليل","j":30,"a":["وَاليْلِ إِذَا يَغْشَىٰ","وَالنَّهَارِ إِذَا تَجَلَّىٰ","وَمَا خَلَقَ اَ۬لذَّكَرَ وَالْأُنثَىٰ","إِنَّ سَعْيَكُمْ لَشَتَّىٰۖ","فَأَمَّا مَنْ أَعْطَىٰ وَاتَّقَىٰ","وَصَدَّقَ بِالْحُسْنَىٰ","فَسَنُيَسِّرُهُۥ لِلْيُسْرَىٰۖ","وَأَمَّا مَنۢ بَخِلَ وَاسْتَغْنَىٰ","وَكَذَّبَ بِالْحُسْنَىٰ","فَسَنُيَسِّرُهُۥ لِلْعُسْرَىٰۖ","وَمَا يُغْنِے عَنْهُ مَالُهُۥ إِذَا تَرَدَّىٰۖ","إِنَّ عَلَيْنَا لَلْهُدَىٰ","وَإِنَّ لَنَا لَلْأٓخِرَةَ وَالْأُولَىٰۖ","فَأَنذَرْتُكُمْ نَاراٗ تَلَظَّىٰ","لَا يَصْلَيٰهَا إِلَّا اَ۬لْأَشْقَى","اَ۬لذِے كَذَّبَ وَتَوَلَّىٰۖ","وَسَيُجَنَّبُهَا اَ۬لْأَتْقَى","اَ۬لذِے يُؤْتِے مَالَهُۥ يَتَزَكَّىٰۖ","وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعْمَةٖ تُجْزَىٰ","إِلَّا اَ۪بْتِغَآءَ وَجْهِ رَبِّهِ اِ۬لْأَعْلَىٰۖ","وَلَسَوْفَ يَرْضَىٰۖ"]},"93":{"n":"الضحى","j":30,"a":["وَالضُّحَىٰ","وَاليْلِ إِذَا سَجَىٰ","مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰۖ","وَلَلْأٓخِرَةُ خَيْرٞ لَّكَ مِنَ اَ۬لْأُولَىٰۖ","وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰۖ","أَلَمْ يَجِدْكَ يَتِيماٗ فَـَٔاوَىٰ","وَوَجَدَكَ ضَآلّاٗ فَهَدَىٰ","وَوَجَدَكَ عَآئِلاٗ فَأَغْنَىٰۖ","فَأَمَّا اَ۬لْيَتِيمَ فَلَا تَقْهَرْۖ","وَأَمَّا اَ۬لسَّآئِلَ فَلَا تَنْهَرْۖ","وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْۖ"]},"94":{"n":"الشرح","j":30,"a":["أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ","وَوَضَعْنَا عَنكَ وِزْرَكَ","اَ۬لذِے أَنقَضَ ظَهْرَكَ","وَرَفَعْنَا لَكَ ذِكْرَكَۖ","فَإِنَّ مَعَ اَ۬لْعُسْرِ يُسْراً","إِنَّ مَعَ اَ۬لْعُسْرِ يُسْراٗۖ","فَإِذَا فَرَغْتَ فَانصَبْ","وَإِلَىٰ رَبِّكَ فَارْغَبۖ"]},"95":{"n":"التين","j":30,"a":["وَالتِّينِ وَالزَّيْتُونِ","وَطُورِ سِينِينَ","وَهَٰذَا اَ۬لْبَلَدِ اِ۬لْأَمِينِ","لَقَدْ خَلَقْنَا اَ۬لْإِنسَٰنَ فِے أَحْسَنِ تَقْوِيمٖ","ثُمَّ رَدَدْنَٰهُ أَسْفَلَ سَٰفِلِينَ","إِلَّا اَ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ اُ۬لصَّٰلِحَٰتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٖۖ","فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِۖ","أَلَيْسَ اَ۬للَّهُ بِأَحْكَمِ اِ۬لْحَٰكِمِينَۖ"]},"96":{"n":"العلق","j":30,"a":["اِ۪قْرَأْ بِاسْمِ رَبِّكَ اَ۬لذِے خَلَقَۖ","خَلَقَ اَ۬لْإِنسَٰنَ مِنْ عَلَقٍۖ","اِ۪قْرَأْ وَرَبُّكَ اَ۬لْأَكْرَمُ","اُ۬لذِے عَلَّمَ بِالْقَلَمِ","عَلَّمَ اَ۬لْإِنسَٰنَ مَا لَمْ يَعْلَمْۖ","كَلَّا إِنَّ اَ۬لْإِنسَٰنَ لَيَطْغَىٰ","أَن رَّءَاهُ اُ۪سْتَغْنَىٰۖ","إِنَّ إِلَىٰ رَبِّكَ اَ۬لرُّجْعَىٰۖ","أَرَٰ۬يْتَ اَ۬لذِے يَنْهَىٰ","عَبْداً إِذَا صَلَّىٰۖ","أَرَٰ۬يْتَ إِن كَانَ عَلَى اَ۬لْهُدَىٰ","أَوْ أَمَرَ بِالتَّقْوَىٰ","أَرَٰ۬يْتَ إِن كَذَّبَ وَتَوَلَّىٰ","أَلَمْ يَعْلَم بِأَنَّ اَ۬للَّهَ يَرَىٰۖ","كَلَّا لَئِن لَّمْ يَنتَهِ","لَنَسْفَعاَۢ بِالنَّاصِيَةِ","نَاصِيَةٖ كَٰذِبَةٍ خَاطِئَةٖۖ","فَلْيَدْعُ نَادِيَهُۥ","سَنَدْعُ اُ۬لزَّبَانِيَةَۖ","كَلَّا لَا تُطِعْهُ وَاسْجُدْ وَاقْتَرِبۖ"]},"97":{"n":"القدر","j":30,"a":["إِنَّا أَنزَلْنَٰهُ فِے لَيْلَةِ اِ۬لْقَدْرِۖ","وَمَا أَدْرَيٰكَ مَا لَيْلَةُ اُ۬لْقَدْرِۖ","لَيْلَةُ اُ۬لْقَدْرِ خَيْرٞ مِّنْ أَلْفِ شَهْرٖۖ","تَنَزَّلُ اُ۬لْمَلَٰٓئِكَةُ وَالرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٖۖ","سَلَٰمٌ هِيَ حَتَّىٰ مَطْلَعِ اِ۬لْفَجْرِۖ"]},"98":{"n":"البينة","j":30,"a":["لَمْ يَكُنِ اِ۬لذِينَ كَفَرُواْ مِنْ أَهْلِ اِ۬لْكِتَٰبِ وَالْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ اُ۬لْبَيِّنَةُۖ","رَسُولٞ مِّنَ اَ۬للَّهِ يَتْلُواْ صُحُفاٗ مُّطَهَّرَةٗ","فِيهَا كُتُبٞ قَيِّمَةٞۖ","وَمَا تَفَرَّقَ اَ۬لذِينَ أُوتُواْ اُ۬لْكِتَٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ اُ۬لْبَيِّنَةُۖ","وَمَا أُمِرُواْ إِلَّا لِيَعْبُدُواْ اُ۬للَّهَ مُخْلِصِينَ لَهُ اُ۬لدِّينَ حُنَفَآءَ وَيُقِيمُواْ اُ۬لصَّلَوٰةَ وَيُؤْتُواْ اُ۬لزَّكَوٰةَۖ وَذَٰلِكَ دِينُ اُ۬لْقَيِّمَةِۖ","إِنَّ اَ۬لذِينَ كَفَرُواْ مِنْ أَهْلِ اِ۬لْكِتَٰبِ وَالْمُشْرِكِينَ فِے نَارِ جَهَنَّمَ خَٰلِدِينَ فِيهَاۖ أُوْلَٰٓئِكَ هُمْ شَرُّ اُ۬لْبَرِيَٓٔةِۖ","إِنَّ اَ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ اُ۬لصَّٰلِحَٰتِ أُوْلَٰٓئِكَ هُمْ خَيْرُ اُ۬لْبَرِيَٓٔةِۖ","جَزَآؤُهُمْ عِندَ رَبِّهِمْ جَنَّٰتُ عَدْنٖ تَجْرِے مِن تَحْتِهَا اَ۬لْأَنْهَٰرُ خَٰلِدِينَ فِيهَا أَبَداٗۖ رَّضِيَ اَ۬للَّهُ عَنْهُمْ وَرَضُواْ عَنْهُۖ ذَٰلِكَ لِمَنْ خَشِيَ رَبَّهُۥۖ"]},"99":{"n":"الزلزلة","j":30,"a":["إِذَا زُلْزِلَتِ اِ۬لْأَرْضُ زِلْزَالَهَا","وَأَخْرَجَتِ اِ۬لْأَرْضُ أَثْقَالَهَا","وَقَالَ اَ۬لْإِنسَٰنُ مَا لَهَا","يَوْمَئِذٖ تُحَدِّثُ أَخْبَارَهَا","بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَاۖ","يَوْمَئِذٖ يَصْدُرُ اُ۬لنَّاسُ أَشْتَاتاٗ","لِّيُرَوْاْ أَعْمَٰلَهُمْۖ","فَمَنْ يَّعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْراٗ يَرَهُۥۖ","وَمَنْ يَّعْمَلْ مِثْقَالَ ذَرَّةٖ شَرّاٗ يَرَهُۥۖ"]},"100":{"n":"العاديات","j":30,"a":["وَالْعَٰدِيَٰتِ ضَبْحاٗ","فَالْمُورِيَٰتِ قَدْحاٗ","فَالْمُغِيرَٰتِ صُبْحاٗ","فَأَثَرْنَ بِهِۦ نَقْعاٗ","فَوَسَطْنَ بِهِۦ جَمْعاً","إِنَّ اَ۬لْإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٞ","وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٞ","وَإِنَّهُۥ لِحُبِّ اِ۬لْخَيْرِ لَشَدِيدٌۖ","أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِے اِ۬لْقُبُورِ","وَحُصِّلَ مَا فِے اِ۬لصُّدُورِ","إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٖ لَّخَبِيرُۢۖ"]},"101":{"n":"القارعة","j":30,"a":["اِ۬لْقَارِعَةُ مَا اَ۬لْقَارِعَةُۖ","وَمَا أَدْرَيٰكَ مَا اَ۬لْقَارِعَةُۖ","يَوْمَ يَكُونُ اُ۬لنَّاسُ كَالْفَرَاشِ اِ۬لْمَبْثُوثِ","وَتَكُونُ اُ۬لْجِبَالُ كَالْعِهْنِ اِ۬لْمَنفُوشِۖ","فَأَمَّا مَن ثَقُلَتْ مَوَٰزِينُهُۥ","فَهْوَ فِے عِيشَةٖ رَّاضِيَةٖۖ","وَأَمَّا مَنْ خَفَّتْ مَوَٰزِينُهُۥ","فَأُمُّهُۥ هَاوِيَةٞۖ","وَمَا أَدْرَيٰكَ مَا هِيَهْۖ","نَارٌ حَامِيَةُۢۖ"]},"102":{"n":"التكاثر","j":30,"a":["أَلْهَيٰكُمُ اُ۬لتَّكَاثُرُ","حَتَّىٰ زُرْتُمُ اُ۬لْمَقَابِرَۖ","كَلَّا سَوْفَ تَعْلَمُونَ","ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَۖ","كَلَّا لَوْ تَعْلَمُونَ عِلْمَ اَ۬لْيَقِينِۖ","لَتَرَوُنَّ اَ۬لْجَحِيمَ","ثُمَّ لَتَرَوُنَّهَا عَيْنَ اَ۬لْيَقِينِ","ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ اِ۬لنَّعِيمِۖ"]},"103":{"n":"العصر","j":30,"a":["وَالْعَصْرِ إِنَّ اَ۬لْإِنسَٰنَ لَفِے خُسْرٍ","إِلَّا اَ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ اُ۬لصَّٰلِحَٰتِ وَتَوَاصَوْاْ بِالْحَقِّ","وَتَوَاصَوْاْ بِالصَّبْرِۖ"]},"104":{"n":"الهمزة","j":30,"a":["وَيْلٞ لِّكُلِّ هُمَزَةٖ لُّمَزَةٍ","اِ۬لذِے جَمَعَ مَالاٗ وَعَدَّدَهُۥ","يَحْسِبُ أَنَّ مَالَهُۥ أَخْلَدَهُۥ","كَلَّاۖ لَيُنۢبَذَنَّ فِے اِ۬لْحُطَمَةِۖ","وَمَا أَدْرَيٰكَ مَا اَ۬لْحُطَمَةُۖ","نَارُ اُ۬للَّهِ اِ۬لْمُوقَدَةُ","اُ۬لتِے تَطَّلِعُ عَلَى اَ۬لْأَفْـِٕدَةِۖ","إِنَّهَا عَلَيْهِم مُّوصَدَةٞ","فِے عَمَدٖ مُّمَدَّدَةِۢۖ"]},"105":{"n":"الفيل","j":30,"a":["أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَٰبِ اِ۬لْفِيلِۖ","أَلَمْ يَجْعَلْ كَيْدَهُمْ فِے تَضْلِيلٖ","وَأَرْسَلَ عَلَيْهِمْ طَيْراً أَبَابِيلَ","تَرْمِيهِم بِحِجَارَةٖ مِّن سِجِّيلٖ","فَجَعَلَهُمْ كَعَصْفٖ مَّأْكُولِۢۖ"]},"106":{"n":"قريش","j":30,"a":["لِإِيلَٰفِ قُرَيْشٍ","إِيلَٰفِهِمْ رِحْلَةَ اَ۬لشِّتَآءِ وَالصَّيْفِۖ","فَلْيَعْبُدُواْ رَبَّ هَٰذَا اَ۬لْبَيْتِ","اِ۬لذِے أَطْعَمَهُم مِّن جُوعٖ","وَءَامَنَهُم مِّنْ خَوْفِۢۖ"]},"107":{"n":"الماعون","j":30,"a":["أَرَٰ۬يْتَ اَ۬لذِے يُكَذِّبُ بِالدِّينِ","فَذَٰلِكَ اَ۬لذِے يَدُعُّ اُ۬لْيَتِيمَ","وَلَا يَحُضُّ عَلَىٰ طَعَامِ اِ۬لْمِسْكِينِۖ","فَوَيْلٞ لِّلْمُصَلِّينَ","اَ۬لذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ","اَ۬لذِينَ هُمْ يُرَآءُونَ وَيَمْنَعُونَ اَ۬لْمَاعُونَۖ"]},"108":{"n":"الكوثر","j":30,"a":["إِنَّا أَعْطَيْنَٰكَ اَ۬لْكَوْثَرَ","فَصَلِّ لِرَبِّكَ وَانْحَرْۖ","إِنَّ شَانِئَكَ هُوَ اَ۬لْأَبْتَرُۖ"]},"109":{"n":"الكافرون","j":30,"a":["قُلْ يَٰأَيُّهَا اَ۬لْكَٰفِرُونَ","لَا أَعْبُدُ مَا تَعْبُدُونَ","وَلَا أَنتُمْ عَٰبِدُونَ مَا أَعْبُدُۖ","وَلَا أَنَا عَابِدٞ مَّا عَبَدتُّمْ","وَلَا أَنتُمْ عَٰبِدُونَ مَا أَعْبُدُۖ","لَكُمْ دِينُكُمْ وَلِيَ دِينِۖ"]},"110":{"n":"النصر","j":30,"a":["إِذَا جَآءَ نَصْرُ اُ۬للَّهِ وَالْفَتْحُ","وَرَأَيْتَ اَ۬لنَّاسَ يَدْخُلُونَ فِے دِينِ اِ۬للَّهِ أَفْوَاجاٗ","فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُۖ إِنَّهُۥ كَانَ تَوَّاباَۢۖ"]},"111":{"n":"المسد","j":30,"a":["تَبَّتْ يَدَا أَبِے لَهَبٖ وَتَبَّۖ","مَا أَغْنَىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَۖ","سَيَصْلَىٰ نَاراٗ ذَاتَ لَهَبٖ","وَامْرَأَتُهُۥۖ حَمَّالَةُ اُ۬لْحَطَبِ","فِے جِيدِهَا حَبْلٞ مِّن مَّسَدِۢۖ"]},"112":{"n":"الإخلاص","j":30,"a":["قُلْ هُوَ اَ۬للَّهُ أَحَدٌۖ","اِ۬للَّهُ اُ۬لصَّمَدُۖ","لَمْ يَلِدْ وَلَمْ يُولَدْۖ","وَلَمْ يَكُن لَّهُۥ كُفُؤاً أَحَدُۢۖ"]},"113":{"n":"الفلق","j":30,"a":["قُلْ أَعُوذُ بِرَبِّ اِ۬لْفَلَقِ","مِن شَرِّ مَا خَلَقَ","وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ","وَمِن شَرِّ اِ۬لنَّفَّٰثَٰتِ فِے اِ۬لْعُقَدِ","وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَۖ"]},"114":{"n":"الناس","j":30,"a":["قُلْ أَعُوذُ بِرَبِّ اِ۬لنَّاسِ","مَلِكِ اِ۬لنَّاسِ","إِلَٰهِ اِ۬لنَّاسِ","مِن شَرِّ اِ۬لْوَسْوَاسِ اِ۬لْخَنَّاسِ","اِ۬لذِے يُوَسْوِسُ فِے صُدُورِ اِ۬لنَّاسِ","مِنَ اَ۬لْجِنَّةِ وَالنَّاسِۖ"]}}},"h":{"label":"رواية حفص عن عاصم","ver":"KFGQPC Hafs v18","suras":{"67":{"n":"الملك","j":29,"a":["تَبَٰرَكَ ٱلَّذِي بِيَدِهِ ٱلۡمُلۡكُ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ","ٱلَّذِي خَلَقَ ٱلۡمَوۡتَ وَٱلۡحَيَوٰةَ لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلٗاۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡغَفُورُ","ٱلَّذِي خَلَقَ سَبۡعَ سَمَٰوَٰتٖ طِبَاقٗاۖ مَّا تَرَىٰ فِي خَلۡقِ ٱلرَّحۡمَٰنِ مِن تَفَٰوُتٖۖ فَٱرۡجِعِ ٱلۡبَصَرَ هَلۡ تَرَىٰ مِن فُطُورٖ","ثُمَّ ٱرۡجِعِ ٱلۡبَصَرَ كَرَّتَيۡنِ يَنقَلِبۡ إِلَيۡكَ ٱلۡبَصَرُ خَاسِئٗا وَهُوَ حَسِيرٞ","وَلَقَدۡ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِمَصَٰبِيحَ وَجَعَلۡنَٰهَا رُجُومٗا لِّلشَّيَٰطِينِۖ وَأَعۡتَدۡنَا لَهُمۡ عَذَابَ ٱلسَّعِيرِ","وَلِلَّذِينَ كَفَرُواْ بِرَبِّهِمۡ عَذَابُ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمَصِيرُ","إِذَآ أُلۡقُواْ فِيهَا سَمِعُواْ لَهَا شَهِيقٗا وَهِيَ تَفُورُ","تَكَادُ تَمَيَّزُ مِنَ ٱلۡغَيۡظِۖ كُلَّمَآ أُلۡقِيَ فِيهَا فَوۡجٞ سَأَلَهُمۡ خَزَنَتُهَآ أَلَمۡ يَأۡتِكُمۡ نَذِيرٞ","قَالُواْ بَلَىٰ قَدۡ جَآءَنَا نَذِيرٞ فَكَذَّبۡنَا وَقُلۡنَا مَا نَزَّلَ ٱللَّهُ مِن شَيۡءٍ إِنۡ أَنتُمۡ إِلَّا فِي ضَلَٰلٖ كَبِيرٖ","وَقَالُواْ لَوۡ كُنَّا نَسۡمَعُ أَوۡ نَعۡقِلُ مَا كُنَّا فِيٓ أَصۡحَٰبِ ٱلسَّعِيرِ","فَٱعۡتَرَفُواْ بِذَنۢبِهِمۡ فَسُحۡقٗا لِّأَصۡحَٰبِ ٱلسَّعِيرِ","إِنَّ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ لَهُم مَّغۡفِرَةٞ وَأَجۡرٞ كَبِيرٞ","وَأَسِرُّواْ قَوۡلَكُمۡ أَوِ ٱجۡهَرُواْ بِهِۦٓۖ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ","أَلَا يَعۡلَمُ مَنۡ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ","هُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ ذَلُولٗا فَٱمۡشُواْ فِي مَنَاكِبِهَا وَكُلُواْ مِن رِّزۡقِهِۦۖ وَإِلَيۡهِ ٱلنُّشُورُ","ءَأَمِنتُم مَّن فِي ٱلسَّمَآءِ أَن يَخۡسِفَ بِكُمُ ٱلۡأَرۡضَ فَإِذَا هِيَ تَمُورُ","أَمۡ أَمِنتُم مَّن فِي ٱلسَّمَآءِ أَن يُرۡسِلَ عَلَيۡكُمۡ حَاصِبٗاۖ فَسَتَعۡلَمُونَ كَيۡفَ نَذِيرِ","وَلَقَدۡ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَكَيۡفَ كَانَ نَكِيرِ","أَوَلَمۡ يَرَوۡاْ إِلَى ٱلطَّيۡرِ فَوۡقَهُمۡ صَٰٓفَّٰتٖ وَيَقۡبِضۡنَۚ مَا يُمۡسِكُهُنَّ إِلَّا ٱلرَّحۡمَٰنُۚ إِنَّهُۥ بِكُلِّ شَيۡءِۭ بَصِيرٌ","أَمَّنۡ هَٰذَا ٱلَّذِي هُوَ جُندٞ لَّكُمۡ يَنصُرُكُم مِّن دُونِ ٱلرَّحۡمَٰنِۚ إِنِ ٱلۡكَٰفِرُونَ إِلَّا فِي غُرُورٍ","أَمَّنۡ هَٰذَا ٱلَّذِي يَرۡزُقُكُمۡ إِنۡ أَمۡسَكَ رِزۡقَهُۥۚ بَل لَّجُّواْ فِي عُتُوّٖ وَنُفُورٍ","أَفَمَن يَمۡشِي مُكِبًّا عَلَىٰ وَجۡهِهِۦٓ أَهۡدَىٰٓ أَمَّن يَمۡشِي سَوِيًّا عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ","قُلۡ هُوَ ٱلَّذِيٓ أَنشَأَكُمۡ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلٗا مَّا تَشۡكُرُونَ","قُلۡ هُوَ ٱلَّذِي ذَرَأَكُمۡ فِي ٱلۡأَرۡضِ وَإِلَيۡهِ تُحۡشَرُونَ","وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ","قُلۡ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٞ مُّبِينٞ","فَلَمَّا رَأَوۡهُ زُلۡفَةٗ سِيٓـَٔتۡ وُجُوهُ ٱلَّذِينَ كَفَرُواْ وَقِيلَ هَٰذَا ٱلَّذِي كُنتُم بِهِۦ تَدَّعُونَ","قُلۡ أَرَءَيۡتُمۡ إِنۡ أَهۡلَكَنِيَ ٱللَّهُ وَمَن مَّعِيَ أَوۡ رَحِمَنَا فَمَن يُجِيرُ ٱلۡكَٰفِرِينَ مِنۡ عَذَابٍ أَلِيمٖ","قُلۡ هُوَ ٱلرَّحۡمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيۡهِ تَوَكَّلۡنَاۖ فَسَتَعۡلَمُونَ مَنۡ هُوَ فِي ضَلَٰلٖ مُّبِينٖ","قُلۡ أَرَءَيۡتُمۡ إِنۡ أَصۡبَحَ مَآؤُكُمۡ غَوۡرٗا فَمَن يَأۡتِيكُم بِمَآءٖ مَّعِينِۭ"]},"68":{"n":"القلم","j":29,"a":["نٓۚ وَٱلۡقَلَمِ وَمَا يَسۡطُرُونَ","مَآ أَنتَ بِنِعۡمَةِ رَبِّكَ بِمَجۡنُونٖ","وَإِنَّ لَكَ لَأَجۡرًا غَيۡرَ مَمۡنُونٖ","وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٖ","فَسَتُبۡصِرُ وَيُبۡصِرُونَ","بِأَييِّكُمُ ٱلۡمَفۡتُونُ","إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ","فَلَا تُطِعِ ٱلۡمُكَذِّبِينَ","وَدُّواْ لَوۡ تُدۡهِنُ فَيُدۡهِنُونَ","وَلَا تُطِعۡ كُلَّ حَلَّافٖ مَّهِينٍ","هَمَّازٖ مَّشَّآءِۭ بِنَمِيمٖ","مَّنَّاعٖ لِّلۡخَيۡرِ مُعۡتَدٍ أَثِيمٍ","عُتُلِّۭ بَعۡدَ ذَٰلِكَ زَنِيمٍ","أَن كَانَ ذَا مَالٖ وَبَنِينَ","إِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلۡأَوَّلِينَ","سَنَسِمُهُۥ عَلَى ٱلۡخُرۡطُومِ","إِنَّا بَلَوۡنَٰهُمۡ كَمَا بَلَوۡنَآ أَصۡحَٰبَ ٱلۡجَنَّةِ إِذۡ أَقۡسَمُواْ لَيَصۡرِمُنَّهَا مُصۡبِحِينَ","وَلَا يَسۡتَثۡنُونَ","فَطَافَ عَلَيۡهَا طَآئِفٞ مِّن رَّبِّكَ وَهُمۡ نَآئِمُونَ","فَأَصۡبَحَتۡ كَٱلصَّرِيمِ","فَتَنَادَوۡاْ مُصۡبِحِينَ","أَنِ ٱغۡدُواْ عَلَىٰ حَرۡثِكُمۡ إِن كُنتُمۡ صَٰرِمِينَ","فَٱنطَلَقُواْ وَهُمۡ يَتَخَٰفَتُونَ","أَن لَّا يَدۡخُلَنَّهَا ٱلۡيَوۡمَ عَلَيۡكُم مِّسۡكِينٞ","وَغَدَوۡاْ عَلَىٰ حَرۡدٖ قَٰدِرِينَ","فَلَمَّا رَأَوۡهَا قَالُوٓاْ إِنَّا لَضَآلُّونَ","بَلۡ نَحۡنُ مَحۡرُومُونَ","قَالَ أَوۡسَطُهُمۡ أَلَمۡ أَقُل لَّكُمۡ لَوۡلَا تُسَبِّحُونَ","قَالُواْ سُبۡحَٰنَ رَبِّنَآ إِنَّا كُنَّا ظَٰلِمِينَ","فَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَلَٰوَمُونَ","قَالُواْ يَٰوَيۡلَنَآ إِنَّا كُنَّا طَٰغِينَ","عَسَىٰ رَبُّنَآ أَن يُبۡدِلَنَا خَيۡرٗا مِّنۡهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ","كَذَٰلِكَ ٱلۡعَذَابُۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ","إِنَّ لِلۡمُتَّقِينَ عِندَ رَبِّهِمۡ جَنَّٰتِ ٱلنَّعِيمِ","أَفَنَجۡعَلُ ٱلۡمُسۡلِمِينَ كَٱلۡمُجۡرِمِينَ","مَا لَكُمۡ كَيۡفَ تَحۡكُمُونَ","أَمۡ لَكُمۡ كِتَٰبٞ فِيهِ تَدۡرُسُونَ","إِنَّ لَكُمۡ فِيهِ لَمَا تَخَيَّرُونَ","أَمۡ لَكُمۡ أَيۡمَٰنٌ عَلَيۡنَا بَٰلِغَةٌ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ إِنَّ لَكُمۡ لَمَا تَحۡكُمُونَ","سَلۡهُمۡ أَيُّهُم بِذَٰلِكَ زَعِيمٌ","أَمۡ لَهُمۡ شُرَكَآءُ فَلۡيَأۡتُواْ بِشُرَكَآئِهِمۡ إِن كَانُواْ صَٰدِقِينَ","يَوۡمَ يُكۡشَفُ عَن سَاقٖ وَيُدۡعَوۡنَ إِلَى ٱلسُّجُودِ فَلَا يَسۡتَطِيعُونَ","خَٰشِعَةً أَبۡصَٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةٞۖ وَقَدۡ كَانُواْ يُدۡعَوۡنَ إِلَى ٱلسُّجُودِ وَهُمۡ سَٰلِمُونَ","فَذَرۡنِي وَمَن يُكَذِّبُ بِهَٰذَا ٱلۡحَدِيثِۖ سَنَسۡتَدۡرِجُهُم مِّنۡ حَيۡثُ لَا يَعۡلَمُونَ","وَأُمۡلِي لَهُمۡۚ إِنَّ كَيۡدِي مَتِينٌ","أَمۡ تَسۡـَٔلُهُمۡ أَجۡرٗا فَهُم مِّن مَّغۡرَمٖ مُّثۡقَلُونَ","أَمۡ عِندَهُمُ ٱلۡغَيۡبُ فَهُمۡ يَكۡتُبُونَ","فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلۡحُوتِ إِذۡ نَادَىٰ وَهُوَ مَكۡظُومٞ","لَّوۡلَآ أَن تَدَٰرَكَهُۥ نِعۡمَةٞ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلۡعَرَآءِ وَهُوَ مَذۡمُومٞ","فَٱجۡتَبَٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّٰلِحِينَ","وَإِن يَكَادُ ٱلَّذِينَ كَفَرُواْ لَيُزۡلِقُونَكَ بِأَبۡصَٰرِهِمۡ لَمَّا سَمِعُواْ ٱلذِّكۡرَ وَيَقُولُونَ إِنَّهُۥ لَمَجۡنُونٞ","وَمَا هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ"]},"69":{"n":"الحاقة","j":29,"a":["ٱلۡحَآقَّةُ","مَا ٱلۡحَآقَّةُ","وَمَآ أَدۡرَىٰكَ مَا ٱلۡحَآقَّةُ","كَذَّبَتۡ ثَمُودُ وَعَادُۢ بِٱلۡقَارِعَةِ","فَأَمَّا ثَمُودُ فَأُهۡلِكُواْ بِٱلطَّاغِيَةِ","وَأَمَّا عَادٞ فَأُهۡلِكُواْ بِرِيحٖ صَرۡصَرٍ عَاتِيَةٖ","سَخَّرَهَا عَلَيۡهِمۡ سَبۡعَ لَيَالٖ وَثَمَٰنِيَةَ أَيَّامٍ حُسُومٗاۖ فَتَرَى ٱلۡقَوۡمَ فِيهَا صَرۡعَىٰ كَأَنَّهُمۡ أَعۡجَازُ نَخۡلٍ خَاوِيَةٖ","فَهَلۡ تَرَىٰ لَهُم مِّنۢ بَاقِيَةٖ","وَجَآءَ فِرۡعَوۡنُ وَمَن قَبۡلَهُۥ وَٱلۡمُؤۡتَفِكَٰتُ بِٱلۡخَاطِئَةِ","فَعَصَوۡاْ رَسُولَ رَبِّهِمۡ فَأَخَذَهُمۡ أَخۡذَةٗ رَّابِيَةً","إِنَّا لَمَّا طَغَا ٱلۡمَآءُ حَمَلۡنَٰكُمۡ فِي ٱلۡجَارِيَةِ","لِنَجۡعَلَهَا لَكُمۡ تَذۡكِرَةٗ وَتَعِيَهَآ أُذُنٞ وَٰعِيَةٞ","فَإِذَا نُفِخَ فِي ٱلصُّورِ نَفۡخَةٞ وَٰحِدَةٞ","وَحُمِلَتِ ٱلۡأَرۡضُ وَٱلۡجِبَالُ فَدُكَّتَا دَكَّةٗ وَٰحِدَةٗ","فَيَوۡمَئِذٖ وَقَعَتِ ٱلۡوَاقِعَةُ","وَٱنشَقَّتِ ٱلسَّمَآءُ فَهِيَ يَوۡمَئِذٖ وَاهِيَةٞ","وَٱلۡمَلَكُ عَلَىٰٓ أَرۡجَآئِهَاۚ وَيَحۡمِلُ عَرۡشَ رَبِّكَ فَوۡقَهُمۡ يَوۡمَئِذٖ ثَمَٰنِيَةٞ","يَوۡمَئِذٖ تُعۡرَضُونَ لَا تَخۡفَىٰ مِنكُمۡ خَافِيَةٞ","فَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَيَقُولُ هَآؤُمُ ٱقۡرَءُواْ كِتَٰبِيَهۡ","إِنِّي ظَنَنتُ أَنِّي مُلَٰقٍ حِسَابِيَهۡ","فَهُوَ فِي عِيشَةٖ رَّاضِيَةٖ","فِي جَنَّةٍ عَالِيَةٖ","قُطُوفُهَا دَانِيَةٞ","كُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا بِمَآ أَسۡلَفۡتُمۡ فِي ٱلۡأَيَّامِ ٱلۡخَالِيَةِ","وَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ بِشِمَالِهِۦ فَيَقُولُ يَٰلَيۡتَنِي لَمۡ أُوتَ كِتَٰبِيَهۡ","وَلَمۡ أَدۡرِ مَا حِسَابِيَهۡ","يَٰلَيۡتَهَا كَانَتِ ٱلۡقَاضِيَةَ","مَآ أَغۡنَىٰ عَنِّي مَالِيَهۡۜ","هَلَكَ عَنِّي سُلۡطَٰنِيَهۡ","خُذُوهُ فَغُلُّوهُ","ثُمَّ ٱلۡجَحِيمَ صَلُّوهُ","ثُمَّ فِي سِلۡسِلَةٖ ذَرۡعُهَا سَبۡعُونَ ذِرَاعٗا فَٱسۡلُكُوهُ","إِنَّهُۥ كَانَ لَا يُؤۡمِنُ بِٱللَّهِ ٱلۡعَظِيمِ","وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ","فَلَيۡسَ لَهُ ٱلۡيَوۡمَ هَٰهُنَا حَمِيمٞ","وَلَا طَعَامٌ إِلَّا مِنۡ غِسۡلِينٖ","لَّا يَأۡكُلُهُۥٓ إِلَّا ٱلۡخَٰطِـُٔونَ","فَلَآ أُقۡسِمُ بِمَا تُبۡصِرُونَ","وَمَا لَا تُبۡصِرُونَ","إِنَّهُۥ لَقَوۡلُ رَسُولٖ كَرِيمٖ","وَمَا هُوَ بِقَوۡلِ شَاعِرٖۚ قَلِيلٗا مَّا تُؤۡمِنُونَ","وَلَا بِقَوۡلِ كَاهِنٖۚ قَلِيلٗا مَّا تَذَكَّرُونَ","تَنزِيلٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ","وَلَوۡ تَقَوَّلَ عَلَيۡنَا بَعۡضَ ٱلۡأَقَاوِيلِ","لَأَخَذۡنَا مِنۡهُ بِٱلۡيَمِينِ","ثُمَّ لَقَطَعۡنَا مِنۡهُ ٱلۡوَتِينَ","فَمَا مِنكُم مِّنۡ أَحَدٍ عَنۡهُ حَٰجِزِينَ","وَإِنَّهُۥ لَتَذۡكِرَةٞ لِّلۡمُتَّقِينَ","وَإِنَّا لَنَعۡلَمُ أَنَّ مِنكُم مُّكَذِّبِينَ","وَإِنَّهُۥ لَحَسۡرَةٌ عَلَى ٱلۡكَٰفِرِينَ","وَإِنَّهُۥ لَحَقُّ ٱلۡيَقِينِ","فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِيمِ"]},"70":{"n":"المعارج","j":29,"a":["سَأَلَ سَآئِلُۢ بِعَذَابٖ وَاقِعٖ","لِّلۡكَٰفِرِينَ لَيۡسَ لَهُۥ دَافِعٞ","مِّنَ ٱللَّهِ ذِي ٱلۡمَعَارِجِ","تَعۡرُجُ ٱلۡمَلَٰٓئِكَةُ وَٱلرُّوحُ إِلَيۡهِ فِي يَوۡمٖ كَانَ مِقۡدَارُهُۥ خَمۡسِينَ أَلۡفَ سَنَةٖ","فَٱصۡبِرۡ صَبۡرٗا جَمِيلًا","إِنَّهُمۡ يَرَوۡنَهُۥ بَعِيدٗا","وَنَرَىٰهُ قَرِيبٗا","يَوۡمَ تَكُونُ ٱلسَّمَآءُ كَٱلۡمُهۡلِ","وَتَكُونُ ٱلۡجِبَالُ كَٱلۡعِهۡنِ","وَلَا يَسۡـَٔلُ حَمِيمٌ حَمِيمٗا","يُبَصَّرُونَهُمۡۚ يَوَدُّ ٱلۡمُجۡرِمُ لَوۡ يَفۡتَدِي مِنۡ عَذَابِ يَوۡمِئِذِۭ بِبَنِيهِ","وَصَٰحِبَتِهِۦ وَأَخِيهِ","وَفَصِيلَتِهِ ٱلَّتِي تُـٔۡوِيهِ","وَمَن فِي ٱلۡأَرۡضِ جَمِيعٗا ثُمَّ يُنجِيهِ","كـَلَّآۖ إِنَّهَا لَظَىٰ","نَزَّاعَةٗ لِّلشَّوَىٰ","تَدۡعُواْ مَنۡ أَدۡبَرَ وَتَوَلَّىٰ","وَجَمَعَ فَأَوۡعَىٰٓ","إِنَّ ٱلۡإِنسَٰنَ خُلِقَ هَلُوعًا","إِذَا مَسَّهُ ٱلشَّرُّ جَزُوعٗا","وَإِذَا مَسَّهُ ٱلۡخَيۡرُ مَنُوعًا","إِلَّا ٱلۡمُصَلِّينَ","ٱلَّذِينَ هُمۡ عَلَىٰ صَلَاتِهِمۡ دَآئِمُونَ","وَٱلَّذِينَ فِيٓ أَمۡوَٰلِهِمۡ حَقّٞ مَّعۡلُومٞ","لِّلسَّآئِلِ وَٱلۡمَحۡرُومِ","وَٱلَّذِينَ يُصَدِّقُونَ بِيَوۡمِ ٱلدِّينِ","وَٱلَّذِينَ هُم مِّنۡ عَذَابِ رَبِّهِم مُّشۡفِقُونَ","إِنَّ عَذَابَ رَبِّهِمۡ غَيۡرُ مَأۡمُونٖ","وَٱلَّذِينَ هُمۡ لِفُرُوجِهِمۡ حَٰفِظُونَ","إِلَّا عَلَىٰٓ أَزۡوَٰجِهِمۡ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَإِنَّهُمۡ غَيۡرُ مَلُومِينَ","فَمَنِ ٱبۡتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡعَادُونَ","وَٱلَّذِينَ هُمۡ لِأَمَٰنَٰتِهِمۡ وَعَهۡدِهِمۡ رَٰعُونَ","وَٱلَّذِينَ هُم بِشَهَٰدَٰتِهِمۡ قَآئِمُونَ","وَٱلَّذِينَ هُمۡ عَلَىٰ صَلَاتِهِمۡ يُحَافِظُونَ","أُوْلَٰٓئِكَ فِي جَنَّٰتٖ مُّكۡرَمُونَ","فَمَالِ ٱلَّذِينَ كَفَرُواْ قِبَلَكَ مُهۡطِعِينَ","عَنِ ٱلۡيَمِينِ وَعَنِ ٱلشِّمَالِ عِزِينَ","أَيَطۡمَعُ كُلُّ ٱمۡرِيٕٖ مِّنۡهُمۡ أَن يُدۡخَلَ جَنَّةَ نَعِيمٖ","كـَلَّآۖ إِنَّا خَلَقۡنَٰهُم مِّمَّا يَعۡلَمُونَ","فَلَآ أُقۡسِمُ بِرَبِّ ٱلۡمَشَٰرِقِ وَٱلۡمَغَٰرِبِ إِنَّا لَقَٰدِرُونَ","عَلَىٰٓ أَن نُّبَدِّلَ خَيۡرٗا مِّنۡهُمۡ وَمَا نَحۡنُ بِمَسۡبُوقِينَ","فَذَرۡهُمۡ يَخُوضُواْ وَيَلۡعَبُواْ حَتَّىٰ يُلَٰقُواْ يَوۡمَهُمُ ٱلَّذِي يُوعَدُونَ","يَوۡمَ يَخۡرُجُونَ مِنَ ٱلۡأَجۡدَاثِ سِرَاعٗا كَأَنَّهُمۡ إِلَىٰ نُصُبٖ يُوفِضُونَ","خَٰشِعَةً أَبۡصَٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةٞۚ ذَٰلِكَ ٱلۡيَوۡمُ ٱلَّذِي كَانُواْ يُوعَدُونَ"]},"71":{"n":"نوح","j":29,"a":["إِنَّآ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦٓ أَنۡ أَنذِرۡ قَوۡمَكَ مِن قَبۡلِ أَن يَأۡتِيَهُمۡ عَذَابٌ أَلِيمٞ","قَالَ يَٰقَوۡمِ إِنِّي لَكُمۡ نَذِيرٞ مُّبِينٌ","أَنِ ٱعۡبُدُواْ ٱللَّهَ وَٱتَّقُوهُ وَأَطِيعُونِ","يَغۡفِرۡ لَكُم مِّن ذُنُوبِكُمۡ وَيُؤَخِّرۡكُمۡ إِلَىٰٓ أَجَلٖ مُّسَمًّىۚ إِنَّ أَجَلَ ٱللَّهِ إِذَا جَآءَ لَا يُؤَخَّرُۚ لَوۡ كُنتُمۡ تَعۡلَمُونَ","قَالَ رَبِّ إِنِّي دَعَوۡتُ قَوۡمِي لَيۡلٗا وَنَهَارٗا","فَلَمۡ يَزِدۡهُمۡ دُعَآءِيٓ إِلَّا فِرَارٗا","وَإِنِّي كُلَّمَا دَعَوۡتُهُمۡ لِتَغۡفِرَ لَهُمۡ جَعَلُوٓاْ أَصَٰبِعَهُمۡ فِيٓ ءَاذَانِهِمۡ وَٱسۡتَغۡشَوۡاْ ثِيَابَهُمۡ وَأَصَرُّواْ وَٱسۡتَكۡبَرُواْ ٱسۡتِكۡبَارٗا","ثُمَّ إِنِّي دَعَوۡتُهُمۡ جِهَارٗا","ثُمَّ إِنِّيٓ أَعۡلَنتُ لَهُمۡ وَأَسۡرَرۡتُ لَهُمۡ إِسۡرَارٗا","فَقُلۡتُ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ إِنَّهُۥ كَانَ غَفَّارٗا","يُرۡسِلِ ٱلسَّمَآءَ عَلَيۡكُم مِّدۡرَارٗا","وَيُمۡدِدۡكُم بِأَمۡوَٰلٖ وَبَنِينَ وَيَجۡعَل لَّكُمۡ جَنَّٰتٖ وَيَجۡعَل لَّكُمۡ أَنۡهَٰرٗا","مَّا لَكُمۡ لَا تَرۡجُونَ لِلَّهِ وَقَارٗا","وَقَدۡ خَلَقَكُمۡ أَطۡوَارًا","أَلَمۡ تَرَوۡاْ كَيۡفَ خَلَقَ ٱللَّهُ سَبۡعَ سَمَٰوَٰتٖ طِبَاقٗا","وَجَعَلَ ٱلۡقَمَرَ فِيهِنَّ نُورٗا وَجَعَلَ ٱلشَّمۡسَ سِرَاجٗا","وَٱللَّهُ أَنۢبَتَكُم مِّنَ ٱلۡأَرۡضِ نَبَاتٗا","ثُمَّ يُعِيدُكُمۡ فِيهَا وَيُخۡرِجُكُمۡ إِخۡرَاجٗا","وَٱللَّهُ جَعَلَ لَكُمُ ٱلۡأَرۡضَ بِسَاطٗا","لِّتَسۡلُكُواْ مِنۡهَا سُبُلٗا فِجَاجٗا","قَالَ نُوحٞ رَّبِّ إِنَّهُمۡ عَصَوۡنِي وَٱتَّبَعُواْ مَن لَّمۡ يَزِدۡهُ مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَارٗا","وَمَكَرُواْ مَكۡرٗا كُبَّارٗا","وَقَالُواْ لَا تَذَرُنَّ ءَالِهَتَكُمۡ وَلَا تَذَرُنَّ وَدّٗا وَلَا سُوَاعٗا وَلَا يَغُوثَ وَيَعُوقَ وَنَسۡرٗا","وَقَدۡ أَضَلُّواْ كَثِيرٗاۖ وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا ضَلَٰلٗا","مِّمَّا خَطِيٓـَٰٔتِهِمۡ أُغۡرِقُواْ فَأُدۡخِلُواْ نَارٗا فَلَمۡ يَجِدُواْ لَهُم مِّن دُونِ ٱللَّهِ أَنصَارٗا","وَقَالَ نُوحٞ رَّبِّ لَا تَذَرۡ عَلَى ٱلۡأَرۡضِ مِنَ ٱلۡكَٰفِرِينَ دَيَّارًا","إِنَّكَ إِن تَذَرۡهُمۡ يُضِلُّواْ عِبَادَكَ وَلَا يَلِدُوٓاْ إِلَّا فَاجِرٗا كَفَّارٗا","رَّبِّ ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِمَن دَخَلَ بَيۡتِيَ مُؤۡمِنٗا وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۖ وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا تَبَارَۢا"]},"72":{"n":"الجن","j":29,"a":["قُلۡ أُوحِيَ إِلَيَّ أَنَّهُ ٱسۡتَمَعَ نَفَرٞ مِّنَ ٱلۡجِنِّ فَقَالُوٓاْ إِنَّا سَمِعۡنَا قُرۡءَانًا عَجَبٗا","يَهۡدِيٓ إِلَى ٱلرُّشۡدِ فَـَٔامَنَّا بِهِۦۖ وَلَن نُّشۡرِكَ بِرَبِّنَآ أَحَدٗا","وَأَنَّهُۥ تَعَٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَٰحِبَةٗ وَلَا وَلَدٗا","وَأَنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ٱللَّهِ شَطَطٗا","وَأَنَّا ظَنَنَّآ أَن لَّن تَقُولَ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَى ٱللَّهِ كَذِبٗا","وَأَنَّهُۥ كَانَ رِجَالٞ مِّنَ ٱلۡإِنسِ يَعُوذُونَ بِرِجَالٖ مِّنَ ٱلۡجِنِّ فَزَادُوهُمۡ رَهَقٗا","وَأَنَّهُمۡ ظَنُّواْ كَمَا ظَنَنتُمۡ أَن لَّن يَبۡعَثَ ٱللَّهُ أَحَدٗا","وَأَنَّا لَمَسۡنَا ٱلسَّمَآءَ فَوَجَدۡنَٰهَا مُلِئَتۡ حَرَسٗا شَدِيدٗا وَشُهُبٗا","وَأَنَّا كُنَّا نَقۡعُدُ مِنۡهَا مَقَٰعِدَ لِلسَّمۡعِۖ فَمَن يَسۡتَمِعِ ٱلۡأٓنَ يَجِدۡ لَهُۥ شِهَابٗا رَّصَدٗا","وَأَنَّا لَا نَدۡرِيٓ أَشَرٌّ أُرِيدَ بِمَن فِي ٱلۡأَرۡضِ أَمۡ أَرَادَ بِهِمۡ رَبُّهُمۡ رَشَدٗا","وَأَنَّا مِنَّا ٱلصَّٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَۖ كُنَّا طَرَآئِقَ قِدَدٗا","وَأَنَّا ظَنَنَّآ أَن لَّن نُّعۡجِزَ ٱللَّهَ فِي ٱلۡأَرۡضِ وَلَن نُّعۡجِزَهُۥ هَرَبٗا","وَأَنَّا لَمَّا سَمِعۡنَا ٱلۡهُدَىٰٓ ءَامَنَّا بِهِۦۖ فَمَن يُؤۡمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخۡسٗا وَلَا رَهَقٗا","وَأَنَّا مِنَّا ٱلۡمُسۡلِمُونَ وَمِنَّا ٱلۡقَٰسِطُونَۖ فَمَنۡ أَسۡلَمَ فَأُوْلَٰٓئِكَ تَحَرَّوۡاْ رَشَدٗا","وَأَمَّا ٱلۡقَٰسِطُونَ فَكَانُواْ لِجَهَنَّمَ حَطَبٗا","وَأَلَّوِ ٱسۡتَقَٰمُواْ عَلَى ٱلطَّرِيقَةِ لَأَسۡقَيۡنَٰهُم مَّآءً غَدَقٗا","لِّنَفۡتِنَهُمۡ فِيهِۚ وَمَن يُعۡرِضۡ عَن ذِكۡرِ رَبِّهِۦ يَسۡلُكۡهُ عَذَابٗا صَعَدٗا","وَأَنَّ ٱلۡمَسَٰجِدَ لِلَّهِ فَلَا تَدۡعُواْ مَعَ ٱللَّهِ أَحَدٗا","وَأَنَّهُۥ لَمَّا قَامَ عَبۡدُ ٱللَّهِ يَدۡعُوهُ كَادُواْ يَكُونُونَ عَلَيۡهِ لِبَدٗا","قُلۡ إِنَّمَآ أَدۡعُواْ رَبِّي وَلَآ أُشۡرِكُ بِهِۦٓ أَحَدٗا","قُلۡ إِنِّي لَآ أَمۡلِكُ لَكُمۡ ضَرّٗا وَلَا رَشَدٗا","قُلۡ إِنِّي لَن يُجِيرَنِي مِنَ ٱللَّهِ أَحَدٞ وَلَنۡ أَجِدَ مِن دُونِهِۦ مُلۡتَحَدًا","إِلَّا بَلَٰغٗا مِّنَ ٱللَّهِ وَرِسَٰلَٰتِهِۦۚ وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدًا","حَتَّىٰٓ إِذَا رَأَوۡاْ مَا يُوعَدُونَ فَسَيَعۡلَمُونَ مَنۡ أَضۡعَفُ نَاصِرٗا وَأَقَلُّ عَدَدٗا","قُلۡ إِنۡ أَدۡرِيٓ أَقَرِيبٞ مَّا تُوعَدُونَ أَمۡ يَجۡعَلُ لَهُۥ رَبِّيٓ أَمَدًا","عَٰلِمُ ٱلۡغَيۡبِ فَلَا يُظۡهِرُ عَلَىٰ غَيۡبِهِۦٓ أَحَدًا","إِلَّا مَنِ ٱرۡتَضَىٰ مِن رَّسُولٖ فَإِنَّهُۥ يَسۡلُكُ مِنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦ رَصَدٗا","لِّيَعۡلَمَ أَن قَدۡ أَبۡلَغُواْ رِسَٰلَٰتِ رَبِّهِمۡ وَأَحَاطَ بِمَا لَدَيۡهِمۡ وَأَحۡصَىٰ كُلَّ شَيۡءٍ عَدَدَۢا"]},"73":{"n":"المزمل","j":29,"a":["يَٰٓأَيُّهَا ٱلۡمُزَّمِّلُ","قُمِ ٱلَّيۡلَ إِلَّا قَلِيلٗا","نِّصۡفَهُۥٓ أَوِ ٱنقُصۡ مِنۡهُ قَلِيلًا","أَوۡ زِدۡ عَلَيۡهِ وَرَتِّلِ ٱلۡقُرۡءَانَ تَرۡتِيلًا","إِنَّا سَنُلۡقِي عَلَيۡكَ قَوۡلٗا ثَقِيلًا","إِنَّ نَاشِئَةَ ٱلَّيۡلِ هِيَ أَشَدُّ وَطۡـٔٗا وَأَقۡوَمُ قِيلًا","إِنَّ لَكَ فِي ٱلنَّهَارِ سَبۡحٗا طَوِيلٗا","وَٱذۡكُرِ ٱسۡمَ رَبِّكَ وَتَبَتَّلۡ إِلَيۡهِ تَبۡتِيلٗا","رَّبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ لَآ إِلَٰهَ إِلَّا هُوَ فَٱتَّخِذۡهُ وَكِيلٗا","وَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَٱهۡجُرۡهُمۡ هَجۡرٗا جَمِيلٗا","وَذَرۡنِي وَٱلۡمُكَذِّبِينَ أُوْلِي ٱلنَّعۡمَةِ وَمَهِّلۡهُمۡ قَلِيلًا","إِنَّ لَدَيۡنَآ أَنكَالٗا وَجَحِيمٗا","وَطَعَامٗا ذَا غُصَّةٖ وَعَذَابًا أَلِيمٗا","يَوۡمَ تَرۡجُفُ ٱلۡأَرۡضُ وَٱلۡجِبَالُ وَكَانَتِ ٱلۡجِبَالُ كَثِيبٗا مَّهِيلًا","إِنَّآ أَرۡسَلۡنَآ إِلَيۡكُمۡ رَسُولٗا شَٰهِدًا عَلَيۡكُمۡ كَمَآ أَرۡسَلۡنَآ إِلَىٰ فِرۡعَوۡنَ رَسُولٗا","فَعَصَىٰ فِرۡعَوۡنُ ٱلرَّسُولَ فَأَخَذۡنَٰهُ أَخۡذٗا وَبِيلٗا","فَكَيۡفَ تَتَّقُونَ إِن كَفَرۡتُمۡ يَوۡمٗا يَجۡعَلُ ٱلۡوِلۡدَٰنَ شِيبًا","ٱلسَّمَآءُ مُنفَطِرُۢ بِهِۦۚ كَانَ وَعۡدُهُۥ مَفۡعُولًا","إِنَّ هَٰذِهِۦ تَذۡكِرَةٞۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا","إِنَّ رَبَّكَ يَعۡلَمُ أَنَّكَ تَقُومُ أَدۡنَىٰ مِن ثُلُثَيِ ٱلَّيۡلِ وَنِصۡفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةٞ مِّنَ ٱلَّذِينَ مَعَكَۚ وَٱللَّهُ يُقَدِّرُ ٱلَّيۡلَ وَٱلنَّهَارَۚ عَلِمَ أَن لَّن تُحۡصُوهُ فَتَابَ عَلَيۡكُمۡۖ فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنَ ٱلۡقُرۡءَانِۚ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرۡضَىٰ وَءَاخَرُونَ يَضۡرِبُونَ فِي ٱلۡأَرۡضِ يَبۡتَغُونَ مِن فَضۡلِ ٱللَّهِ وَءَاخَرُونَ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنۡهُۚ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَقۡرِضُواْ ٱللَّهَ قَرۡضًا حَسَنٗاۚ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنۡ خَيۡرٖ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَيۡرٗا وَأَعۡظَمَ أَجۡرٗاۚ وَٱسۡتَغۡفِرُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمُۢ"]},"74":{"n":"المدثر","j":29,"a":["يَٰٓأَيُّهَا ٱلۡمُدَّثِّرُ","قُمۡ فَأَنذِرۡ","وَرَبَّكَ فَكَبِّرۡ","وَثِيَابَكَ فَطَهِّرۡ","وَٱلرُّجۡزَ فَٱهۡجُرۡ","وَلَا تَمۡنُن تَسۡتَكۡثِرُ","وَلِرَبِّكَ فَٱصۡبِرۡ","فَإِذَا نُقِرَ فِي ٱلنَّاقُورِ","فَذَٰلِكَ يَوۡمَئِذٖ يَوۡمٌ عَسِيرٌ","عَلَى ٱلۡكَٰفِرِينَ غَيۡرُ يَسِيرٖ","ذَرۡنِي وَمَنۡ خَلَقۡتُ وَحِيدٗا","وَجَعَلۡتُ لَهُۥ مَالٗا مَّمۡدُودٗا","وَبَنِينَ شُهُودٗا","وَمَهَّدتُّ لَهُۥ تَمۡهِيدٗا","ثُمَّ يَطۡمَعُ أَنۡ أَزِيدَ","كـَلَّآۖ إِنَّهُۥ كَانَ لِأٓيَٰتِنَا عَنِيدٗا","سَأُرۡهِقُهُۥ صَعُودًا","إِنَّهُۥ فَكَّرَ وَقَدَّرَ","فَقُتِلَ كَيۡفَ قَدَّرَ","ثُمَّ قُتِلَ كَيۡفَ قَدَّرَ","ثُمَّ نَظَرَ","ثُمَّ عَبَسَ وَبَسَرَ","ثُمَّ أَدۡبَرَ وَٱسۡتَكۡبَرَ","فَقَالَ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ يُؤۡثَرُ","إِنۡ هَٰذَآ إِلَّا قَوۡلُ ٱلۡبَشَرِ","سَأُصۡلِيهِ سَقَرَ","وَمَآ أَدۡرَىٰكَ مَا سَقَرُ","لَا تُبۡقِي وَلَا تَذَرُ","لَوَّاحَةٞ لِّلۡبَشَرِ","عَلَيۡهَا تِسۡعَةَ عَشَرَ","وَمَا جَعَلۡنَآ أَصۡحَٰبَ ٱلنَّارِ إِلَّا مَلَٰٓئِكَةٗۖ وَمَا جَعَلۡنَا عِدَّتَهُمۡ إِلَّا فِتۡنَةٗ لِّلَّذِينَ كَفَرُواْ لِيَسۡتَيۡقِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَيَزۡدَادَ ٱلَّذِينَ ءَامَنُوٓاْ إِيمَٰنٗا وَلَا يَرۡتَابَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَٱلۡمُؤۡمِنُونَ وَلِيَقُولَ ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡكَٰفِرُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلٗاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَمَا يَعۡلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَۚ وَمَا هِيَ إِلَّا ذِكۡرَىٰ لِلۡبَشَرِ","كـَلَّا وَٱلۡقَمَرِ","وَٱلَّيۡلِ إِذۡ أَدۡبَرَ","وَٱلصُّبۡحِ إِذَآ أَسۡفَرَ","إِنَّهَا لَإِحۡدَى ٱلۡكُبَرِ","نَذِيرٗا لِّلۡبَشَرِ","لِمَن شَآءَ مِنكُمۡ أَن يَتَقَدَّمَ أَوۡ يَتَأَخَّرَ","كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡ رَهِينَةٌ","إِلَّآ أَصۡحَٰبَ ٱلۡيَمِينِ","فِي جَنَّٰتٖ يَتَسَآءَلُونَ","عَنِ ٱلۡمُجۡرِمِينَ","مَا سَلَكَكُمۡ فِي سَقَرَ","قَالُواْ لَمۡ نَكُ مِنَ ٱلۡمُصَلِّينَ","وَلَمۡ نَكُ نُطۡعِمُ ٱلۡمِسۡكِينَ","وَكُنَّا نَخُوضُ مَعَ ٱلۡخَآئِضِينَ","وَكُنَّا نُكَذِّبُ بِيَوۡمِ ٱلدِّينِ","حَتَّىٰٓ أَتَىٰنَا ٱلۡيَقِينُ","فَمَا تَنفَعُهُمۡ شَفَٰعَةُ ٱلشَّٰفِعِينَ","فَمَا لَهُمۡ عَنِ ٱلتَّذۡكِرَةِ مُعۡرِضِينَ","كَأَنَّهُمۡ حُمُرٞ مُّسۡتَنفِرَةٞ","فَرَّتۡ مِن قَسۡوَرَةِۭ","بَلۡ يُرِيدُ كُلُّ ٱمۡرِيٕٖ مِّنۡهُمۡ أَن يُؤۡتَىٰ صُحُفٗا مُّنَشَّرَةٗ","كـَلَّاۖ بَل لَّا يَخَافُونَ ٱلۡأٓخِرَةَ","كـَلَّآ إِنَّهُۥ تَذۡكِرَةٞ","فَمَن شَآءَ ذَكَرَهُۥ","وَمَا يَذۡكُرُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ هُوَ أَهۡلُ ٱلتَّقۡوَىٰ وَأَهۡلُ ٱلۡمَغۡفِرَةِ"]},"75":{"n":"القيامة","j":29,"a":["لَآ أُقۡسِمُ بِيَوۡمِ ٱلۡقِيَٰمَةِ","وَلَآ أُقۡسِمُ بِٱلنَّفۡسِ ٱللَّوَّامَةِ","أَيَحۡسَبُ ٱلۡإِنسَٰنُ أَلَّن نَّجۡمَعَ عِظَامَهُۥ","بَلَىٰ قَٰدِرِينَ عَلَىٰٓ أَن نُّسَوِّيَ بَنَانَهُۥ","بَلۡ يُرِيدُ ٱلۡإِنسَٰنُ لِيَفۡجُرَ أَمَامَهُۥ","يَسۡـَٔلُ أَيَّانَ يَوۡمُ ٱلۡقِيَٰمَةِ","فَإِذَا بَرِقَ ٱلۡبَصَرُ","وَخَسَفَ ٱلۡقَمَرُ","وَجُمِعَ ٱلشَّمۡسُ وَٱلۡقَمَرُ","يَقُولُ ٱلۡإِنسَٰنُ يَوۡمَئِذٍ أَيۡنَ ٱلۡمَفَرُّ","كـَلَّا لَا وَزَرَ","إِلَىٰ رَبِّكَ يَوۡمَئِذٍ ٱلۡمُسۡتَقَرُّ","يُنَبَّؤُاْ ٱلۡإِنسَٰنُ يَوۡمَئِذِۭ بِمَا قَدَّمَ وَأَخَّرَ","بَلِ ٱلۡإِنسَٰنُ عَلَىٰ نَفۡسِهِۦ بَصِيرَةٞ","وَلَوۡ أَلۡقَىٰ مَعَاذِيرَهُۥ","لَا تُحَرِّكۡ بِهِۦ لِسَانَكَ لِتَعۡجَلَ بِهِۦٓ","إِنَّ عَلَيۡنَا جَمۡعَهُۥ وَقُرۡءَانَهُۥ","فَإِذَا قَرَأۡنَٰهُ فَٱتَّبِعۡ قُرۡءَانَهُۥ","ثُمَّ إِنَّ عَلَيۡنَا بَيَانَهُۥ","كـَلَّا بَلۡ تُحِبُّونَ ٱلۡعَاجِلَةَ","وَتَذَرُونَ ٱلۡأٓخِرَةَ","وُجُوهٞ يَوۡمَئِذٖ نَّاضِرَةٌ","إِلَىٰ رَبِّهَا نَاظِرَةٞ","وَوُجُوهٞ يَوۡمَئِذِۭ بَاسِرَةٞ","تَظُنُّ أَن يُفۡعَلَ بِهَا فَاقِرَةٞ","كـَلَّآ إِذَا بَلَغَتِ ٱلتَّرَاقِيَ","وَقِيلَ مَنۡۜ رَاقٖ","وَظَنَّ أَنَّهُ ٱلۡفِرَاقُ","وَٱلۡتَفَّتِ ٱلسَّاقُ بِٱلسَّاقِ","إِلَىٰ رَبِّكَ يَوۡمَئِذٍ ٱلۡمَسَاقُ","فَلَا صَدَّقَ وَلَا صَلَّىٰ","وَلَٰكِن كَذَّبَ وَتَوَلَّىٰ","ثُمَّ ذَهَبَ إِلَىٰٓ أَهۡلِهِۦ يَتَمَطَّىٰٓ","أَوۡلَىٰ لَكَ فَأَوۡلَىٰ","ثُمَّ أَوۡلَىٰ لَكَ فَأَوۡلَىٰٓ","أَيَحۡسَبُ ٱلۡإِنسَٰنُ أَن يُتۡرَكَ سُدًى","أَلَمۡ يَكُ نُطۡفَةٗ مِّن مَّنِيّٖ يُمۡنَىٰ","ثُمَّ كَانَ عَلَقَةٗ فَخَلَقَ فَسَوَّىٰ","فَجَعَلَ مِنۡهُ ٱلزَّوۡجَيۡنِ ٱلذَّكَرَ وَٱلۡأُنثَىٰٓ","أَلَيۡسَ ذَٰلِكَ بِقَٰدِرٍ عَلَىٰٓ أَن يُحۡـِۧيَ ٱلۡمَوۡتَىٰ"]},"76":{"n":"الإنسان","j":29,"a":["هَلۡ أَتَىٰ عَلَى ٱلۡإِنسَٰنِ حِينٞ مِّنَ ٱلدَّهۡرِ لَمۡ يَكُن شَيۡـٔٗا مَّذۡكُورًا","إِنَّا خَلَقۡنَا ٱلۡإِنسَٰنَ مِن نُّطۡفَةٍ أَمۡشَاجٖ نَّبۡتَلِيهِ فَجَعَلۡنَٰهُ سَمِيعَۢا بَصِيرًا","إِنَّا هَدَيۡنَٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرٗا وَإِمَّا كَفُورًا","إِنَّآ أَعۡتَدۡنَا لِلۡكَٰفِرِينَ سَلَٰسِلَاْ وَأَغۡلَٰلٗا وَسَعِيرًا","إِنَّ ٱلۡأَبۡرَارَ يَشۡرَبُونَ مِن كَأۡسٖ كَانَ مِزَاجُهَا كَافُورًا","عَيۡنٗا يَشۡرَبُ بِهَا عِبَادُ ٱللَّهِ يُفَجِّرُونَهَا تَفۡجِيرٗا","يُوفُونَ بِٱلنَّذۡرِ وَيَخَافُونَ يَوۡمٗا كَانَ شَرُّهُۥ مُسۡتَطِيرٗا","وَيُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسۡكِينٗا وَيَتِيمٗا وَأَسِيرًا","إِنَّمَا نُطۡعِمُكُمۡ لِوَجۡهِ ٱللَّهِ لَا نُرِيدُ مِنكُمۡ جَزَآءٗ وَلَا شُكُورًا","إِنَّا نَخَافُ مِن رَّبِّنَا يَوۡمًا عَبُوسٗا قَمۡطَرِيرٗا","فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَٰلِكَ ٱلۡيَوۡمِ وَلَقَّىٰهُمۡ نَضۡرَةٗ وَسُرُورٗا","وَجَزَىٰهُم بِمَا صَبَرُواْ جَنَّةٗ وَحَرِيرٗا","مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلۡأَرَآئِكِۖ لَا يَرَوۡنَ فِيهَا شَمۡسٗا وَلَا زَمۡهَرِيرٗا","وَدَانِيَةً عَلَيۡهِمۡ ظِلَٰلُهَا وَذُلِّلَتۡ قُطُوفُهَا تَذۡلِيلٗا","وَيُطَافُ عَلَيۡهِم بِـَٔانِيَةٖ مِّن فِضَّةٖ وَأَكۡوَابٖ كَانَتۡ قَوَارِيرَا۠","قَوَارِيرَاْ مِن فِضَّةٖ قَدَّرُوهَا تَقۡدِيرٗا","وَيُسۡقَوۡنَ فِيهَا كَأۡسٗا كَانَ مِزَاجُهَا زَنجَبِيلًا","عَيۡنٗا فِيهَا تُسَمَّىٰ سَلۡسَبِيلٗا","وَيَطُوفُ عَلَيۡهِمۡ وِلۡدَٰنٞ مُّخَلَّدُونَ إِذَا رَأَيۡتَهُمۡ حَسِبۡتَهُمۡ لُؤۡلُؤٗا مَّنثُورٗا","وَإِذَا رَأَيۡتَ ثَمَّ رَأَيۡتَ نَعِيمٗا وَمُلۡكٗا كَبِيرًا","عَٰلِيَهُمۡ ثِيَابُ سُندُسٍ خُضۡرٞ وَإِسۡتَبۡرَقٞۖ وَحُلُّوٓاْ أَسَاوِرَ مِن فِضَّةٖ وَسَقَىٰهُمۡ رَبُّهُمۡ شَرَابٗا طَهُورًا","إِنَّ هَٰذَا كَانَ لَكُمۡ جَزَآءٗ وَكَانَ سَعۡيُكُم مَّشۡكُورًا","إِنَّا نَحۡنُ نَزَّلۡنَا عَلَيۡكَ ٱلۡقُرۡءَانَ تَنزِيلٗا","فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تُطِعۡ مِنۡهُمۡ ءَاثِمًا أَوۡ كَفُورٗا","وَٱذۡكُرِ ٱسۡمَ رَبِّكَ بُكۡرَةٗ وَأَصِيلٗا","وَمِنَ ٱلَّيۡلِ فَٱسۡجُدۡ لَهُۥ وَسَبِّحۡهُ لَيۡلٗا طَوِيلًا","إِنَّ هَٰٓؤُلَآءِ يُحِبُّونَ ٱلۡعَاجِلَةَ وَيَذَرُونَ وَرَآءَهُمۡ يَوۡمٗا ثَقِيلٗا","نَّحۡنُ خَلَقۡنَٰهُمۡ وَشَدَدۡنَآ أَسۡرَهُمۡۖ وَإِذَا شِئۡنَا بَدَّلۡنَآ أَمۡثَٰلَهُمۡ تَبۡدِيلًا","إِنَّ هَٰذِهِۦ تَذۡكِرَةٞۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلٗا","وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا","يُدۡخِلُ مَن يَشَآءُ فِي رَحۡمَتِهِۦۚ وَٱلظَّٰلِمِينَ أَعَدَّ لَهُمۡ عَذَابًا أَلِيمَۢا"]},"77":{"n":"المرسلات","j":29,"a":["وَٱلۡمُرۡسَلَٰتِ عُرۡفٗا","فَٱلۡعَٰصِفَٰتِ عَصۡفٗا","وَٱلنَّٰشِرَٰتِ نَشۡرٗا","فَٱلۡفَٰرِقَٰتِ فَرۡقٗا","فَٱلۡمُلۡقِيَٰتِ ذِكۡرًا","عُذۡرًا أَوۡ نُذۡرًا","إِنَّمَا تُوعَدُونَ لَوَٰقِعٞ","فَإِذَا ٱلنُّجُومُ طُمِسَتۡ","وَإِذَا ٱلسَّمَآءُ فُرِجَتۡ","وَإِذَا ٱلۡجِبَالُ نُسِفَتۡ","وَإِذَا ٱلرُّسُلُ أُقِّتَتۡ","لِأَيِّ يَوۡمٍ أُجِّلَتۡ","لِيَوۡمِ ٱلۡفَصۡلِ","وَمَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلۡفَصۡلِ","وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","أَلَمۡ نُهۡلِكِ ٱلۡأَوَّلِينَ","ثُمَّ نُتۡبِعُهُمُ ٱلۡأٓخِرِينَ","كَذَٰلِكَ نَفۡعَلُ بِٱلۡمُجۡرِمِينَ","وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","أَلَمۡ نَخۡلُقكُّم مِّن مَّآءٖ مَّهِينٖ","فَجَعَلۡنَٰهُ فِي قَرَارٖ مَّكِينٍ","إِلَىٰ قَدَرٖ مَّعۡلُومٖ","فَقَدَرۡنَا فَنِعۡمَ ٱلۡقَٰدِرُونَ","وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","أَلَمۡ نَجۡعَلِ ٱلۡأَرۡضَ كِفَاتًا","أَحۡيَآءٗ وَأَمۡوَٰتٗا","وَجَعَلۡنَا فِيهَا رَوَٰسِيَ شَٰمِخَٰتٖ وَأَسۡقَيۡنَٰكُم مَّآءٗ فُرَاتٗا","وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","ٱنطَلِقُوٓاْ إِلَىٰ مَا كُنتُم بِهِۦ تُكَذِّبُونَ","ٱنطَلِقُوٓاْ إِلَىٰ ظِلّٖ ذِي ثَلَٰثِ شُعَبٖ","لَّا ظَلِيلٖ وَلَا يُغۡنِي مِنَ ٱللَّهَبِ","إِنَّهَا تَرۡمِي بِشَرَرٖ كَٱلۡقَصۡرِ","كَأَنَّهُۥ جِمَٰلَتٞ صُفۡرٞ","وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","هَٰذَا يَوۡمُ لَا يَنطِقُونَ","وَلَا يُؤۡذَنُ لَهُمۡ فَيَعۡتَذِرُونَ","وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","هَٰذَا يَوۡمُ ٱلۡفَصۡلِۖ جَمَعۡنَٰكُمۡ وَٱلۡأَوَّلِينَ","فَإِن كَانَ لَكُمۡ كَيۡدٞ فَكِيدُونِ","وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","إِنَّ ٱلۡمُتَّقِينَ فِي ظِلَٰلٖ وَعُيُونٖ","وَفَوَٰكِهَ مِمَّا يَشۡتَهُونَ","كُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا بِمَا كُنتُمۡ تَعۡمَلُونَ","إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ","وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","كُلُواْ وَتَمَتَّعُواْ قَلِيلًا إِنَّكُم مُّجۡرِمُونَ","وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","وَإِذَا قِيلَ لَهُمُ ٱرۡكَعُواْ لَا يَرۡكَعُونَ","وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","فَبِأَيِّ حَدِيثِۭ بَعۡدَهُۥ يُؤۡمِنُونَ"]},"78":{"n":"النبإ","j":30,"a":["عَمَّ يَتَسَآءَلُونَ","عَنِ ٱلنَّبَإِ ٱلۡعَظِيمِ","ٱلَّذِي هُمۡ فِيهِ مُخۡتَلِفُونَ","كـَلَّا سَيَعۡلَمُونَ","ثُمَّ كـَلَّا سَيَعۡلَمُونَ","أَلَمۡ نَجۡعَلِ ٱلۡأَرۡضَ مِهَٰدٗا","وَٱلۡجِبَالَ أَوۡتَادٗا","وَخَلَقۡنَٰكُمۡ أَزۡوَٰجٗا","وَجَعَلۡنَا نَوۡمَكُمۡ سُبَاتٗا","وَجَعَلۡنَا ٱلَّيۡلَ لِبَاسٗا","وَجَعَلۡنَا ٱلنَّهَارَ مَعَاشٗا","وَبَنَيۡنَا فَوۡقَكُمۡ سَبۡعٗا شِدَادٗا","وَجَعَلۡنَا سِرَاجٗا وَهَّاجٗا","وَأَنزَلۡنَا مِنَ ٱلۡمُعۡصِرَٰتِ مَآءٗ ثَجَّاجٗا","لِّنُخۡرِجَ بِهِۦ حَبّٗا وَنَبَاتٗا","وَجَنَّٰتٍ أَلۡفَافًا","إِنَّ يَوۡمَ ٱلۡفَصۡلِ كَانَ مِيقَٰتٗا","يَوۡمَ يُنفَخُ فِي ٱلصُّورِ فَتَأۡتُونَ أَفۡوَاجٗا","وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتۡ أَبۡوَٰبٗا","وَسُيِّرَتِ ٱلۡجِبَالُ فَكَانَتۡ سَرَابًا","إِنَّ جَهَنَّمَ كَانَتۡ مِرۡصَادٗا","لِّلطَّٰغِينَ مَـَٔابٗا","لَّٰبِثِينَ فِيهَآ أَحۡقَابٗا","لَّا يَذُوقُونَ فِيهَا بَرۡدٗا وَلَا شَرَابًا","إِلَّا حَمِيمٗا وَغَسَّاقٗا","جَزَآءٗ وِفَاقًا","إِنَّهُمۡ كَانُواْ لَا يَرۡجُونَ حِسَابٗا","وَكَذَّبُواْ بِـَٔايَٰتِنَا كِذَّابٗا","وَكُلَّ شَيۡءٍ أَحۡصَيۡنَٰهُ كِتَٰبٗا","فَذُوقُواْ فَلَن نَّزِيدَكُمۡ إِلَّا عَذَابًا","إِنَّ لِلۡمُتَّقِينَ مَفَازًا","حَدَآئِقَ وَأَعۡنَٰبٗا","وَكَوَاعِبَ أَتۡرَابٗا","وَكَأۡسٗا دِهَاقٗا","لَّا يَسۡمَعُونَ فِيهَا لَغۡوٗا وَلَا كِذَّٰبٗا","جَزَآءٗ مِّن رَّبِّكَ عَطَآءً حِسَابٗا","رَّبِّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا ٱلرَّحۡمَٰنِۖ لَا يَمۡلِكُونَ مِنۡهُ خِطَابٗا","يَوۡمَ يَقُومُ ٱلرُّوحُ وَٱلۡمَلَٰٓئِكَةُ صَفّٗاۖ لَّا يَتَكَلَّمُونَ إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَٰنُ وَقَالَ صَوَابٗا","ذَٰلِكَ ٱلۡيَوۡمُ ٱلۡحَقُّۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا","إِنَّآ أَنذَرۡنَٰكُمۡ عَذَابٗا قَرِيبٗا يَوۡمَ يَنظُرُ ٱلۡمَرۡءُ مَا قَدَّمَتۡ يَدَاهُ وَيَقُولُ ٱلۡكَافِرُ يَٰلَيۡتَنِي كُنتُ تُرَٰبَۢا"]},"79":{"n":"النازعات","j":30,"a":["وَٱلنَّٰزِعَٰتِ غَرۡقٗا","وَٱلنَّٰشِطَٰتِ نَشۡطٗا","وَٱلسَّٰبِحَٰتِ سَبۡحٗا","فَٱلسَّٰبِقَٰتِ سَبۡقٗا","فَٱلۡمُدَبِّرَٰتِ أَمۡرٗا","يَوۡمَ تَرۡجُفُ ٱلرَّاجِفَةُ","تَتۡبَعُهَا ٱلرَّادِفَةُ","قُلُوبٞ يَوۡمَئِذٖ وَاجِفَةٌ","أَبۡصَٰرُهَا خَٰشِعَةٞ","يَقُولُونَ أَءِنَّا لَمَرۡدُودُونَ فِي ٱلۡحَافِرَةِ","أَءِذَا كُنَّا عِظَٰمٗا نَّخِرَةٗ","قَالُواْ تِلۡكَ إِذٗا كَرَّةٌ خَاسِرَةٞ","فَإِنَّمَا هِيَ زَجۡرَةٞ وَٰحِدَةٞ","فَإِذَا هُم بِٱلسَّاهِرَةِ","هَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ","إِذۡ نَادَىٰهُ رَبُّهُۥ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوًى","ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ","فَقُلۡ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ","وَأَهۡدِيَكَ إِلَىٰ رَبِّكَ فَتَخۡشَىٰ","فَأَرَىٰهُ ٱلۡأٓيَةَ ٱلۡكُبۡرَىٰ","فَكَذَّبَ وَعَصَىٰ","ثُمَّ أَدۡبَرَ يَسۡعَىٰ","فَحَشَرَ فَنَادَىٰ","فَقَالَ أَنَا۠ رَبُّكُمُ ٱلۡأَعۡلَىٰ","فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلۡأٓخِرَةِ وَٱلۡأُولَىٰٓ","إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّمَن يَخۡشَىٰٓ","ءَأَنتُمۡ أَشَدُّ خَلۡقًا أَمِ ٱلسَّمَآءُۚ بَنَىٰهَا","رَفَعَ سَمۡكَهَا فَسَوَّىٰهَا","وَأَغۡطَشَ لَيۡلَهَا وَأَخۡرَجَ ضُحَىٰهَا","وَٱلۡأَرۡضَ بَعۡدَ ذَٰلِكَ دَحَىٰهَآ","أَخۡرَجَ مِنۡهَا مَآءَهَا وَمَرۡعَىٰهَا","وَٱلۡجِبَالَ أَرۡسَىٰهَا","مَتَٰعٗا لَّكُمۡ وَلِأَنۡعَٰمِكُمۡ","فَإِذَا جَآءَتِ ٱلطَّآمَّةُ ٱلۡكُبۡرَىٰ","يَوۡمَ يَتَذَكَّرُ ٱلۡإِنسَٰنُ مَا سَعَىٰ","وَبُرِّزَتِ ٱلۡجَحِيمُ لِمَن يَرَىٰ","فَأَمَّا مَن طَغَىٰ","وَءَاثَرَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا","فَإِنَّ ٱلۡجَحِيمَ هِيَ ٱلۡمَأۡوَىٰ","وَأَمَّا مَنۡ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفۡسَ عَنِ ٱلۡهَوَىٰ","فَإِنَّ ٱلۡجَنَّةَ هِيَ ٱلۡمَأۡوَىٰ","يَسۡـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرۡسَىٰهَا","فِيمَ أَنتَ مِن ذِكۡرَىٰهَآ","إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ","إِنَّمَآ أَنتَ مُنذِرُ مَن يَخۡشَىٰهَا","كَأَنَّهُمۡ يَوۡمَ يَرَوۡنَهَا لَمۡ يَلۡبَثُوٓاْ إِلَّا عَشِيَّةً أَوۡ ضُحَىٰهَا"]},"80":{"n":"عبس","j":30,"a":["عَبَسَ وَتَوَلَّىٰٓ","أَن جَآءَهُ ٱلۡأَعۡمَىٰ","وَمَا يُدۡرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ","أَوۡ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكۡرَىٰٓ","أَمَّا مَنِ ٱسۡتَغۡنَىٰ","فَأَنتَ لَهُۥ تَصَدَّىٰ","وَمَا عَلَيۡكَ أَلَّا يَزَّكَّىٰ","وَأَمَّا مَن جَآءَكَ يَسۡعَىٰ","وَهُوَ يَخۡشَىٰ","فَأَنتَ عَنۡهُ تَلَهَّىٰ","كـَلَّآ إِنَّهَا تَذۡكِرَةٞ","فَمَن شَآءَ ذَكَرَهُۥ","فِي صُحُفٖ مُّكَرَّمَةٖ","مَّرۡفُوعَةٖ مُّطَهَّرَةِۭ","بِأَيۡدِي سَفَرَةٖ","كِرَامِۭ بَرَرَةٖ","قُتِلَ ٱلۡإِنسَٰنُ مَآ أَكۡفَرَهُۥ","مِنۡ أَيِّ شَيۡءٍ خَلَقَهُۥ","مِن نُّطۡفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ","ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ","ثُمَّ أَمَاتَهُۥ فَأَقۡبَرَهُۥ","ثُمَّ إِذَا شَآءَ أَنشَرَهُۥ","كـَلَّا لَمَّا يَقۡضِ مَآ أَمَرَهُۥ","فَلۡيَنظُرِ ٱلۡإِنسَٰنُ إِلَىٰ طَعَامِهِۦٓ","أَنَّا صَبَبۡنَا ٱلۡمَآءَ صَبّٗا","ثُمَّ شَقَقۡنَا ٱلۡأَرۡضَ شَقّٗا","فَأَنۢبَتۡنَا فِيهَا حَبّٗا","وَعِنَبٗا وَقَضۡبٗا","وَزَيۡتُونٗا وَنَخۡلٗا","وَحَدَآئِقَ غُلۡبٗا","وَفَٰكِهَةٗ وَأَبّٗا","مَّتَٰعٗا لَّكُمۡ وَلِأَنۡعَٰمِكُمۡ","فَإِذَا جَآءَتِ ٱلصَّآخَّةُ","يَوۡمَ يَفِرُّ ٱلۡمَرۡءُ مِنۡ أَخِيهِ","وَأُمِّهِۦ وَأَبِيهِ","وَصَٰحِبَتِهِۦ وَبَنِيهِ","لِكُلِّ ٱمۡرِيٕٖ مِّنۡهُمۡ يَوۡمَئِذٖ شَأۡنٞ يُغۡنِيهِ","وُجُوهٞ يَوۡمَئِذٖ مُّسۡفِرَةٞ","ضَاحِكَةٞ مُّسۡتَبۡشِرَةٞ","وَوُجُوهٞ يَوۡمَئِذٍ عَلَيۡهَا غَبَرَةٞ","تَرۡهَقُهَا قَتَرَةٌ","أُوْلَٰٓئِكَ هُمُ ٱلۡكَفَرَةُ ٱلۡفَجَرَةُ"]},"81":{"n":"التكوير","j":30,"a":["إِذَا ٱلشَّمۡسُ كُوِّرَتۡ","وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتۡ","وَإِذَا ٱلۡجِبَالُ سُيِّرَتۡ","وَإِذَا ٱلۡعِشَارُ عُطِّلَتۡ","وَإِذَا ٱلۡوُحُوشُ حُشِرَتۡ","وَإِذَا ٱلۡبِحَارُ سُجِّرَتۡ","وَإِذَا ٱلنُّفُوسُ زُوِّجَتۡ","وَإِذَا ٱلۡمَوۡءُۥدَةُ سُئِلَتۡ","بِأَيِّ ذَنۢبٖ قُتِلَتۡ","وَإِذَا ٱلصُّحُفُ نُشِرَتۡ","وَإِذَا ٱلسَّمَآءُ كُشِطَتۡ","وَإِذَا ٱلۡجَحِيمُ سُعِّرَتۡ","وَإِذَا ٱلۡجَنَّةُ أُزۡلِفَتۡ","عَلِمَتۡ نَفۡسٞ مَّآ أَحۡضَرَتۡ","فَلَآ أُقۡسِمُ بِٱلۡخُنَّسِ","ٱلۡجَوَارِ ٱلۡكُنَّسِ","وَٱلَّيۡلِ إِذَا عَسۡعَسَ","وَٱلصُّبۡحِ إِذَا تَنَفَّسَ","إِنَّهُۥ لَقَوۡلُ رَسُولٖ كَرِيمٖ","ذِي قُوَّةٍ عِندَ ذِي ٱلۡعَرۡشِ مَكِينٖ","مُّطَاعٖ ثَمَّ أَمِينٖ","وَمَا صَاحِبُكُم بِمَجۡنُونٖ","وَلَقَدۡ رَءَاهُ بِٱلۡأُفُقِ ٱلۡمُبِينِ","وَمَا هُوَ عَلَى ٱلۡغَيۡبِ بِضَنِينٖ","وَمَا هُوَ بِقَوۡلِ شَيۡطَٰنٖ رَّجِيمٖ","فَأَيۡنَ تَذۡهَبُونَ","إِنۡ هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ","لِمَن شَآءَ مِنكُمۡ أَن يَسۡتَقِيمَ","وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ"]},"82":{"n":"الانفطار","j":30,"a":["إِذَا ٱلسَّمَآءُ ٱنفَطَرَتۡ","وَإِذَا ٱلۡكَوَاكِبُ ٱنتَثَرَتۡ","وَإِذَا ٱلۡبِحَارُ فُجِّرَتۡ","وَإِذَا ٱلۡقُبُورُ بُعۡثِرَتۡ","عَلِمَتۡ نَفۡسٞ مَّا قَدَّمَتۡ وَأَخَّرَتۡ","يَٰٓأَيُّهَا ٱلۡإِنسَٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلۡكَرِيمِ","ٱلَّذِي خَلَقَكَ فَسَوَّىٰكَ فَعَدَلَكَ","فِيٓ أَيِّ صُورَةٖ مَّا شَآءَ رَكَّبَكَ","كـَلَّا بَلۡ تُكَذِّبُونَ بِٱلدِّينِ","وَإِنَّ عَلَيۡكُمۡ لَحَٰفِظِينَ","كِرَامٗا كَٰتِبِينَ","يَعۡلَمُونَ مَا تَفۡعَلُونَ","إِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٖ","وَإِنَّ ٱلۡفُجَّارَ لَفِي جَحِيمٖ","يَصۡلَوۡنَهَا يَوۡمَ ٱلدِّينِ","وَمَا هُمۡ عَنۡهَا بِغَآئِبِينَ","وَمَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلدِّينِ","ثُمَّ مَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلدِّينِ","يَوۡمَ لَا تَمۡلِكُ نَفۡسٞ لِّنَفۡسٖ شَيۡـٔٗاۖ وَٱلۡأَمۡرُ يَوۡمَئِذٖ لِّلَّهِ"]},"83":{"n":"المطففين","j":30,"a":["وَيۡلٞ لِّلۡمُطَفِّفِينَ","ٱلَّذِينَ إِذَا ٱكۡتَالُواْ عَلَى ٱلنَّاسِ يَسۡتَوۡفُونَ","وَإِذَا كَالُوهُمۡ أَو وَّزَنُوهُمۡ يُخۡسِرُونَ","أَلَا يَظُنُّ أُوْلَٰٓئِكَ أَنَّهُم مَّبۡعُوثُونَ","لِيَوۡمٍ عَظِيمٖ","يَوۡمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلۡعَٰلَمِينَ","كـَلَّآ إِنَّ كِتَٰبَ ٱلۡفُجَّارِ لَفِي سِجِّينٖ","وَمَآ أَدۡرَىٰكَ مَا سِجِّينٞ","كِتَٰبٞ مَّرۡقُومٞ","وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","ٱلَّذِينَ يُكَذِّبُونَ بِيَوۡمِ ٱلدِّينِ","وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعۡتَدٍ أَثِيمٍ","إِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلۡأَوَّلِينَ","كـَلَّاۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكۡسِبُونَ","كـَلَّآ إِنَّهُمۡ عَن رَّبِّهِمۡ يَوۡمَئِذٖ لَّمَحۡجُوبُونَ","ثُمَّ إِنَّهُمۡ لَصَالُواْ ٱلۡجَحِيمِ","ثُمَّ يُقَالُ هَٰذَا ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ","كـَلَّآ إِنَّ كِتَٰبَ ٱلۡأَبۡرَارِ لَفِي عِلِّيِّينَ","وَمَآ أَدۡرَىٰكَ مَا عِلِّيُّونَ","كِتَٰبٞ مَّرۡقُومٞ","يَشۡهَدُهُ ٱلۡمُقَرَّبُونَ","إِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٍ","عَلَى ٱلۡأَرَآئِكِ يَنظُرُونَ","تَعۡرِفُ فِي وُجُوهِهِمۡ نَضۡرَةَ ٱلنَّعِيمِ","يُسۡقَوۡنَ مِن رَّحِيقٖ مَّخۡتُومٍ","خِتَٰمُهُۥ مِسۡكٞۚ وَفِي ذَٰلِكَ فَلۡيَتَنَافَسِ ٱلۡمُتَنَٰفِسُونَ","وَمِزَاجُهُۥ مِن تَسۡنِيمٍ","عَيۡنٗا يَشۡرَبُ بِهَا ٱلۡمُقَرَّبُونَ","إِنَّ ٱلَّذِينَ أَجۡرَمُواْ كَانُواْ مِنَ ٱلَّذِينَ ءَامَنُواْ يَضۡحَكُونَ","وَإِذَا مَرُّواْ بِهِمۡ يَتَغَامَزُونَ","وَإِذَا ٱنقَلَبُوٓاْ إِلَىٰٓ أَهۡلِهِمُ ٱنقَلَبُواْ فَكِهِينَ","وَإِذَا رَأَوۡهُمۡ قَالُوٓاْ إِنَّ هَٰٓؤُلَآءِ لَضَآلُّونَ","وَمَآ أُرۡسِلُواْ عَلَيۡهِمۡ حَٰفِظِينَ","فَٱلۡيَوۡمَ ٱلَّذِينَ ءَامَنُواْ مِنَ ٱلۡكُفَّارِ يَضۡحَكُونَ","عَلَى ٱلۡأَرَآئِكِ يَنظُرُونَ","هَلۡ ثُوِّبَ ٱلۡكُفَّارُ مَا كَانُواْ يَفۡعَلُونَ"]},"84":{"n":"الانشقاق","j":30,"a":["إِذَا ٱلسَّمَآءُ ٱنشَقَّتۡ","وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ","وَإِذَا ٱلۡأَرۡضُ مُدَّتۡ","وَأَلۡقَتۡ مَا فِيهَا وَتَخَلَّتۡ","وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ","يَٰٓأَيُّهَا ٱلۡإِنسَٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدۡحٗا فَمُلَٰقِيهِ","فَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ","فَسَوۡفَ يُحَاسَبُ حِسَابٗا يَسِيرٗا","وَيَنقَلِبُ إِلَىٰٓ أَهۡلِهِۦ مَسۡرُورٗا","وَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ وَرَآءَ ظَهۡرِهِۦ","فَسَوۡفَ يَدۡعُواْ ثُبُورٗا","وَيَصۡلَىٰ سَعِيرًا","إِنَّهُۥ كَانَ فِيٓ أَهۡلِهِۦ مَسۡرُورًا","إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ","بَلَىٰٓۚ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرٗا","فَلَآ أُقۡسِمُ بِٱلشَّفَقِ","وَٱلَّيۡلِ وَمَا وَسَقَ","وَٱلۡقَمَرِ إِذَا ٱتَّسَقَ","لَتَرۡكَبُنَّ طَبَقًا عَن طَبَقٖ","فَمَا لَهُمۡ لَا يُؤۡمِنُونَ","وَإِذَا قُرِئَ عَلَيۡهِمُ ٱلۡقُرۡءَانُ لَا يَسۡجُدُونَۤ۩","بَلِ ٱلَّذِينَ كَفَرُواْ يُكَذِّبُونَ","وَٱللَّهُ أَعۡلَمُ بِمَا يُوعُونَ","فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ","إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونِۭ"]},"85":{"n":"البروج","j":30,"a":["وَٱلسَّمَآءِ ذَاتِ ٱلۡبُرُوجِ","وَٱلۡيَوۡمِ ٱلۡمَوۡعُودِ","وَشَاهِدٖ وَمَشۡهُودٖ","قُتِلَ أَصۡحَٰبُ ٱلۡأُخۡدُودِ","ٱلنَّارِ ذَاتِ ٱلۡوَقُودِ","إِذۡ هُمۡ عَلَيۡهَا قُعُودٞ","وَهُمۡ عَلَىٰ مَا يَفۡعَلُونَ بِٱلۡمُؤۡمِنِينَ شُهُودٞ","وَمَا نَقَمُواْ مِنۡهُمۡ إِلَّآ أَن يُؤۡمِنُواْ بِٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ","ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ","إِنَّ ٱلَّذِينَ فَتَنُواْ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ ثُمَّ لَمۡ يَتُوبُواْ فَلَهُمۡ عَذَابُ جَهَنَّمَ وَلَهُمۡ عَذَابُ ٱلۡحَرِيقِ","إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُمۡ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡكَبِيرُ","إِنَّ بَطۡشَ رَبِّكَ لَشَدِيدٌ","إِنَّهُۥ هُوَ يُبۡدِئُ وَيُعِيدُ","وَهُوَ ٱلۡغَفُورُ ٱلۡوَدُودُ","ذُو ٱلۡعَرۡشِ ٱلۡمَجِيدُ","فَعَّالٞ لِّمَا يُرِيدُ","هَلۡ أَتَىٰكَ حَدِيثُ ٱلۡجُنُودِ","فِرۡعَوۡنَ وَثَمُودَ","بَلِ ٱلَّذِينَ كَفَرُواْ فِي تَكۡذِيبٖ","وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطُۢ","بَلۡ هُوَ قُرۡءَانٞ مَّجِيدٞ","فِي لَوۡحٖ مَّحۡفُوظِۭ"]},"86":{"n":"الطارق","j":30,"a":["وَٱلسَّمَآءِ وَٱلطَّارِقِ","وَمَآ أَدۡرَىٰكَ مَا ٱلطَّارِقُ","ٱلنَّجۡمُ ٱلثَّاقِبُ","إِن كُلُّ نَفۡسٖ لَّمَّا عَلَيۡهَا حَافِظٞ","فَلۡيَنظُرِ ٱلۡإِنسَٰنُ مِمَّ خُلِقَ","خُلِقَ مِن مَّآءٖ دَافِقٖ","يَخۡرُجُ مِنۢ بَيۡنِ ٱلصُّلۡبِ وَٱلتَّرَآئِبِ","إِنَّهُۥ عَلَىٰ رَجۡعِهِۦ لَقَادِرٞ","يَوۡمَ تُبۡلَى ٱلسَّرَآئِرُ","فَمَا لَهُۥ مِن قُوَّةٖ وَلَا نَاصِرٖ","وَٱلسَّمَآءِ ذَاتِ ٱلرَّجۡعِ","وَٱلۡأَرۡضِ ذَاتِ ٱلصَّدۡعِ","إِنَّهُۥ لَقَوۡلٞ فَصۡلٞ","وَمَا هُوَ بِٱلۡهَزۡلِ","إِنَّهُمۡ يَكِيدُونَ كَيۡدٗا","وَأَكِيدُ كَيۡدٗا","فَمَهِّلِ ٱلۡكَٰفِرِينَ أَمۡهِلۡهُمۡ رُوَيۡدَۢا"]},"87":{"n":"الأعلى","j":30,"a":["سَبِّحِ ٱسۡمَ رَبِّكَ ٱلۡأَعۡلَى","ٱلَّذِي خَلَقَ فَسَوَّىٰ","وَٱلَّذِي قَدَّرَ فَهَدَىٰ","وَٱلَّذِيٓ أَخۡرَجَ ٱلۡمَرۡعَىٰ","فَجَعَلَهُۥ غُثَآءً أَحۡوَىٰ","سَنُقۡرِئُكَ فَلَا تَنسَىٰٓ","إِلَّا مَا شَآءَ ٱللَّهُۚ إِنَّهُۥ يَعۡلَمُ ٱلۡجَهۡرَ وَمَا يَخۡفَىٰ","وَنُيَسِّرُكَ لِلۡيُسۡرَىٰ","فَذَكِّرۡ إِن نَّفَعَتِ ٱلذِّكۡرَىٰ","سَيَذَّكَّرُ مَن يَخۡشَىٰ","وَيَتَجَنَّبُهَا ٱلۡأَشۡقَى","ٱلَّذِي يَصۡلَى ٱلنَّارَ ٱلۡكُبۡرَىٰ","ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ","قَدۡ أَفۡلَحَ مَن تَزَكَّىٰ","وَذَكَرَ ٱسۡمَ رَبِّهِۦ فَصَلَّىٰ","بَلۡ تُؤۡثِرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا","وَٱلۡأٓخِرَةُ خَيۡرٞ وَأَبۡقَىٰٓ","إِنَّ هَٰذَا لَفِي ٱلصُّحُفِ ٱلۡأُولَىٰ","صُحُفِ إِبۡرَٰهِيمَ وَمُوسَىٰ"]},"88":{"n":"الغاشية","j":30,"a":["هَلۡ أَتَىٰكَ حَدِيثُ ٱلۡغَٰشِيَةِ","وُجُوهٞ يَوۡمَئِذٍ خَٰشِعَةٌ","عَامِلَةٞ نَّاصِبَةٞ","تَصۡلَىٰ نَارًا حَامِيَةٗ","تُسۡقَىٰ مِنۡ عَيۡنٍ ءَانِيَةٖ","لَّيۡسَ لَهُمۡ طَعَامٌ إِلَّا مِن ضَرِيعٖ","لَّا يُسۡمِنُ وَلَا يُغۡنِي مِن جُوعٖ","وُجُوهٞ يَوۡمَئِذٖ نَّاعِمَةٞ","لِّسَعۡيِهَا رَاضِيَةٞ","فِي جَنَّةٍ عَالِيَةٖ","لَّا تَسۡمَعُ فِيهَا لَٰغِيَةٗ","فِيهَا عَيۡنٞ جَارِيَةٞ","فِيهَا سُرُرٞ مَّرۡفُوعَةٞ","وَأَكۡوَابٞ مَّوۡضُوعَةٞ","وَنَمَارِقُ مَصۡفُوفَةٞ","وَزَرَابِيُّ مَبۡثُوثَةٌ","أَفَلَا يَنظُرُونَ إِلَى ٱلۡإِبِلِ كَيۡفَ خُلِقَتۡ","وَإِلَى ٱلسَّمَآءِ كَيۡفَ رُفِعَتۡ","وَإِلَى ٱلۡجِبَالِ كَيۡفَ نُصِبَتۡ","وَإِلَى ٱلۡأَرۡضِ كَيۡفَ سُطِحَتۡ","فَذَكِّرۡ إِنَّمَآ أَنتَ مُذَكِّرٞ","لَّسۡتَ عَلَيۡهِم بِمُصَيۡطِرٍ","إِلَّا مَن تَوَلَّىٰ وَكَفَرَ","فَيُعَذِّبُهُ ٱللَّهُ ٱلۡعَذَابَ ٱلۡأَكۡبَرَ","إِنَّ إِلَيۡنَآ إِيَابَهُمۡ","ثُمَّ إِنَّ عَلَيۡنَا حِسَابَهُم"]},"89":{"n":"الفجر","j":30,"a":["وَٱلۡفَجۡرِ","وَلَيَالٍ عَشۡرٖ","وَٱلشَّفۡعِ وَٱلۡوَتۡرِ","وَٱلَّيۡلِ إِذَا يَسۡرِ","هَلۡ فِي ذَٰلِكَ قَسَمٞ لِّذِي حِجۡرٍ","أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِعَادٍ","إِرَمَ ذَاتِ ٱلۡعِمَادِ","ٱلَّتِي لَمۡ يُخۡلَقۡ مِثۡلُهَا فِي ٱلۡبِلَٰدِ","وَثَمُودَ ٱلَّذِينَ جَابُواْ ٱلصَّخۡرَ بِٱلۡوَادِ","وَفِرۡعَوۡنَ ذِي ٱلۡأَوۡتَادِ","ٱلَّذِينَ طَغَوۡاْ فِي ٱلۡبِلَٰدِ","فَأَكۡثَرُواْ فِيهَا ٱلۡفَسَادَ","فَصَبَّ عَلَيۡهِمۡ رَبُّكَ سَوۡطَ عَذَابٍ","إِنَّ رَبَّكَ لَبِٱلۡمِرۡصَادِ","فَأَمَّا ٱلۡإِنسَٰنُ إِذَا مَا ٱبۡتَلَىٰهُ رَبُّهُۥ فَأَكۡرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّيٓ أَكۡرَمَنِ","وَأَمَّآ إِذَا مَا ٱبۡتَلَىٰهُ فَقَدَرَ عَلَيۡهِ رِزۡقَهُۥ فَيَقُولُ رَبِّيٓ أَهَٰنَنِ","كـَلَّاۖ بَل لَّا تُكۡرِمُونَ ٱلۡيَتِيمَ","وَلَا تَحَٰٓضُّونَ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ","وَتَأۡكُلُونَ ٱلتُّرَاثَ أَكۡلٗا لَّمّٗا","وَتُحِبُّونَ ٱلۡمَالَ حُبّٗا جَمّٗا","كـَلَّآۖ إِذَا دُكَّتِ ٱلۡأَرۡضُ دَكّٗا دَكّٗا","وَجَآءَ رَبُّكَ وَٱلۡمَلَكُ صَفّٗا صَفّٗا","وَجِاْيٓءَ يَوۡمَئِذِۭ بِجَهَنَّمَۚ يَوۡمَئِذٖ يَتَذَكَّرُ ٱلۡإِنسَٰنُ وَأَنَّىٰ لَهُ ٱلذِّكۡرَىٰ","يَقُولُ يَٰلَيۡتَنِي قَدَّمۡتُ لِحَيَاتِي","فَيَوۡمَئِذٖ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدٞ","وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدٞ","يَٰٓأَيَّتُهَا ٱلنَّفۡسُ ٱلۡمُطۡمَئِنَّةُ","ٱرۡجِعِيٓ إِلَىٰ رَبِّكِ رَاضِيَةٗ مَّرۡضِيَّةٗ","فَٱدۡخُلِي فِي عِبَٰدِي","وَٱدۡخُلِي جَنَّتِي"]},"90":{"n":"البلد","j":30,"a":["لَآ أُقۡسِمُ بِهَٰذَا ٱلۡبَلَدِ","وَأَنتَ حِلُّۢ بِهَٰذَا ٱلۡبَلَدِ","وَوَالِدٖ وَمَا وَلَدَ","لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِي كَبَدٍ","أَيَحۡسَبُ أَن لَّن يَقۡدِرَ عَلَيۡهِ أَحَدٞ","يَقُولُ أَهۡلَكۡتُ مَالٗا لُّبَدًا","أَيَحۡسَبُ أَن لَّمۡ يَرَهُۥٓ أَحَدٌ","أَلَمۡ نَجۡعَل لَّهُۥ عَيۡنَيۡنِ","وَلِسَانٗا وَشَفَتَيۡنِ","وَهَدَيۡنَٰهُ ٱلنَّجۡدَيۡنِ","فَلَا ٱقۡتَحَمَ ٱلۡعَقَبَةَ","وَمَآ أَدۡرَىٰكَ مَا ٱلۡعَقَبَةُ","فَكُّ رَقَبَةٍ","أَوۡ إِطۡعَٰمٞ فِي يَوۡمٖ ذِي مَسۡغَبَةٖ","يَتِيمٗا ذَا مَقۡرَبَةٍ","أَوۡ مِسۡكِينٗا ذَا مَتۡرَبَةٖ","ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُواْ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ وَتَوَاصَوۡاْ بِٱلۡمَرۡحَمَةِ","أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡمَيۡمَنَةِ","وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِنَا هُمۡ أَصۡحَٰبُ ٱلۡمَشۡـَٔمَةِ","عَلَيۡهِمۡ نَارٞ مُّؤۡصَدَةُۢ"]},"91":{"n":"الشمس","j":30,"a":["وَٱلشَّمۡسِ وَضُحَىٰهَا","وَٱلۡقَمَرِ إِذَا تَلَىٰهَا","وَٱلنَّهَارِ إِذَا جَلَّىٰهَا","وَٱلَّيۡلِ إِذَا يَغۡشَىٰهَا","وَٱلسَّمَآءِ وَمَا بَنَىٰهَا","وَٱلۡأَرۡضِ وَمَا طَحَىٰهَا","وَنَفۡسٖ وَمَا سَوَّىٰهَا","فَأَلۡهَمَهَا فُجُورَهَا وَتَقۡوَىٰهَا","قَدۡ أَفۡلَحَ مَن زَكَّىٰهَا","وَقَدۡ خَابَ مَن دَسَّىٰهَا","كَذَّبَتۡ ثَمُودُ بِطَغۡوَىٰهَآ","إِذِ ٱنۢبَعَثَ أَشۡقَىٰهَا","فَقَالَ لَهُمۡ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقۡيَٰهَا","فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمۡدَمَ عَلَيۡهِمۡ رَبُّهُم بِذَنۢبِهِمۡ فَسَوَّىٰهَا","وَلَا يَخَافُ عُقۡبَٰهَا"]},"92":{"n":"الليل","j":30,"a":["وَٱلَّيۡلِ إِذَا يَغۡشَىٰ","وَٱلنَّهَارِ إِذَا تَجَلَّىٰ","وَمَا خَلَقَ ٱلذَّكَرَ وَٱلۡأُنثَىٰٓ","إِنَّ سَعۡيَكُمۡ لَشَتَّىٰ","فَأَمَّا مَنۡ أَعۡطَىٰ وَٱتَّقَىٰ","وَصَدَّقَ بِٱلۡحُسۡنَىٰ","فَسَنُيَسِّرُهُۥ لِلۡيُسۡرَىٰ","وَأَمَّا مَنۢ بَخِلَ وَٱسۡتَغۡنَىٰ","وَكَذَّبَ بِٱلۡحُسۡنَىٰ","فَسَنُيَسِّرُهُۥ لِلۡعُسۡرَىٰ","وَمَا يُغۡنِي عَنۡهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ","إِنَّ عَلَيۡنَا لَلۡهُدَىٰ","وَإِنَّ لَنَا لَلۡأٓخِرَةَ وَٱلۡأُولَىٰ","فَأَنذَرۡتُكُمۡ نَارٗا تَلَظَّىٰ","لَا يَصۡلَىٰهَآ إِلَّا ٱلۡأَشۡقَى","ٱلَّذِي كَذَّبَ وَتَوَلَّىٰ","وَسَيُجَنَّبُهَا ٱلۡأَتۡقَى","ٱلَّذِي يُؤۡتِي مَالَهُۥ يَتَزَكَّىٰ","وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعۡمَةٖ تُجۡزَىٰٓ","إِلَّا ٱبۡتِغَآءَ وَجۡهِ رَبِّهِ ٱلۡأَعۡلَىٰ","وَلَسَوۡفَ يَرۡضَىٰ"]},"93":{"n":"الضحى","j":30,"a":["وَٱلضُّحَىٰ","وَٱلَّيۡلِ إِذَا سَجَىٰ","مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ","وَلَلۡأٓخِرَةُ خَيۡرٞ لَّكَ مِنَ ٱلۡأُولَىٰ","وَلَسَوۡفَ يُعۡطِيكَ رَبُّكَ فَتَرۡضَىٰٓ","أَلَمۡ يَجِدۡكَ يَتِيمٗا فَـَٔاوَىٰ","وَوَجَدَكَ ضَآلّٗا فَهَدَىٰ","وَوَجَدَكَ عَآئِلٗا فَأَغۡنَىٰ","فَأَمَّا ٱلۡيَتِيمَ فَلَا تَقۡهَرۡ","وَأَمَّا ٱلسَّآئِلَ فَلَا تَنۡهَرۡ","وَأَمَّا بِنِعۡمَةِ رَبِّكَ فَحَدِّثۡ"]},"94":{"n":"الشرح","j":30,"a":["أَلَمۡ نَشۡرَحۡ لَكَ صَدۡرَكَ","وَوَضَعۡنَا عَنكَ وِزۡرَكَ","ٱلَّذِيٓ أَنقَضَ ظَهۡرَكَ","وَرَفَعۡنَا لَكَ ذِكۡرَكَ","فَإِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرًا","إِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرٗا","فَإِذَا فَرَغۡتَ فَٱنصَبۡ","وَإِلَىٰ رَبِّكَ فَٱرۡغَب"]},"95":{"n":"التين","j":30,"a":["وَٱلتِّينِ وَٱلزَّيۡتُونِ","وَطُورِ سِينِينَ","وَهَٰذَا ٱلۡبَلَدِ ٱلۡأَمِينِ","لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِيٓ أَحۡسَنِ تَقۡوِيمٖ","ثُمَّ رَدَدۡنَٰهُ أَسۡفَلَ سَٰفِلِينَ","إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَلَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونٖ","فَمَا يُكَذِّبُكَ بَعۡدُ بِٱلدِّينِ","أَلَيۡسَ ٱللَّهُ بِأَحۡكَمِ ٱلۡحَٰكِمِينَ"]},"96":{"n":"العلق","j":30,"a":["ٱقۡرَأۡ بِٱسۡمِ رَبِّكَ ٱلَّذِي خَلَقَ","خَلَقَ ٱلۡإِنسَٰنَ مِنۡ عَلَقٍ","ٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ","ٱلَّذِي عَلَّمَ بِٱلۡقَلَمِ","عَلَّمَ ٱلۡإِنسَٰنَ مَا لَمۡ يَعۡلَمۡ","كـَلَّآ إِنَّ ٱلۡإِنسَٰنَ لَيَطۡغَىٰٓ","أَن رَّءَاهُ ٱسۡتَغۡنَىٰٓ","إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجۡعَىٰٓ","أَرَءَيۡتَ ٱلَّذِي يَنۡهَىٰ","عَبۡدًا إِذَا صَلَّىٰٓ","أَرَءَيۡتَ إِن كَانَ عَلَى ٱلۡهُدَىٰٓ","أَوۡ أَمَرَ بِٱلتَّقۡوَىٰٓ","أَرَءَيۡتَ إِن كَذَّبَ وَتَوَلَّىٰٓ","أَلَمۡ يَعۡلَم بِأَنَّ ٱللَّهَ يَرَىٰ","كـَلَّا لَئِن لَّمۡ يَنتَهِ لَنَسۡفَعَۢا بِٱلنَّاصِيَةِ","نَاصِيَةٖ كَٰذِبَةٍ خَاطِئَةٖ","فَلۡيَدۡعُ نَادِيَهُۥ","سَنَدۡعُ ٱلزَّبَانِيَةَ","كـَلَّا لَا تُطِعۡهُ وَٱسۡجُدۡۤ وَٱقۡتَرِب۩"]},"97":{"n":"القدر","j":30,"a":["إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةِ ٱلۡقَدۡرِ","وَمَآ أَدۡرَىٰكَ مَا لَيۡلَةُ ٱلۡقَدۡرِ","لَيۡلَةُ ٱلۡقَدۡرِ خَيۡرٞ مِّنۡ أَلۡفِ شَهۡرٖ","تَنَزَّلُ ٱلۡمَلَٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذۡنِ رَبِّهِم مِّن كُلِّ أَمۡرٖ","سَلَٰمٌ هِيَ حَتَّىٰ مَطۡلَعِ ٱلۡفَجۡرِ"]},"98":{"n":"البينة","j":30,"a":["لَمۡ يَكُنِ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأۡتِيَهُمُ ٱلۡبَيِّنَةُ","رَسُولٞ مِّنَ ٱللَّهِ يَتۡلُواْ صُحُفٗا مُّطَهَّرَةٗ","فِيهَا كُتُبٞ قَيِّمَةٞ","وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَةُ","وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُواْ ٱلصَّلَوٰةَ وَيُؤۡتُواْ ٱلزَّكَوٰةَۚ وَذَٰلِكَ دِينُ ٱلۡقَيِّمَةِ","إِنَّ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ فِي نَارِ جَهَنَّمَ خَٰلِدِينَ فِيهَآۚ أُوْلَٰٓئِكَ هُمۡ شَرُّ ٱلۡبَرِيَّةِ","إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أُوْلَٰٓئِكَ هُمۡ خَيۡرُ ٱلۡبَرِيَّةِ","جَزَآؤُهُمۡ عِندَ رَبِّهِمۡ جَنَّٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ لِمَنۡ خَشِيَ رَبَّهُۥ"]},"99":{"n":"الزلزلة","j":30,"a":["إِذَا زُلۡزِلَتِ ٱلۡأَرۡضُ زِلۡزَالَهَا","وَأَخۡرَجَتِ ٱلۡأَرۡضُ أَثۡقَالَهَا","وَقَالَ ٱلۡإِنسَٰنُ مَا لَهَا","يَوۡمَئِذٖ تُحَدِّثُ أَخۡبَارَهَا","بِأَنَّ رَبَّكَ أَوۡحَىٰ لَهَا","يَوۡمَئِذٖ يَصۡدُرُ ٱلنَّاسُ أَشۡتَاتٗا لِّيُرَوۡاْ أَعۡمَٰلَهُمۡ","فَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرٗا يَرَهُۥ","وَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٖ شَرّٗا يَرَهُۥ"]},"100":{"n":"العاديات","j":30,"a":["وَٱلۡعَٰدِيَٰتِ ضَبۡحٗا","فَٱلۡمُورِيَٰتِ قَدۡحٗا","فَٱلۡمُغِيرَٰتِ صُبۡحٗا","فَأَثَرۡنَ بِهِۦ نَقۡعٗا","فَوَسَطۡنَ بِهِۦ جَمۡعًا","إِنَّ ٱلۡإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٞ","وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٞ","وَإِنَّهُۥ لِحُبِّ ٱلۡخَيۡرِ لَشَدِيدٌ","أَفَلَا يَعۡلَمُ إِذَا بُعۡثِرَ مَا فِي ٱلۡقُبُورِ","وَحُصِّلَ مَا فِي ٱلصُّدُورِ","إِنَّ رَبَّهُم بِهِمۡ يَوۡمَئِذٖ لَّخَبِيرُۢ"]},"101":{"n":"القارعة","j":30,"a":["ٱلۡقَارِعَةُ","مَا ٱلۡقَارِعَةُ","وَمَآ أَدۡرَىٰكَ مَا ٱلۡقَارِعَةُ","يَوۡمَ يَكُونُ ٱلنَّاسُ كَٱلۡفَرَاشِ ٱلۡمَبۡثُوثِ","وَتَكُونُ ٱلۡجِبَالُ كَٱلۡعِهۡنِ ٱلۡمَنفُوشِ","فَأَمَّا مَن ثَقُلَتۡ مَوَٰزِينُهُۥ","فَهُوَ فِي عِيشَةٖ رَّاضِيَةٖ","وَأَمَّا مَنۡ خَفَّتۡ مَوَٰزِينُهُۥ","فَأُمُّهُۥ هَاوِيَةٞ","وَمَآ أَدۡرَىٰكَ مَا هِيَهۡ","نَارٌ حَامِيَةُۢ"]},"102":{"n":"التكاثر","j":30,"a":["أَلۡهَىٰكُمُ ٱلتَّكَاثُرُ","حَتَّىٰ زُرۡتُمُ ٱلۡمَقَابِرَ","كـَلَّا سَوۡفَ تَعۡلَمُونَ","ثُمَّ كـَلَّا سَوۡفَ تَعۡلَمُونَ","كـَلَّا لَوۡ تَعۡلَمُونَ عِلۡمَ ٱلۡيَقِينِ","لَتَرَوُنَّ ٱلۡجَحِيمَ","ثُمَّ لَتَرَوُنَّهَا عَيۡنَ ٱلۡيَقِينِ","ثُمَّ لَتُسۡـَٔلُنَّ يَوۡمَئِذٍ عَنِ ٱلنَّعِيمِ"]},"103":{"n":"العصر","j":30,"a":["وَٱلۡعَصۡرِ","إِنَّ ٱلۡإِنسَٰنَ لَفِي خُسۡرٍ","إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَتَوَاصَوۡاْ بِٱلۡحَقِّ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ"]},"104":{"n":"الهمزة","j":30,"a":["وَيۡلٞ لِّكُلِّ هُمَزَةٖ لُّمَزَةٍ","ٱلَّذِي جَمَعَ مَالٗا وَعَدَّدَهُۥ","يَحۡسَبُ أَنَّ مَالَهُۥٓ أَخۡلَدَهُۥ","كـَلَّاۖ لَيُنۢبَذَنَّ فِي ٱلۡحُطَمَةِ","وَمَآ أَدۡرَىٰكَ مَا ٱلۡحُطَمَةُ","نَارُ ٱللَّهِ ٱلۡمُوقَدَةُ","ٱلَّتِي تَطَّلِعُ عَلَى ٱلۡأَفۡـِٔدَةِ","إِنَّهَا عَلَيۡهِم مُّؤۡصَدَةٞ","فِي عَمَدٖ مُّمَدَّدَةِۭ"]},"105":{"n":"الفيل","j":30,"a":["أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِأَصۡحَٰبِ ٱلۡفِيلِ","أَلَمۡ يَجۡعَلۡ كَيۡدَهُمۡ فِي تَضۡلِيلٖ","وَأَرۡسَلَ عَلَيۡهِمۡ طَيۡرًا أَبَابِيلَ","تَرۡمِيهِم بِحِجَارَةٖ مِّن سِجِّيلٖ","فَجَعَلَهُمۡ كَعَصۡفٖ مَّأۡكُولِۭ"]},"106":{"n":"قريش","j":30,"a":["لِإِيلَٰفِ قُرَيۡشٍ","إِۦلَٰفِهِمۡ رِحۡلَةَ ٱلشِّتَآءِ وَٱلصَّيۡفِ","فَلۡيَعۡبُدُواْ رَبَّ هَٰذَا ٱلۡبَيۡتِ","ٱلَّذِيٓ أَطۡعَمَهُم مِّن جُوعٖ وَءَامَنَهُم مِّنۡ خَوۡفِۭ"]},"107":{"n":"الماعون","j":30,"a":["أَرَءَيۡتَ ٱلَّذِي يُكَذِّبُ بِٱلدِّينِ","فَذَٰلِكَ ٱلَّذِي يَدُعُّ ٱلۡيَتِيمَ","وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ","فَوَيۡلٞ لِّلۡمُصَلِّينَ","ٱلَّذِينَ هُمۡ عَن صَلَاتِهِمۡ سَاهُونَ","ٱلَّذِينَ هُمۡ يُرَآءُونَ","وَيَمۡنَعُونَ ٱلۡمَاعُونَ"]},"108":{"n":"الكوثر","j":30,"a":["إِنَّآ أَعۡطَيۡنَٰكَ ٱلۡكَوۡثَرَ","فَصَلِّ لِرَبِّكَ وَٱنۡحَرۡ","إِنَّ شَانِئَكَ هُوَ ٱلۡأَبۡتَرُ"]},"109":{"n":"الكافرون","j":30,"a":["قُلۡ يَٰٓأَيُّهَا ٱلۡكَٰفِرُونَ","لَآ أَعۡبُدُ مَا تَعۡبُدُونَ","وَلَآ أَنتُمۡ عَٰبِدُونَ مَآ أَعۡبُدُ","وَلَآ أَنَا۠ عَابِدٞ مَّا عَبَدتُّمۡ","وَلَآ أَنتُمۡ عَٰبِدُونَ مَآ أَعۡبُدُ","لَكُمۡ دِينُكُمۡ وَلِيَ دِينِ"]},"110":{"n":"النصر","j":30,"a":["إِذَا جَآءَ نَصۡرُ ٱللَّهِ وَٱلۡفَتۡحُ","وَرَأَيۡتَ ٱلنَّاسَ يَدۡخُلُونَ فِي دِينِ ٱللَّهِ أَفۡوَاجٗا","فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَٱسۡتَغۡفِرۡهُۚ إِنَّهُۥ كَانَ تَوَّابَۢا"]},"111":{"n":"المسد","j":30,"a":["تَبَّتۡ يَدَآ أَبِي لَهَبٖ وَتَبَّ","مَآ أَغۡنَىٰ عَنۡهُ مَالُهُۥ وَمَا كَسَبَ","سَيَصۡلَىٰ نَارٗا ذَاتَ لَهَبٖ","وَٱمۡرَأَتُهُۥ حَمَّالَةَ ٱلۡحَطَبِ","فِي جِيدِهَا حَبۡلٞ مِّن مَّسَدِۭ"]},"112":{"n":"الإخلاص","j":30,"a":["قُلۡ هُوَ ٱللَّهُ أَحَدٌ","ٱللَّهُ ٱلصَّمَدُ","لَمۡ يَلِدۡ وَلَمۡ يُولَدۡ","وَلَمۡ يَكُن لَّهُۥ كُفُوًا أَحَدُۢ"]},"113":{"n":"الفلق","j":30,"a":["قُلۡ أَعُوذُ بِرَبِّ ٱلۡفَلَقِ","مِن شَرِّ مَا خَلَقَ","وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ","وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِي ٱلۡعُقَدِ","وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ"]},"114":{"n":"الناس","j":30,"a":["قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ","مَلِكِ ٱلنَّاسِ","إِلَٰهِ ٱلنَّاسِ","مِن شَرِّ ٱلۡوَسۡوَاسِ ٱلۡخَنَّاسِ","ٱلَّذِي يُوَسۡوِسُ فِي صُدُورِ ٱلنَّاسِ","مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ"]}}}};
